MultiLanguageItemData['de'][62348] = {name = "[q3]Terraths Signet des Gleichgewichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Beweglichkeit\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nBenötigtTherazane\n- Respektvoll\n[q]\"Wenn die Erde still wird, der Lärm verstummt und sich Eure Konzentration verschärft, zielt genau. -Terrath der Beständige\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62350] = {name = "[q3]Gorsiks Band der Zerschlagung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 2.\nBenötigtTherazane\n- Respektvoll\n[q]\"Die Erde bebt, und Eure Feinde erzittern. Ihr erscheint, und die Zerstörung ist an Eurer Seite. - Gorsik der Tosende\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62351] = {name = "[q3]Felsens Ring der Entschlossenheit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Stärke\n+3 Ausdauer\n[q2]+ 2 Ausweichen\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nBenötigtTherazane\n- Respektvoll\n[q]\"Winde, Erde und Stürme mögen auf Euren Körper prallen, doch allein Euer Wille wird Euch auf den Beinen halten. -Felsen der Ausdauernde\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62352] = {name = "[q3]Diamants Ring der Mäßigung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 2.\nBenötigtTherazane\n- Respektvoll\n[q]\"Alle Seelen zeigen ihre wahre Natur, wenn man ihnen vertraut, selbst wenn das Vertrauen ungerechtfertigt ist. -Diamant der Geduldige\"\nVerkaufspreis:"}
