MultiLanguageItemData['de'][62559] = {name = "Glückskarte", additional_info = "[q]\"Vertraut auf das Licht, aber behaltet Euer Reittier im Auge.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62560] = {name = "Glückskarte", additional_info = "[q]\"Steht nie im Schatten von Drachen.\"\nVerkaufspreis:"}
