MultiLanguageItemData['de'][62575] = {name = "Glückskarte", additional_info = "[q]\"Ihr habt viele verborgene Talente. Mit mehr Erfahrung werdet Ihr noch mehr hinzugewinnen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62576] = {name = "Glückskarte", additional_info = "[q]\"Wer eine ganze Armee bekämpft, ist ein Märtyrer; Wer gegen fünf auf einmal kämpft, ist die Elite.\"\nVerkaufspreis:"}
