MultiLanguageItemData['de'][62578] = {name = "Glückskarte", additional_info = "[q]\"All Eure Mühen sind die Reparaturkosten wert.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62579] = {name = "Glückskarte", additional_info = "[q]\"Vertraut niemals einem Troll. Und auch keinem Schurken. Besonders keinem Trollschurken.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62580] = {name = "Glückskarte", additional_info = "[q]\"Ungläubigkeit zerstört die Magie.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62581] = {name = "Glückskarte", additional_info = "[q]\"Die Gelegenheit ist günstig, etwas neues zu probieren. Vielleicht einen neuen Beruf.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62582] = {name = "Glückskarte", additional_info = "[q]\"Jede Pflanze blüht dann auf, wenn die Zeit reif ist. Und dann pflückt Ihr sie!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][62583] = {name = "Glückskarte", additional_info = "[q]\"Geht und ruht Euch aus. Ihr habt es Euch verdient. Aber vergesst nicht, in einem Gasthaus auszuruhen!\"\nVerkaufspreis:"}
