MultiLanguageItemData['de'][62799] = {name = "[q3]Rezept: Gebratenes Drachenfestmahl", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man ein gebratenes Drachenfestmahl zubereitet.\nBenötigt Kochkunst des Kataklysmus (50)\nVerkaufspreis: \nGebratenes Drachenfestmahl\nWird beim Aufheben gebunden\n[q2]Benutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Drachenfestmahl her! Stellt im Verlauf von 30 Sek. 6510 Gesundheit und ( 1118 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 9 Ausdauer und ein für Euch nützlicher Wert wird um 9 erhöht.\nVerkaufspreis:\nBenötigt Drachenflanke (3), Zarter Flügel (2)"}
MultiLanguageItemData['de'][62800] = {name = "[q3]Rezept: Meeresfrüchtefestmahl Magnifique", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man ein Meeresfrüchtefestmahl Magnifique zubereitet.\nBenötigt Kochkunst des Kataklysmus (75)\nVerkaufspreis: \nMeeresfrüchtefestmahl Magnifique\nWird beim Aufheben gebunden\n[q2]Benutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Meeresfrüchtefestmahl Magnifique her! Stellt im Verlauf von 30 Sek. 8944 Gesundheit und ( 1375 / 5 * 30) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 15 Ausdauer und ein für Euch nützlicher Wert wird um 15 erhöht.\nVerkaufspreis:\nBenötigt Hochlandguppy (2), Lavaschuppenwels (2), Klafteraal (2)"}
