MultiLanguageItemData['de'][63039] = {name = "[q4]Zügel des Drachen des Westwinds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört einen reitbaren Drachen des Westwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtWächter von Baradin\n- Ehrfürchtig\n\n\n[q]\"Diese majestätischen Bestien nutzen die elementaren Kräfte des Sturms, knistern wie Blitze und brüllen wie der Donner.\"\nVerkäufer:\nRüstmeister Brazie\nZone:\nHalbinsel von Tol Barad\nFraktion:\nWächter von Baradin - Ehrfürchtig"}
MultiLanguageItemData['de'][63040] = {name = "[q4]Zügel des Drachen des Nordwinds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört einen reitbaren Drachen des Nordwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wer den Sturm kennt wird der Ruhe überdrüssig.\"\nBeute von:\nAltairus\nZone:\nDer Vortexgipfel"}
MultiLanguageItemData['de'][63041] = {name = "[q4]Zügel des Drachen des Südwinds", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört einen reitbaren Drachen des Südwinds und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wie eine zarte Brise im Sommer. Aber das will nicht viel heißen, wenn man bedenkt, woher sie kommt. - Itesh\"\nBeute von:\nAl'Akir\nZone:\nThron der Vier Winde"}
MultiLanguageItemData['de'][63042] = {name = "[q4]Zügel des Phosphorsteindrachen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört einen reitbaren Phosphorsteindrachen und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Steinmutter hat sich nie viele Gedanken über den rebellischen Aeonaxx gemacht und sogar zugelassen, dass seine Brut ihr Reich verlässt.\"\nBeute von:\nAeonaxx\nOrt:\nTiefenheim"}
MultiLanguageItemData['de'][63043] = {name = "[q4]Zügel des Vitriolsteindrachen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört einen reitbaren Vitriolsteindrachen und gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die wären perfekt für einen Anhänger geeignet, und das da würde einen fantastischen Ring ergeben. Lasst mich wissen, wenn das Ding sich häutet oder so. - Kalinda\"\nBeute von:\nPlattenhaut\nZone:\nDer Steinerne Kern"}
MultiLanguageItemData['de'][63044] = {name = "[q4]Zügel des braunen Reitkamels", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört ein reitbares braunes Reitkamel oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtRamkahen\n- Ehrfürchtig\n\n\n[q]\"An einem einzigen Nachmittag hat Fennimore Quigley als Erster ein Kamel gemolken und kurz darauf auch noch den Rekord für den längsten unbeabsichtigten Flug gebrochen.\"\nVerkäufer:\nSchmied Abasi\nZone:\nUldum\nFraktion:\nRamkahen - Ehrfürchtig\nKosten:"}
