MultiLanguageItemData['de'][66100] = {name = "Pläne: Gürtelschnalle aus Schwarzstahl", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung einer Gürtelschnalle aus Schwarzstahl.\n[q2]Kann nicht auf Gegenstände über Stufe 49 angewandt werden.\nBenötigt Schmiedekunst des Kataklysmus (75)\n\n\n[q3]Gürtelschnalle aus Schwarzstahl\n[q2]Benutzen: Bringt dauerhaft eine Gürtelschnalle aus Schwarzstahl an einem Gürtel an und fügt ihm so einen Sockel hinzu.\n\n Durch das Anbringen der Gürtelschnalle wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände der Stufe 0 oder höher angewandt werden.\nVerkaufspreis: \nBenötigt Flüchtige Erde (4), Elementiumbarren (4), Pyriumbarren (4)"}
MultiLanguageItemData['de'][66101] = {name = "Pläne: Pyriumschildstachel", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Pyriumschildstachels.\nBenötigt Schmiedekunst des Kataklysmus (75)\n\n\n[q3]Pyriumschildstachel\nWird beim Anlegen gebunden\n[q2]Benutzen: Bringt einen Pyriumstachel an Eurem Schild an, der beim Blocken manchmal 42 Schaden verursacht.\n\n Durch das Anbringen des Pyriumschildstachels wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Pyriumbarren (5)"}
