MultiLanguageItemData['de'][68793] = {name = "[q0]Ausgebrannte Glyphe", additional_info = "Klassen: Todesritter\n[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][68795] = {name = "Stendels Ruin", additional_info = "Wird beim Aufheben gebunden\n[q]\"Dieser riesige, aufgeblähte Wels ist Stendel jahrelang entkommen und mit Narben übersät. Er scheint fast zu grinsen.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][68796] = {name = "Verstärkte Angelschnur", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Ersetzt die Angelschnur Eurer Angelrute mit einer etwas festeren, wodurch die Angelfertigkeit dauerhaft um 1 erhöht wird. Kann nicht auf Gegenstände über Stufe 0 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][68797] = {name = "[q3]Stendels Ehering", additional_info = "Wird beim Anlegen gebunden\nFinger\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\nVerkaufspreis:"}
MultiLanguageItemData['de'][68806] = {name = "[q3]Kalythas Spukmedaillon", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Ladet den Geist von Kalytha ein, von Euch Besitz zu ergreifen. (15 Min Abklingzeit)"}
MultiLanguageItemData['de'][68808] = {name = "Ruhestein des Helden", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Teleportiert Euch sofort zum \"Zum Goldenen Fass\" in Sturmwind. Kann nur einmal benutzt werden.\n[q]\"Vergesst nicht, Euren eigenen Ruhestein zu binden, wenn Ihr in Sturmwind seid!\""}
MultiLanguageItemData['de'][68809] = {name = "Ruhestein des Veteranen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Teleportiert Euch sofort zum Tal der Weisheit in Orgrimmar. Kann nur einmal benutzt werden.\n[q]\"Vergesst nicht, Euren eigenen Ruhestein zu binden, wenn Ihr in Orgrimmar seid!\""}
MultiLanguageItemData['de'][68812] = {name = "[q4]Hornissenstichband", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+2 Beweglichkeit\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nVerkaufspreis:"}
MultiLanguageItemData['de'][68813] = {name = "[q3]Ranzen mit frisch gepflückten Kräutern", additional_info = "Wird beim Aufheben gebunden\n[q]\"Enthält eine Auswahl von 20 zufälligen Cataclysm-Kräutern\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][68820] = {name = "Stotterspritters Blaupausen", additional_info = "Questgegenstand\n[q]\"Die Blaupausen enthalten eine detaillierte Anleitung zum Bau der Silberblitz X-831.\""}
MultiLanguageItemData['de'][68823] = {name = "[q4]Gepanzerter Razzashiraptor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen reitbaren gepanzerten Razzashiraptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die reinrassigen königlichen Raptoren von Zul'Gurub sind im Schlingendorntal zu einer Seltenheit geworden. Wenn die Gurubashi jemand anderen als einen Troll auf einem ihrer geliebten Tiere erblicken, steigern sie sich in einen Blutrausch.\"\nBeute von:\nBlutfürst Mandokir\nZone:\nZul'Gurub"}
MultiLanguageItemData['de'][68824] = {name = "[q4]Schneller zulianischer Panther", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört einen schnellen zulianischen Panther oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Pantherfangzähne sind schon seit langer Zeit bei den Dschungeltrollen begehrt. Sie werden in Ritualen oder als Zutaten von Mojos verwendet.\"\nBeute von:\nHohepriesterin Kilnara\nZone:\nZul'Gurub"}
MultiLanguageItemData['de'][68825] = {name = "[q4]Drachenfalke der Amani", additional_info = "Einzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört einen reitbaren Drachenfalken der Amani oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Drachenfalken, die aus der Versklavung durch Trolle befreit wurden, gehören zu den treuesten ihrer Art.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht"}
MultiLanguageItemData['de'][68833] = {name = "[q3]Pantherjunges", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euer Pantherjunges beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][68837] = {name = "Dämonensaat", additional_info = "Questgegenstand\n[q]\"Leuchtet mit dämonischer Energie.\""}
MultiLanguageItemData['de'][68840] = {name = "[q3]Landros Lichling", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Landros Lichling beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][68841] = {name = "[q3]Nachtsäblerjunges", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euer Nachtsäblerjunges beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][68890] = {name = "Doppelpack Papierdrachen", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Lasst mit Eurem Waisenkind einen Papierdrachen steigen. (30 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68915] = {name = "[q4]Waagschalen des Lebens", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Waagschalen des Lebens (1)\nSchmuck\n+6 Ausdauer\n[q2]Anlegen: Speichert bis zu 511 zusätzliche Gesundheit aus Zaubern, die Euch über Eure maximale Gesundheit hinaus heilen.\n[q2]Benutzen: Gibt sofort alle auf den Waagschalen des Lebens angesammelte Gesundheit als Selbstheilung frei. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68925] = {name = "[q4]Wechselimpulsblitzkondensator", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Wechselimpulsblitzkondensator (1)\nSchmuck\n+4 Intelligenz\n[q2]Anlegen: Ihr erhaltet eine elektrische Aufladung, wann immer Ihr einen kritischen Zaubertreffer erzielt, was eine Chance verleiht, einen 'Blitzschlag' abzufeuern, der pro gesammelter 'Elektrischer Aufladung' ( 9 * 0.875) bis ( 9 * 1.125) Schaden verursacht. Ihr könnt nicht mehr als 10 'Elektrische Aufladungen' ansammeln und könnt nicht mehr als einmal alle 2,5 Sek. eine erhalten. (2.5s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68926] = {name = "[q4]Fänge des Schicksals", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Fänge des Schicksals (1)\nSchmuck\n+4 Intelligenz\n[q2]Benutzen: Die nächsten 10 Zauber, die innerhalb der nächsten 20 Sek. gewirkt werden, verringern die Kosten Eurer Heilig- und Naturzauber um 1 . Bis zu 10-mal stapelbar. (900ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68927] = {name = "[q4]Der Hungerleider", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Der Hungerleider (1)\nSchmuck\n+4 Beweglichkeit\n[q2]Anlegen: Eure Nahkampf- und Distanzangriffe gewähren eine Chance, Euer Tempo 15 Sek. lang um 22 zu erhöhen. (1Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68937] = {name = "Düsterhammers Stiefel", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Diese Stiefel haben schon bessere Tage gesehen.\""}
MultiLanguageItemData['de'][68955] = {name = "Totem von Tortolla", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Umhüllt Euch 10 Sek. lang mit einem undurchdringlichen Panzer. (20 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][68972] = {name = "[q4]Apparat von Khaz'goroth", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Apparat von Khaz'goroth (1)\nSchmuck\n+4 Stärke\n[q2]Anlegen: Eure kritischen Nahkampftreffer gewähren Euch Titanische Kraft, mit der Ihr diesen Apparat betreiben könnt. Die Titanische Kraft ist bis zu 5-mal stapelbar und hält 30 Sek. lang an.\n[q2]Benutzen: Zehrt sämtliche Titanische Kraft auf, um Euren kritischen Trefferwert, Euer Tempo oder Eure Meisterschaft pro angesammelter Titanischer Kraft um 5 zu erhöhen. Hält 15 Sek. lang an. Der Apparat wird immer den höchsten dieser drei Werte auswählen. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68981] = {name = "[q4]Spinnenseidenspindel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Spinnenseidenspindel (1)\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n[q2]Anlegen: Nahkampfangriffe, die Eure Gesundheit unter 35% fallenlassen, verleihen Euch einen Schutzschild, der 30 Sek. lang 437 Schaden absorbiert. Kann nicht öfter als ein Mal pro Minute auftreten. (1Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68982] = {name = "[q4]Nekromantischer Fokus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Nekromantischer Fokus (1)\nSchmuck\n+4 Intelligenz\n[q2]Anlegen: Jedes Mal, wenn Eure regelmäßigen Zauber Schaden verursachen, wird Eure Meisterschaft 10 Sek. lang um 1 erhöht. Bis zu 10-mal stapelbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][68983] = {name = "[q4]Auge der lodernden Kraft", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Auge der lodernden Kraft (1)\nSchmuck\n+4 Intelligenz\n[q2]Anlegen: Eure Heilzauber haben eine Chance, das am schwersten verletzte nahe Gruppenmitglied um 87 zu heilen. (Procchance: 10%, 45s Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68994] = {name = "[q4]Matrixrestabilisator", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Matrixrestabilisator (1)\nSchmuck\n+4 Beweglichkeit\n[q2]Anlegen: Eure Nahkampf- und Distanzangriffe haben eine Chance, Euren kritischen Trefferwert, Euer Tempo oder Eure Meisterschaft (je nachdem, welcher Wert derzeit am höchsten ist) 30 Sek. lang um 18 zu erhöhen. (Procchance: 20%, 1.75Min. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][68995] = {name = "[q4]Gefäß der Beschleunigung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Gefäß der Beschleunigung (1)\nSchmuck\n+4 Stärke\n[q2]Anlegen: Erhöht jedes Mal, wenn Ihr einen kritischen Nahkampftreffer erzielt, den kritischen Trefferwert 20 Sek. lang um 1 . Bis zu 5-mal stapelbar.\nVerkaufspreis:"}
MultiLanguageItemData['de'][68996] = {name = "[q4]Hinrichtungsaufschub", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Hinrichtungsaufschub (1)\nSchmuck\n[q2]+ 6 Ausweichen\n[q2]Benutzen: Absorbiert 20% des eintreffenden Schadens, bis zu 54 Schaden insgesamt. Wenn der Effekt endet, erleidet Ihr 10 Sek. lang alle 2 Sek. 8% des absorbierten Schadens. Hält 30 Sek. lang an. (2 Min Abklingzeit)\nBenötigtRächer des Hyjal\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][68997] = {name = "Stab des Wächters", additional_info = "Questgegenstand\n[q2]Benutzen: In den Aschehaufen platzieren, um Galenges zu beschwören."}
