MultiLanguageItemData['de'][79813] = {name = "Fetzen der Allianz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (3)\n[q2]Benutzen: Fügt 3 Fetzen der Allianz zusammen, um ihre ursprüngliche Form wiederherzustellen.\n[q]\"Ein Stofffetzen in den Farben der Allianz. Bei den Langfingern der Schlingschwänze können vielleicht noch mehr gefunden werden.\""}
MultiLanguageItemData['de'][79819] = {name = "Dit Da Jow", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Ein populäres Einreibemittel, das aus diversen Kräutern besteht, die in einer geheimen Mischung zusammengestellt wurden. Heilt unter Garantie sofort blaue Flecken und kleinere Verletzungen. (5 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][79824] = {name = "Gestohlenes Gemüse", additional_info = "Questgegenstand\n[q]\"Scheint... größtenteils unbeschädigt.\""}
MultiLanguageItemData['de'][79825] = {name = "Versorgungsgüter aus Zhus Wacht", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Getreide, Gewürze und Pökelfleisch sind fein säuberlich verstaut.\""}
MultiLanguageItemData['de'][79826] = {name = "Verschossener Shado-Pan-Pfeil", additional_info = "Questgegenstand\n[q]\"Ein Paradebeispiel für 'Hauptsache weit - wen interessiert, ob's trifft'.\""}
