MultiLanguageItemData['de'][84580] = {name = "[q3]Formel: Waffe - Flussgesang", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man die Verzauberung 'Flussgesang' durchführt.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Schaden verursachenden Nahkampfangriffe manchmal Euer Ausweichen 7 Sek. lang um 34 erhöhen. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigtShado-Pan\n- Respektvoll\nVerkaufspreis:"}
MultiLanguageItemData['de'][84582] = {name = "[q0]Formel: Waffe - Windweise", additional_info = "Benötigt Verzauberkunst (550)\n[q]\"Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass verursachter Zauber- und Nahkampfschaden den kritischen Trefferwert, das Tempo oder die Meisterschaft manchmal 12 Sek. lang um 1.500 erhöht. Erfordert einen Gegenstand der Stufe 372 oder höher.\""}
MultiLanguageItemData['de'][84583] = {name = "[q3]Formel: Waffe - Jadegeist", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man die Verzauberung 'Jadegeist' durchführt.\n[q2]Eine Nahkampfwaffe dauerhaft verzaubern, sodass Eure Heilungen oder Schaden verursachenden Zauber manchmal Eure Intelligenz um 34 erhöhen. Wenn Ihr über weniger als 25% Mana verfügt, während dieser Effekt ausgelöst wird, wird Eure Vielseitigkeit ebenfalls um 16 erhöht. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Verzauberkunst von Pandaria (75)\nBenötigtShado-Pan\n- Respektvoll\nVerkaufspreis:"}
