MultiLanguageItemData['de'][86476] = {name = "Laterne des Zaubererkönigs", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Der Zaubererkönig, Zian des endlosen Schattens, benutzte das Licht dieser Laterne als Energiequelle für seine mächtigsten Zauber.\""}
MultiLanguageItemData['de'][86477] = {name = "Waage von König Meng dem Irren", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Eine obskure Passage eines uralten Texts deutet darauf hin, dass Meng der Irre mit seiner Waage auch seinen Verstand verlor.\""}
MultiLanguageItemData['de'][86478] = {name = "Qiangs \"Die Wissenschaft des Krieges\"", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Qiang der Gnadenlose war ein Meister der Taktik und Strategie. Ein zufällig ausgewähltes Zitat dieser Abhandlung des Königs und Kriegsfürsten lautet 'Knochen mehren sich, wenn sie zermalmt werden.'\""}
MultiLanguageItemData['de'][86479] = {name = "Bogen von Subetai dem Schnellen", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Niemand war so habgierig wie der Banditenkönig und niemandes Bogen war so schnell.\""}
