MultiLanguageItemData['de'][86529] = {name = "[q3]Talisman des Manipulators", additional_info = "[q7]Wird an Kriegsmeute gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Anlegen: Die Angriffe Eures Begleiters haben eine Chance, zusätzlich 50% Schaden als Naturschaden zu verursachen, jedoch nicht mehr als 26 . (Procchance: 10%)\nVerkaufspreis:"}
MultiLanguageItemData['de'][86532] = {name = "Beutel mit Gasbomben der Shado-Pan", additional_info = "Questgegenstand\n[q2]Benutzen: Platziert eine Shado-Pan-Gasbombe. Fügt Humanoiden, die keine Mantis sind, keinen Schaden zu. (20 Sek. Abklingzeit)\n[q]\"Macht Schluss mit Mantis.\""}
MultiLanguageItemData['de'][86533] = {name = "Leuchtender Bern", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Das sanfte Schimmern legt Euch nahe, dass es sich hierbei nicht um ein gewöhnliches Stück Bern handelt.\""}
MultiLanguageItemData['de'][86534] = {name = "Glänzende Münze der Shado-Pan", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 18 std. (Realzeit)\n[q2]Benutzen: Wirft eine Shado-Pan-Münze, die die Aufmerksamkeit aller in der Nähe befindlichen Monster 10 Sek. lang auf sich zieht. Bricht Verstohlenheit nicht ab. Nur auf Sra'vess anwendbar. (3 Sek. Abklingzeit)\n[q]\"Das Geräusch lenkt die Mantis ab, nicht der Wert.\""}
MultiLanguageItemData['de'][86536] = {name = "Wukaopfeil der Lethargie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (6)\nDauer: 18 std. (Realzeit)\n[q2]Benutzen: Macht ein Ziel bis zu 1 Min. lang handlungsunfähig. Muss im Verstohlenheitsmodus sein. Wirkt nur bei Sra'vess, die sich nicht im Kampf befinden. Jeglicher erlittene Schaden belebt das Ziel wieder. (3 Sek. Abklingzeit)\n[q]\"Ein kunstvoll gearbeiteter Pfeil, der von den Wukao verwendet wird.\""}
MultiLanguageItemData['de'][86541] = {name = "[q0]Ausgebrannte Glyphe", additional_info = "Klassen: Priester\n[q]\"Es sieht zwar aus, als wäre diese Glyphe entsetzlich verbrannt und hätte jegliche Magie verloren, doch ein Händler bemerkt den Unterschied vielleicht nicht...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86542] = {name = "[q2]Fliegender Tigergurami", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Angeln (1)\n[q]\"Ein Fisch mit Flügeln? Wie ungewöhnlich.\""}
