MultiLanguageItemData['de'][86545] = {name = "[q2]Fintenfisch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Angeln (1)\n[q]\"Selbst nach ihrem Tod ändert diese seltsame Kreatur ihre Farben, um sich ihrer Umgebung anzupassen.\""}
