MultiLanguageItemData['de'][86565] = {name = "[q3]Schlachthorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Schmettert in ein lautes Signalhorn, das Gegner innerhalb von 40 Metern anlockt. Funktioniert nicht bei Zielen, die nicht aus Pandaria stammen oder deren Stufe 49 überschreitet. (2 Min Abklingzeit)\n[q]\"Wird von Yaungolspähern getragen, um im Falle eines Angriffs Verbündete zu alarmieren.\""}
MultiLanguageItemData['de'][86566] = {name = "[q3]Sammlerhandschuhe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Hände} {Stoff}\n1 Rüstung\nHaltbarkeit 20 / 20\n[q2]Anlegen: Ermöglicht schnelleres Sammeln von Ressourcen in Pandaria.\n[q]\"Schützt gegen scharfkantige Steine und Dornen.\""}
MultiLanguageItemData['de'][86567] = {name = "[q3]Yaungolwindspiel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Stürmt auf einen Gegner zu, fügt Gegnern in einem Umkreis von 8 Metern 32 körperlichen Schaden zu und stößt sie 2 Sek. lang zu Boden. (2 Min Abklingzeit)\n[q]\"Wird von Yaungolmedizinmännern verwendet, um Wetteränderungen zu erahnen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86568] = {name = "[q3]Handlanger Peins Messingkompass", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Setzt die Erinnerungen eines längst vergessenen Ersten Maats frei. (Procchance: 5%, 3Min. Abklingzeit) (2 Std. Abklingzeit)"}
MultiLanguageItemData['de'][86569] = {name = "[q3]Kristall des Wahnsinns", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Erhöht 1 Stunde lang alle Werte um 9 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. (15 Min Abklingzeit)\n[q]\"Es wirkt fast, als ob er Euch... anstarrt.\""}
MultiLanguageItemData['de'][86570] = {name = "[q3]Kiste mit entführten Welpen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Befreit die entführten Welpen, die 10 Min. lang für Euch kämpfen. (1 Stunde Abklingzeit)\n[q]\"...und sie essen Welpen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86571] = {name = "[q3]Kangs Bindungsstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Erfüllt Euch mit Stein und gewährt eine Chance, nach dem Töten eines Gegners diesen in Stein zu hüllen. (Procchance: 33%, 1Min. Abklingzeit) (1 Stunde Abklingzeit)\n[q]\"Die Steinbinder der Mogu nutzen diese runenverzierten Katalysatoren, um Fleisch in Stein zu verwandeln.\""}
MultiLanguageItemData['de'][86572] = {name = "[q3]Terrakottafragment", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Beschwört einen Terrakottakrieger, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n[q]\"Mit mächtiger Mogumagie erfüllt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86573] = {name = "[q3]Fragment des Abschlusssteins", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Verwandelt in eine Mogustatue und kann 5 Min. lang nicht als Ziel erfasst werden. (30 Min Abklingzeit)\n[q]\"Ein Fragment unbekannter Herkunft, das von uralter Magie erfüllt ist.\""}
MultiLanguageItemData['de'][86574] = {name = "[q0]Elixier des uralten Wissens", additional_info = "[q]\"Ein leises Flüstern ist aus dem Fläschchen zu vernehmen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86575] = {name = "[q3]Kelch der Geheimnisse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Gebt Euch Eurem Zorn 10 Sek. lang hin. Während der Wirkungsdauer verwandelt Euch der nächste Todesstoß, den Ihr gegen einen Spielercharakter erzielt, 6.3 Sek. lang in einen Mogu. Als Mogu könnt Ihr keine anderen Aktionen ausführen, während Ihr den Gegner verhöhnt. (10 Min Abklingzeit)\n[q]\"Rituale, um die Leichen gefallener Feinde zu entweihen, waren in der Mogukultur weit verbreitet.\""}
MultiLanguageItemData['de'][86576] = {name = "[q3]Dynastie des Stahls", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Beschwört einen Klingentornado, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n[q]\"Die Schwertkunst der Mantis ist ein sorgsam gehütetes Geheimnis.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86577] = {name = "[q3]Rute des Bernformens", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Hüllt das Ziel in Bern und verhindert bis zu 1 Min. lang jegliche Handlung. Jeglicher Schaden zerbricht den Bern. Kann nicht gegen Spielercharaktere oder Ziele über Stufe 49 eingesetzt werden. (5 Min Abklingzeit)\n[q]\"Wird von den Bernwebern der Mantis verwendet, um Konstruktionen oder gehärteten Bern herzustellen.\""}
MultiLanguageItemData['de'][86578] = {name = "[q3]Siegel des ewigen Kriegers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Regeneriert 6 Sek. lang alle 1 Sek. 15% Gesundheit und Mana. Jeglicher erlittene Schaden beendet die Raserei. Kann nur in Pandaria genutzt werden. (5 Min Abklingzeit)\n[q]\"An Shek'zeers Elitewächter für treue Dienste verliehen.\""}
MultiLanguageItemData['de'][86580] = {name = "[q0]Verwelktes Seerosenblatt", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Jäger , Schurke , Priester , Todesritter , Schamane , Magier , Hexenmeister , Mönch\n[q]\"Dieses Exemplar ist dem Klimawandel erlegen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86581] = {name = "[q3]Weitwassermuschelhorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Lässt Euch weit in die Ferne blicken und gewährt die Fähigkeit, kleine Wassertropfen zu erzeugen. (10 Min Abklingzeit)\n[q]\"Das Muschelhorn ist mit Jinyurunen beschrieben, die es dem Benutzer ermöglichen, die Sprache der Wellen zu verstehen.\""}
MultiLanguageItemData['de'][86582] = {name = "[q3]Wasserjuwel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Erhöht die Schwimmgeschwindigkeit um 50% und gestattet Unterwasseratmung. Hält 10 Min. lang an. Kann nur in Pandaria genutzt werden. (1 Stunde Abklingzeit)\n[q]\"Aus dem Schlund von Gokk'lok erbeutet.\""}
MultiLanguageItemData['de'][86583] = {name = "[q3]Schlachtbanner von Salyis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Versteckt Euch 1 Sek. lang in den Schatten und beschwört einen Kriegsspäher von Salyis. Der Kriegsspäher zieht die Aufmerksamkeit von Monstern in der Nähe auf sich und rennt davon. Nur wirksam in Pandaria. (10 Min Abklingzeit)\n[q]\"Mit dem Blut vieler glückloser Abenteurer getränkt.\""}
MultiLanguageItemData['de'][86584] = {name = "[q3]Gehärteter Panzer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Wirft einen harten Panzer, der das Ziel aus dem Sattel stößt. Funktioniert nicht bei Zielen über Stufe 49.. (15 Min Abklingzeit)\n[q]\"Unfair!\""}
MultiLanguageItemData['de'][86585] = {name = "[q3]Goldenes Vlies", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Anlegen: Getötete Gegner, die Erfahrung oder Ehre gewähren, können zusätzliche Goldbeute gewähren. (Procchance: 10%, 10Min. Abklingzeit)\n[q]\"Wird unter den Saurok als Zeichen von Reichtum und Status betrachtet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86586] = {name = "[q3]Pandarische Panflöte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Spielt auf der Panflöte, woraufhin Euch Kleintiere in der Nähe 15 Min. lang folgen. (1 Min Abklingzeit)"}
MultiLanguageItemData['de'][86587] = {name = "[q3]Samen des ruhigen Wachstums", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Beschwört einen ruhigen Sprössling, der Euch 10 Min. lang heilt. (1 Stunde Abklingzeit)\n[q]\"Pulsierende Lebensenergie entspringt diesem Samen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][86588] = {name = "[q3]Pandarischer Raketenzünder", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Bereitet ein beeindruckendes Feuerwerk vor. (30 Min Abklingzeit)\n[q]\"Hier geht's ab!\""}
MultiLanguageItemData['de'][86589] = {name = "[q3]Ai-Lis Himmelsspiegel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Nehmt das etwas verzerrte Aussehen des Ziels an. Hält 10 Min. lang an. (1 Stunde Abklingzeit)\n[q]\"Von einem sich stetig bewegenden Wolkenring umgeben.\""}
MultiLanguageItemData['de'][86590] = {name = "[q3]Essenz der Brise", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Löst eine leichte Brise aus, die Eure Schritte leichter macht. Dieser Effekt zeigt nur in Pandaria Wirkung. (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][86591] = {name = "[q3]Magische Banane", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Wirft eine magische Banane auf den Boden, die die nächste Person zu Fall bringen wird, die über sie läuft. (2 Std. Abklingzeit)"}
MultiLanguageItemData['de'][86592] = {name = "[q3]Ho-zen-Friedenspfeife", additional_info = "[q2]Benutzen: Erhöht den Ruf bei den Einwohnern Pandarias um 1000. (7 Tagen Abklingzeit)"}
MultiLanguageItemData['de'][86593] = {name = "[q3]Ho-zen-Wasserball", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Macht Euch auf Sommerspaß gefasst! (1 Stunde Abklingzeit)"}
MultiLanguageItemData['de'][86594] = {name = "[q3]Pfeife des hilfreichen Nupsi", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Ruft das hilfreiche Nupsi, das für Euch nach Futter sucht und Geschenke zurückbringt. Kann nur in Pandaria genutzt werden. (2 Std. Abklingzeit)\n[q]\"Darauf wurde wohl heftig herumgekaut.\""}
MultiLanguageItemData['de'][86595] = {name = "[q2]Beutel mit hilfreichen Sachen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][86596] = {name = "[q3]Nats Angelstuhl", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Einen bequemen Angelstuhl aufstellen. (5 Min Abklingzeit)\n[q]\"Hat sogar einen Getränkehalter!\""}
MultiLanguageItemData['de'][86597] = {name = "[q2]Waffenkette aus lebendigem Stahl", additional_info = "Wird beim Anlegen gebunden\n[q2]Benutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert und Euren kritischen Trefferwert um 13 erhöht. Ist nicht mit ähnlichen Effekten stapelbar. Durch das Anbringen der Waffenkette wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden."}
MultiLanguageItemData['de'][86598] = {name = "Vor'thik-Eier", additional_info = "Questgegenstand"}
MultiLanguageItemData['de'][86599] = {name = "Geistereisenschildstachel", additional_info = "Wird beim Anlegen gebunden\n[q2]Benutzen: Bringt einen Geistereisenstachel an Eurem Schild an, der beim Blocken manchmal 42 Schaden verursacht.\n\n Durch das Anbringen des Geistereisenstachels wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][86607] = {name = "Goblindrachengewehr - Nr. II", additional_info = "[q2]Benutzen: Entfesselt eine Blitzentladung, die Zielen in einem 10 Meter großen kegelförmigen Bereich vor dem Wirkenden 4 Sek. lang alle 0.5 Sek. 48 Naturschaden zufügt.\n\n Kann während der Bewegung gewirkt werden. (30 Sek. Abklingzeit)\n50 Aufladungen\nVerkaufspreis:"}
MultiLanguageItemData['de'][86616] = {name = "Schreckensbernfokus", additional_info = "Questgegenstand\n[q]\"Konzentrierte Angst, die in kristallisiertem Kyparitharz gebunden wurde.\""}
