MultiLanguageItemData['de'][87202] = {name = "Stimmgabel der Klaxxi", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Schlägt auf den Brocken uralten Berns.\n[q]\"Die Gabeln summen sanft, wenn man sie anschlägt.\""}
