MultiLanguageItemData['de'][87212] = {name = "[q5]Atem des Schwarzen Prinzen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Verstärkt jegliche Sha-berührte Ausrüstung enorm. Entfernt alle vorhandenen Edelsteine und Verzauberungen.\n1 Aufladung\n[q]\"Die Macht des letzten Schwarzdrachen steht zu Eurer Verfügung.\""}
MultiLanguageItemData['de'][87213] = {name = "[q2]Nebeldurchdringende Brille", additional_info = "Wird beim Anlegen gebunden\nKopf\n[q2]Anlegen: Ermöglicht Euch, zusätzliche Erzadern und Kräutervorkommen aufzuspüren, während Ihr Euch in Pandaria befindet.\n[q]\"Obwohl diese Brille sehr modisch ist, muss sie nicht aufgesetzt werden, um von ihrer Spezialfähigkeit zu profitieren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][87214] = {name = "[q4]Blingtron 4000", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Setzt den unglaublichen Blingtron 4000 zusammen, einen Roboter von unendlichem Reichtum. Bling, wie er gerne genannt wird, händigt jedem, der mit ihm spricht, ein zufälliges Geschenk aus, aber nur ein Mal pro Tag. Hält 10 Min. lang an. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Pandaria (75)"}
MultiLanguageItemData['de'][87215] = {name = "[q3]Wurmlochgenerator: Pandaria", additional_info = "Wird bei Benutzung gebunden\nSpielzeug\n[q2]Benutzen: Teleportiert Euch an irgendeinen Ort in Pandaria. Der exakte Ort ist schwer zu bestimmen, aber er ist wahrscheinlich ziemlich weit entfernt. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Pandaria (1)\n[q]\"An der Seite ist eine winzige Notiz: Huiiiiiiiiiiiiiii!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][87216] = {name = "Thermischer Amboss", additional_info = "[q2]Benutzen: Platziert einen thermischen Amboss zu Euren Füßen, der allen in der Nähe befindlichen Charakteren erlaubt, sowohl einen Amboss als auch eine Schmiede zu benutzen. Hält 5 Min. lang an. (5 Min Abklingzeit)\n20 Aufladungen\nVerkaufspreis:"}
