MultiLanguageItemData['de'][87775] = {name = "[q4]Yu'lei, Tochter der Jade", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Yu'lei, Tochter der Jade, und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser großen Kreatur, die wie Mondlicht durch feinste Jade schimmert, entspringt Wärme und Weisheit.\"\nVerkäufer:\nNebelwirkerin Xia\nZone:\nZeitlose Insel\nKosten:\n5.000"}
MultiLanguageItemData['de'][87776] = {name = "[q4]Zügel der himmlischen Azurwolkenschlange", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört eine reitbare himmlische Azurwolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser großen Kreatur, die wie ein wolkenloser Himmel an einem Sommerabend leuchtet, entspringt Wärme und Gelassenheit.\"\nErfolg:\nHerr der Reittiere\nKategorie:\nReittiere"}
MultiLanguageItemData['de'][87777] = {name = "[q4]Zügel der astralen Wolkenschlange", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört eine reitbare astrale Wolkenschlange und gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Man geht davon aus, dass die astralen Wolkenschlangen Antworten auf einige der größten Geheimnisse des Lebens kennen. Zu dumm, dass sie nicht sprechen können.\"\nBeute von:\nBehälter aus reiner Energie"}
