MultiLanguageItemData['de'][88371] = {name = "[q2]Wassermelonenbombe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Ausdauer\n[q2]Anlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 15 kritischen Trefferwert zu gewähren. (Procchance: 20%, 50s Abklingzeit)\n[q2]Benutzen: Wirft eine Wassermelone auf den Zielort, deren Aufprall alle Gegner in der Nähe mit klebrigem Fruchtfleisch bespritzt, was sie 3 Sek. lang bewegungsunfähig macht. Spielercharaktere sind davon nicht betroffen. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][88375] = {name = "Rübensandsack", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört 5 Min. lang einen Rübensandsack am Zielort, der als Zielattrappe dient.\n\n Kann nur im Freien eingesetzt werden. (1 Stunde Abklingzeit)\n[q]\"Eine Rübe mit extrem robustem Äußeren. Sie kann genauso gut Schläge einstecken wie ein Boss in heroischen Dungeons.\""}
MultiLanguageItemData['de'][88376] = {name = "[q2]Orange angemalte Rübe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Anlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 15 Meisterschaft zu gewähren. (Procchance: 20%, 50s Abklingzeit)\n[q2]Benutzen: Wirft eine orange angemalte Rübe auf den Zielort, worauf alle Shed-Ling in der Nähe 3 Sek. lang vor Furcht flüchten. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][88377] = {name = "[q3]Rübenfarbsprühpistole", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Schleudert eine Kugel oranger Farbe auf Euer aktuelles verbündetes Ziel, wodurch es 6 Sek. lang orange angemalt wird. (5 Min Abklingzeit)"}
MultiLanguageItemData['de'][88378] = {name = "[q2]Mottallus' Spinndrüsen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n[q2]Anlegen: Eure offensiven Angriffe und Fähigkeiten haben eine Chance, Euch 20 Sek. lang 15 Tempo zu gewähren. (Procchance: 20%, 50s Abklingzeit)\n[q2]Benutzen: Feuert ein Netz auf das Ziel und macht es 3 Sek. lang bewegungsunfähig. Hat keinen Effekt auf Spieler. Kann nur im Tal der Vier Winde und in der Krasarangwildnis verwendet werden. (2 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][88379] = {name = "Grummelkuchen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Stellt im Verlauf von 10 Sek. ( 1833 * 10 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet einen zufälligen Stärkungszauber, der am Kun-Lai-Gipfel wirkt.\n\n Funktioniert nur am Kun-Lai-Gipfel."}
