MultiLanguageItemData['de'][89196] = {name = "[q3]Wappenrock von Theramore", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nWappenrock\n[q2]Benutzen: Euer Banner von Theramore aufstellen. (3 Min Abklingzeit)\n[q]\"Vergesst Theramore nicht!\""}
MultiLanguageItemData['de'][89197] = {name = "Scherwindkaktussamen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Pflanzt einen Scherwindkaktussamen.\nBenötigt einen respektvollen Ruf bei den Ackerbauern\n[q]\"Der Scherwindkaktus ist mit Millionen feinster Nadeln bedeckt, die den vorbeiziehenden Wind filtern. Windwollfasern und Reste anderer Materialien bleiben häufig an ihnen hängen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][89202] = {name = "Raptorblattsamen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Pflanzt Raptorblattsamen.\nBenötigt einen respektvollen Ruf bei den Ackerbauern\n[q]\"Das Raptorblatt ist eine fleischfressende Pflanze, der regelmäßig Shed-Ling, Falken und andere Kleintiere zum Opfer fallen. Nach einem einzigen Fang stirbt sie, setzt dabei ihre Samen frei und lässt oft auch Überreste ihrer Beute zurück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][89205] = {name = "[q3]Minimanabombe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Diese Minimanabombe werfen. (3 Min Abklingzeit)"}
MultiLanguageItemData['de'][89209] = {name = "Makelloses Kassenbuch eines Architekten", additional_info = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Die Einzelheiten dieses Artefakts wurden bereits in Eurem Archäologiebuch unter 'Restaurierte Artefakte' protokolliert.\""}
MultiLanguageItemData['de'][89216] = {name = "[q4]Yis ungeliebter Helm", additional_info = "Wird beim Aufheben gebunden\n{Kopf} {Platte}\n12 Rüstung\n+1 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Metasockel\n[q0]Prismatischer Sockel\n[q0]Sockelbonus: + 10 Ausdauer\n\nHaltbarkeit 100 / 100\nVerkaufspreis:"}
MultiLanguageItemData['de'][89222] = {name = "[q3]Wolkenring", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört einen Wolkenring, durch den Euer Haustier springt. Benötigt ein fliegendes Haustier. (10 Min Abklingzeit)\nBenötigtOrden der Wolkenschlange\n- Respektvoll\n[q]\"Unterhaltung für Euer fliegendes Haustier.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][89223] = {name = "Rennflagge", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Beschwört 15 Min. lang eine Rennflagge am Zielort. (30 Sek. Abklingzeit)\nBenötigtOrden der Wolkenschlange\n- Respektvoll\n[q]\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][89224] = {name = "Schwebende Rennflagge", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 15 Min. lang eine schwebende Rennflagge an Eurem aktuellen Standort. Kann beim Reiten verwendet werden. (30 Sek. Abklingzeit)\nBenötigtOrden der Wolkenschlange\n- Respektvoll\n[q]\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][89225] = {name = "Ziellinie", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Beschwört 15 Min. lang eine Ziellinie am Zielort. (10 Min Abklingzeit)\nBenötigtOrden der Wolkenschlange\n- Respektvoll\n[q]\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][89227] = {name = "Schwebende Ziellinie", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Beschwört 15 Min. lang eine schwebende Ziellinie an Eurem aktuellen Standort. Kann beim Reiten verwendet werden. (10 Min Abklingzeit)\nBenötigtOrden der Wolkenschlange\n- Respektvoll\n[q]\"Baut Eure eigene Rennstrecke.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][89230] = {name = "Erneuernder Bern", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Schließt Euch selbst in erneuernden Bern ein. Stellt im Verlauf von 10 Sek. 4340 Gesundheit und ( 5203 / 5 * 10) Mana wieder her.\nBenötigtDie Klaxxi\n- Wohlwollend\nVerkaufspreis:"}
MultiLanguageItemData['de'][89232] = {name = "[q3]Mogurune der Paralyse", additional_info = "Wird beim Aufheben gebunden\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n[q2]Benutzen: Platziert eine Mogurune der Paralyse auf dem Boden, die 1 Min. lang anhält und die nächste Kreatur 4 Sek. lang betäubt, die sie betritt. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][89233] = {name = "Klangglöckchensamen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Pflanzt Klangglöckchensamen.\nBenötigt einen respektvollen Ruf bei den Ackerbauern\n[q]\"Die Harmonie der hellen und dunklen, glockenförmigen Blüten dieser Pflanze hat die pandarische Lied- und Dichtkunst über Jahrtausende hinweg beeinflusst.\"\nVerkaufspreis:"}
