MultiLanguageItemData['de'][91865] = {name = "Portalsplitter: Darnassus", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bricht den Splitter auf und erschafft ein Portal nach Darnassus.\n\n Kann nur auf dem Gehöft Sonnensang verwendet werden."}
MultiLanguageItemData['de'][91866] = {name = "Portalsplitter: Exodar", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bricht den Splitter auf und erschafft ein Portal zur Exodar.\n\n Kann nur auf dem Gehöft Sonnensang verwendet werden."}
MultiLanguageItemData['de'][91869] = {name = "Verdorbenes Zwingzangenfleisch", additional_info = "Questgegenstand\n[q]\"Ein ranziger Gestank geht von diesem eitrigen Fleisch aus.\""}
MultiLanguageItemData['de'][91871] = {name = "Gezackter Stein", additional_info = "Questgegenstand\n[q]\"Der Stein hat eine rauhe, aber warme Oberfläche.\""}
MultiLanguageItemData['de'][91874] = {name = "Brocken eigenartiges Fleisch", additional_info = "Questgegenstand\n[q]\"Ein fürchterlich riechender Schleim trieft von dem Fleisch. Es wird Tage dauern, bis Ihr den Gestank aus Euren Taschen bekommt.\""}
MultiLanguageItemData['de'][91875] = {name = "Kreissäges Hausmarke", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Bixis geheimes Familienrezept für Treibstoff, das von einer Generation Kreissägen zur nächsten weitergegeben wurde.\""}
MultiLanguageItemData['de'][91877] = {name = "Schlachtbefehl der Herrschaftsfeste", additional_info = "Wird beim Aufheben gebunden\n[q]\"Ein kleines Schriftstück, das in der Sprache der Orcs verfasst ist und eine Karte von Pandaria zeigt, auf der mit roter Tinte Punkte markiert sind. Bringt es zu Administrator Grantley in der Löwenlandung.\""}
MultiLanguageItemData['de'][91902] = {name = "Universalfernsteuerung", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Sendet auf Frequenz Drei Zwo Neun. (5 Sek. Abklingzeit)\n[q]\"Nicht direkt in die Lichtquelle blicken. Hersteller übernimmt keine Haftbarkeit.\""}
MultiLanguageItemData['de'][91904] = {name = "[q3]Stapelbarer Hirsch", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Beschwört einen stapelbaren Hirsch am Zielort. Wenn sich ein anderer stapelbarer Hirsch in der Nähe befindet, wird sich Euer stapelbarer Hirsch auf den anderen stapelbaren Hirsch stapeln. (1 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][91906] = {name = "Brüchige Wurzel", additional_info = "Ein wenig Geduld\nEinzigartig (5)\n[q2]Benutzen: Stellt allen Arbeitern Materialien zur Verfügung, wodurch sich ihre Arbeitsgeschwindigkeit 60 Sek. lang um 30% des Grundwerts erhöht. Bis zu 3-mal stapelbar."}
MultiLanguageItemData['de'][91907] = {name = "Bauholz der Löwenlandung", additional_info = "Questgegenstand\n[q]\"Dieses Holz wurde kürzlich in den Wäldern um die Löwenlandung geschlagen – und noch kürzlicher von feigen Arbeitern zurückgelassen.\""}
MultiLanguageItemData['de'][91971] = {name = "Kampfrationen", additional_info = "Ein wenig Geduld\nEinzigartig (5)\n[q2]Benutzen: Versorgt alle Arbeiter mit Nahrung, was ihre Arbeitsgeschwindigkeit 60 Sek. lang um 60% des Grundwerts erhöht. Bis zu 3-mal stapelbar."}
MultiLanguageItemData['de'][92019] = {name = "Der Bilgewässer Molotow", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft eine Flasche brennenden, umfunktionierten Fusels nach einem Gyrokopter X2 der Himmelsfeuer.\n[q]\"Ein starkes Gemisch aus hochreaktiven, brennbaren Chemikalien, serviert mit einem brennenden Taschentuch.\""}
MultiLanguageItemData['de'][92035] = {name = "Verziertes Zepter", additional_info = "Ein wenig Geduld\nEinzigartig\n[q]\"Ein uraltes Moguartefakt.\""}
MultiLanguageItemData['de'][92036] = {name = "Stab des Affenkönigs", additional_info = "Questgegenstand\n[q]\"Ihr verspürt große Macht in diesem einfach anmutenden Stab. So sehr Ihr es auch versucht, er lässt sich nicht benutzen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][92049] = {name = "Söldnervertrag: Magier", additional_info = "[q2]Benutzen: Heuert einen Magier an, der Hordespielern in der Nähe kostenlos 'Arkane Brillanz' verleiht.\n\nArkane Brillanz\n 30 Meter Reichweite\n Sofort\n Requires Mage Erfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92050] = {name = "Söldnervertrag: Paladin", additional_info = "[q2]Benutzen: Heuert einen Paladin an, der Hordespielern in der Nähe kostenlos 'Segen der Macht' verleiht.\n\nSegen der Macht Stufe 35 30 Meter Reichweite\n Sofort\n Requires Paladin Belegt ein befreundetes Ziel mit einem Segen, welcher seine Meisterschaft um 59 erhöht. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92051] = {name = "Söldnervertrag: Priester", additional_info = "[q2]Benutzen: Heuert einen Priester an, der Hordespielern in der Nähe kostenlos 'Machtwort: Seelenstärke' verleiht.\n\nMachtwort: Seelenstärke 4.4% of base mana 40 Meter Reichweite Spontan\n Requires Priest Erfüllt das Ziel mit Vitalität, die die Ausdauer 1 Stunde lang um 10% erhöht. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92052] = {name = "Söldnervertrag: Druide", additional_info = "[q2]Benutzen: Heuert einen Druiden an, der Hordespielern in der Nähe kostenlos 'Mal der Wildnis' verleiht.\n\nMal der Wildnis\n 30 Meter Reichweite\n Sofort\n Requires Druid Erhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels 1 Stunde lang um 5%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92053] = {name = "Söldnervertrag: Krieger", additional_info = "[q2]Benutzen: Heuert einen Krieger an, der Hordespielern in der Nähe kostenlos 'Schlachtruf' verleiht.\n\nGellender Schlachtruf\n 30 Meter Reichweite\n Sofort\n Requires Warrior Erhöht die Angriffskraft des Ziels um 10%. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92054] = {name = "Söldnervertrag: Schurke", additional_info = "[q2]Benutzen: Heuert einen Schurken an, der Hordespielern in der Nähe kostenlos 'Signal der Schnellklinge' verleiht.\n\nSignal der Schnellklinge\n 30 Meter Reichweite\n Sofort\n Requires Rogue Erhöht das Nahkampf- und Distanzangriffstempo des Ziels um 10%. Funktioniert nur in der Krasrangwildnis."}
MultiLanguageItemData['de'][92055] = {name = "Söldnervertrag: Schamane", additional_info = "[q2]Benutzen: Heuert einen Schamanen an, der Hordespielern in der Nähe kostenlos 'Bindender elementarer Schwur' verleiht.\n\nBindender Elementarer Schwur\n 30 Meter Reichweite\n Sofort\n Requires Shaman Gewährt dem Ziel 5% Zaubertempo. Funktioniert nur in der Krasarangwildnis."}
MultiLanguageItemData['de'][92056] = {name = "Portaltreibstoff: Außenposten Zündmine", additional_info = "[q2]Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Zweiwegportal zum Außenposten Zündmine aufrechtzuerhalten."}
MultiLanguageItemData['de'][92057] = {name = "Portaltreibstoff: Orgrimmar", additional_info = "[q2]Benutzen: Ausreichend Treibstoff, um 20 Minuten lang ein Einwegportal nach Orgrimmar aufrechtzuerhalten."}
