MultiLanguageItemData['de'][92070] = {name = "[q2]Ranzen der Huojin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n16 Platz Tasche\n[q]\"Erfordert einen respektvollen Ruf bei den Huojin.\""}
MultiLanguageItemData['de'][92071] = {name = "[q2]Ranzen der Tushui", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n16 Platz Tasche\n[q]\"Erfordert einen respektvollen Ruf bei den Tushui.\""}
MultiLanguageItemData['de'][92072] = {name = "Korunkodex", additional_info = "Questgegenstand\n[q]\"Auf dem ledrigen Pergament ist eine Karte der nordöstlichen Kun-Lai-Berge abgebildet. Uralte, in dunkelroter Tinte gezeichnete Symbole der Macht gehen vom Mittelpunkt der Karte nach außen.\""}
MultiLanguageItemData['de'][92421] = {name = "Bewachungsvertrag: Friedhof", additional_info = "[q2]Benutzen: Heuert Wachen an, die einen eroberbaren Friedhof in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Friedhofs befinden und Eure Fraktion muss ihn kontrollieren."}
MultiLanguageItemData['de'][92422] = {name = "Bewachungsvertrag: Turm", additional_info = "[q2]Benutzen: Heuert Wachen an, die einen eroberbaren Turm in der Krasarangwildnis bewachen. Ihr müsst Euch in der Nähe des Turms befinden und Eure Fraktion muss ihn kontrollieren."}
MultiLanguageItemData['de'][92425] = {name = "Uralte Tafel der Korun", additional_info = "Questgegenstand\n[q]\"Diese Steintafel ist mit machtvollen Mogusymbolen übersät.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][92426] = {name = "[q4]Versiegelter Foliant der verlorenen Legion", additional_info = "Einzigartig\n[q2]Benutzen: Mit einem Gesundheitsstein verbinden, um den Folianten an Euch zu binden.\n[q]\"Abgesehen von der Kette und dem Schloss, die es binden, sieht das Buch ungewöhnlich normal aus.\""}
