MultiLanguageItemData['de'][92440] = {name = "Faksimile der Archäologischen Akademie", additional_info = "[q]\"Eine Abschrift der uralten Tafel der Korun. Darin wird der Ursprung der Götterglocke beschrieben.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][92441] = {name = "[q4]Kodex von Xerrath", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Als Ihr das Buch aufhebt, erklingen schreckliche, geflüsterte Mysterien in Euren Ohren, die Euren Verstand peinigen…\""}
MultiLanguageItemData['de'][92442] = {name = "Hordebanner", additional_info = "Einzigartig (20)\n[q2]Benutzen: Stellt ein Hordenbanner auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\n Ihr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Allianz können versuchen, Eure Banner niederzubrennen."}
MultiLanguageItemData['de'][92443] = {name = "Allianzbanner", additional_info = "Einzigartig (20)\n[q2]Benutzen: Stellt ein Allianzbanner auf. Das Banner bleibt 10 Minuten lang bestehen und ihr könnt bis zu 5 Banner gleichzeitig aufstellen.\n\n Ihr müsst für PvP markiert sein, um ein Banner aufzustellen. Für PvP markierte Spielercharaktere der Horde können versuchen, Eure Banner niederzubrennen."}
MultiLanguageItemData['de'][92444] = {name = "Fleischige Keule", additional_info = "Ein wenig Geduld\nEinzigartig (5)\n[q2]Benutzen: Versorgt alle Arbeiter mit Nahrung, was ihre Arbeitsgeschwindigkeit 60 Sek. lang um 60% des Grundwerts erhöht. Bis zu 3-mal stapelbar."}
MultiLanguageItemData['de'][92470] = {name = "Schlangenöl", additional_info = "Ein wenig Geduld\nEinzigartig (5)\n[q2]Benutzen: Stellt allen Gnomenarbeitern Schlangenöl zur Verfügung, wodurch sich ihre Arbeitsgeschwindigkeit 60 Sek. lang um 50% des Grundwerts erhöht. Bis zu 3-mal stapelbar. 1 Sek. Abklingzeit."}
MultiLanguageItemData['de'][92471] = {name = "Jubekas Tagebuch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Dieses lädierte, in Leder gebundene Notizbuch hat schon bessere Zeiten gesehen.\"\n[q2]<Zum Lesen rechtsklicken>"}
MultiLanguageItemData['de'][92472] = {name = "Durchweichtes Tagebuch", additional_info = "Ein wenig Geduld\nEinzigartig\n[q]\"Die Wahrscheinlichkeit, dies hier zu finden, kann nicht mehr als eins zu einer Million sein.\""}
MultiLanguageItemData['de'][92474] = {name = "Besonders schmalzige Allianzohren", additional_info = "Questgegenstand\n[q]\"Zündmines patentierte Glücksohren. Nur echt mit dem Schmalzpfropfen!\""}
