MultiLanguageItemData['de'][92754] = {name = "Feuerwein von Ruqin", additional_info = "Questgegenstand\n[q]\"Die weiße Flüssigkeit verströmt einen strengen, beißenden Geruch. Ein kleiner Schluck breitet sich wie Feuer in Eurem Inneren aus, gefolgt von einem warmen, lebendigen Gefühl im Kopf.\""}
MultiLanguageItemData['de'][92756] = {name = "Wein der Erinnerungen", additional_info = "Questgegenstand\n[q2]Benutzen: Werdet Zeuge einer Vision aus Shan Kiens Vergangenheit. (3 Sek. Abklingzeit)\n[q]\"Der Wein riecht nach einem Dutzend Aromen und Gewürzen, die gleichermaßen widerlich und verführerisch sind...\""}
MultiLanguageItemData['de'][92763] = {name = "Helm der Kor'kron", additional_info = "Questgegenstand\n[q2]Benutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen. (3 Sek. Abklingzeit)\n[q]\"Der polierte Helm ist verbeult.\""}
MultiLanguageItemData['de'][92764] = {name = "Rüstung der Kor'kron", additional_info = "Questgegenstand\n[q2]Benutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen.\n[q]\"Ziemlich schwer.\""}
MultiLanguageItemData['de'][92765] = {name = "Stiefel der Kor'kron", additional_info = "Questgegenstand\n[q2]Benutzen: Fügt den Helm der Kor'kron, die Rüstung der Kor'kron und die Stiefel der Kor'kron zu einer Kor'kron-Verkleidung zusammen.\n[q]\"Da hat wohl jemand seine Füße nicht gewaschen...\""}
MultiLanguageItemData['de'][92766] = {name = "Kor'kron-Verkleidung", additional_info = "Questgegenstand\n[q2]Benutzen: Verkleidet Euch als ein Mitglied der Kor'kron. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][92782] = {name = "[q4]Medaillon des standhaften Fußsoldaten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Erhöht die Rüstung 15 Sek. lang um 57 . Kann nur in Pandaria verwendet werden. (1 Min Abklingzeit)\n[q]\"Das Blut des Fußsoldaten, von dem es stammt, hat es dauerhaft befleckt.\""}
