MultiLanguageItemData['de'][104223] = {name = "[q2]Technik: Glyphe 'Unbändiger Elementar'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man die Glyphe 'Unbändiger Elementar' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\n\nGlyphe 'Unbändiger Elementar'\nKlassen: Magier\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nEuer Wasserelementar wird durch einen unbändigen Wasserelementar ersetzt. Exklusiv mit: Glyphe 'Verdampfen' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Jadefeuertinte (3)"}
MultiLanguageItemData['de'][104224] = {name = "[q2]Technik: Glyphe 'Verdampfen'", additional_info = "[q2]Benutzen: Lehrt Euch, wie man die Glyphe 'Verdampfen' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\nGlyphe 'Verdampfen'\nKlassen: Magier\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerringert die Größe Eures Wasserelementars um 15%. Exklusiv mit: Glyphe 'Unbändiger Elementar' Glyphe 'Gezeiten' Glyphe 'Sturmwacht' Glyphe 'Finstere Tiefe' Glyphe 'Dampfende Wut' Glyphe 'Kältewellen'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Löwentinte (3)"}
