MultiLanguageItemData['de'][104227] = {name = "[q2]Technik: Glyphe 'Säule des Lichts'", additional_info = "[q2]Benutzen: Lehrt Euch, wie man die Glyphe 'Säule des Lichts' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\n\nGlyphe 'Säule des Lichts'\nKlassen: Paladin\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nKritische Heilungen von 'Heiliger Schock' bei anderen Spielercharakteren erzeugen kurzzeitig eine Lichtsäule an deren Standort.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Traumtinte (3)"}
MultiLanguageItemData['de'][104228] = {name = "[q2]Technik: Glyphe 'Engel'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man die Glyphe 'Engel' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\n\nGlyphe 'Engel'\nKlassen: Priester\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nBeim Wirken von Heilzaubern besteht eine Chance, dass Ihr Engelsflügel erhaltet. (Procchance: 15%)\nVerkaufspreis:\nBenötigt Leichtes Pergament , Meerestinte (3)"}
MultiLanguageItemData['de'][104229] = {name = "[q2]Technik: Glyphe 'Sha'", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man die Glyphe 'Sha' schreibt.\nBenötigt Inschriftenkunde von Pandaria (1)\n\n\nGlyphe 'Sha'\nKlassen: Priester\n[q2]Benutzen: Lehrt Euch permanent diese Glyphe.\n\nVerwandelt Euren Schattengeist in eine Sha-Bestie. Exklusiv mit: Glyphe 'Lichtbrut' Glyphe 'Leerenekel'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Astraltinte (3)"}
