MultiLanguageItemData['de'][104286] = {name = "Zitterndes Feuersturmei", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q]\"Ein sehr seltenes Ei. Es sieht aus, als wenn bald etwas daraus schlüpfen würde. Die Älteste Anli im Arboretum würde das sicherlich gerne sehen.\""}
MultiLanguageItemData['de'][104287] = {name = "[q2]Windfeder", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Erhöht 1 Stunde lang die Geschwindigkeit um 30%, während Ihr ein nicht fliegendes Reittier reitet. Kann nur in Pandaria verwendet werden.\n[q]\"Die Federn des Windfederkranichs sind überraschend leicht und wehen schon beim sanftesten Lufthauch davon.\""}
MultiLanguageItemData['de'][104288] = {name = "[q2]Kondensierter Jadenebel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (5)\n[q2]Benutzen: Umgebt Euch mit einem dichten Nebel und ermöglicht Euch so, 10 Sek. lang mit den Schatten zu verschmelzen. Kann nur in Pandaria verwendet werden. (5 Min Abklingzeit)\n[q]\"Es heißt, die Jadenebeltänzer seien eins mit dem Nebel, der die Insel umgibt.\""}
MultiLanguageItemData['de'][104289] = {name = "[q2]Schwach leuchtendes Kraut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\nDauer: 1 tag (Realzeit)\n[q2]Benutzen: Der Verzehr des Krauts stellt 10 Sek. lang alle 1 Sek. 206 Gesundheit wieder her.\n[q]\"Diese Pflanze scheint über einen natürlichen Zauber zu verfügen.\""}
MultiLanguageItemData['de'][104290] = {name = "[q2]Klebriges Seidenraupenexkret", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q2]Benutzen: Überzieht einen Gegner mit klebriger Seide, wodurch sich selbst das stärkste Geschöpf 20 Sek. lang nicht bewegen kann. Kann nur auf der Zeitlosen Insel verwendet werden. (5 Min Abklingzeit)\n[q]\"Die Seidenraupen der Zeitlosen Insel benutzen einen seltsamen, doch sehr starken Seidenfaden, um ihre Beute zu fangen.\""}
MultiLanguageItemData['de'][104291] = {name = "[q2]Schwarmling von Gu'chi", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Mit Rechtsklick Euren Schwarmling von Gu'chi beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][104292] = {name = "[q3]Halbverdaute Mahlzeit", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese Schlange hat offensichtlich viel zu viel auf einmal gefressen, denn das Mahl scheint größtenteils ganz und unverdaut zu sein.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][104293] = {name = "[q2]Krabblerpanzer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig (10)\n[q2]Benutzen: Bedeckt Euren Kopf mit einem farbenfrohen Panzer und verringert so 1 Stunde lang den Radius, in dem Gegner Euch entdecken können. Kann nur in Pandaria verwendet werden. (5 Min Abklingzeit)\n[q]\"Die schimmernden Panzer der Dornzangen sind nützlich, um potenzielle Angreifer zu verwirren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104294] = {name = "[q3]Reif des zeitverlorenen Seefahrers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Singt die eindringliche Melodie der auf dem Schreckensschiff Vazuvius verloren gegangenen Besatzung. (2 Std. Abklingzeit)"}
MultiLanguageItemData['de'][104295] = {name = "[q3]Harmonisches Stachelschweinchen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euer harmonisches Stachelschwein beschwören oder wieder freigeben.\n80 ( 80)\nBenötigtKaiser Shaohao\n- Respektvoll"}
MultiLanguageItemData['de'][104296] = {name = "[q3]Zeremonielle Roben von Ordos", additional_info = "Wird beim Aufheben gebunden\n[q]\"Diese kunstvoll verzierten verzauberten Roben können in nützliche Bestandteile aufgetrennt werden.\"\n[q2]<Zum Öffnen rechtsklicken>"}
