MultiLanguageItemData['de'][104298] = {name = "[q4]Totenglocke von Ordos", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\n[q2]Benutzen: Stürmt auf einen Gegner zu, fügt Gegnern in einem Umkreis von 8 Metern 18 Feuerschaden zu und stößt sie für 3 Sek. auf den Boden. (2 Min Abklingzeit)\n[q]\"Die Anhänger von Ordos läuten diese Glocke, bevor Ordos ein Opfer dargebracht wird.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104299] = {name = "[q3]Flammenschnuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Schleudert den Benutzer als flammenden Meteor weit weg. (1 Stunde Abklingzeit)\n50 Aufladungen\n[q]\"Ein weißglühender Splitter aus dem Inneren von Glutfall.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104302] = {name = "[q3]Schwarzflammendolche", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\n[q2]Benutzen: Legt die Schwarzflammendolche an, um Eure Treue zu Ordos zu demonstrieren. (1 Stunde Abklingzeit)\n[q]\"Die Champions von Ordos verwenden diese zeremoniellen Dolche.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104303] = {name = "[q3]Regenstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Platziert einen Regenstein, der in der Umgebung 10 Min. lang eine unnatürliche Sturzflut auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n[q]\"Die verspielten Wassergeister Pandarias haben eine merkwürdige Verbindung mit dem Wetter.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104304] = {name = "[q3]Blizzardstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Platziert einen Blizzardstein, der in der Umgebung 10 Min. lang einen unnatürlichen Schneesturm auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n[q]\"Ranghohe Sänger von Ordos können das Wetter kontrollieren, sodass nie Schnee oder Regen auf die ewigen Feuer im Heiligtum von Ordos fällt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104305] = {name = "[q3]Aschestein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Platziert einen Aschestein, der in der Umgebung 10 Min. lang einen Aschesturm auslöst. (1 Stunde Abklingzeit)\n50 Aufladungen\n[q]\"Bevor sie angreifen, beschwören die Anhänger von Ordos oft einen Aschesturm, der ihren Feinden die Sicht unmöglich macht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104306] = {name = "[q3]Sonnenuntergangsstein", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Platziert einen Sonnenuntergangsstein, der die Tageszeit der Umgebung 10 Min. lang zu Sonnenuntergang ändert. (1 Stunde Abklingzeit)\n50 Aufladungen\n[q]\"Eine seltsame und potenziell ziemlich gefährliche Kuriosität, die in einem kleinen Gebiet den Fluss der Zeit anhalten kann.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][104307] = {name = "[q3]Jadefeuergeist", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\n[q2]Mit Rechtsklick Euren Jadefeuergeist beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][104308] = {name = "[q4]Akoliks säuregetränkte Roben", additional_info = "Heroisch\nWird beim Aufheben gebunden\n{Brust} {Stoff}\n4 Rüstung\n+1 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Sockelbonus: + 7 Intelligenz\n\nHaltbarkeit 165 / 165\nVerkaufspreis:"}
MultiLanguageItemData['de'][104309] = {name = "[q3]Ewiger Flammenkessel", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Baut einen ewigen Flammenkessel auf, der die Willenskraft aller in der Nähe um 4 erhöht und das Kochen ermöglicht. (30 Min Abklingzeit)\n[q]\"Anhänger von Ordos nehmen kleine Flammenkessel mit, wenn sie sich auf lange Reisen durch die Wildnis begeben.\""}
MultiLanguageItemData['de'][104311] = {name = "[q4]Beinplatten des unüberlegten Streits", additional_info = "Heroisch\nWird beim Aufheben gebunden\n{Beine} {Platte}\n15 Rüstung\n+1 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Sockelbonus: + 7 Stärke\n\nHaltbarkeit 120 / 120\nVerkaufspreis:"}
