MultiLanguageItemData['de'][104323] = {name = "[q2]Das runde Schweineleder", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Werft den Ball einem freundlich gesinnten Spieler zu. Wenn möglich, wird er ihn zurückwerfen!\n[q]\"Eine luftgefüllte Schweineblase, die in robustes Rindsleder gewickelt ist.\"\nVerkaufspreis:"}
