MultiLanguageItemData['de'][104325] = {name = "[q4]Wolkenschlange des tyrannischen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört eine reitbare Wolkenschlange des tyrannischen Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"In klassischem Schwarz sehen diese Wolkenschlangen immer sehr elegant und schlank aus.\"\nKlassisch"}
MultiLanguageItemData['de'][104326] = {name = "[q4]Wolkenschlange des erbitterten Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört eine reitbare Wolkenschlange des erbitterten Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Schuppenfarben dieser strahlend bunten Wolkenschlangen sind eine Mischung aus Rubinrot, Gold und beinahe Violett.\"\nKlassisch"}
MultiLanguageItemData['de'][104327] = {name = "[q4]Wolkenschlange des stolzen Gladiators", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\n[q2]Beschwört eine reitbare Wolkenschlange des stolzen Gladiators oder gibt sie wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Schuppenfarben dieser strahlend bunten Wolkenschlangen reichen von Gold zu Pink. Aber wir könnten sie auch korallenfarben nennen.\"\nKlassisch"}
MultiLanguageItemData['de'][104328] = {name = "[q3]Kauterisierender Kern", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Aktiviert den Kern und ermöglicht es dem Träger, mit 20% Gesundheit und Mana wiederbelebt zu werden. Kann nur in Pandaria verwendet werden. (1 Stunde Abklingzeit)\n20 Aufladungen\n[q]\"Ein feuriger Kern, der die lebendige Essenz des geschmolzenen Wächters enthält.\""}
MultiLanguageItemData['de'][104329] = {name = "[q3]Aschebedecktes Horn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Beschwört ein reitbares, aber unkontrollierbares wütendes Aschefellmushan. Das ist ein sehr, SEHR schnelles Reittier. Kann nur auf der Zeitlosen Insel verwendet werden. (1 Min Abklingzeit)\n[q]\"Immer etwas warm.\""}
