MultiLanguageItemData['de'][109013] = {name = "[q4]Zügel des Schreckensraben", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q2]Beschwört einen Schreckensraben oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Mit dem Hass eines uralten Gottes erfüllt, sind die Schreckensraben die vertrautesten Wächter der Arakkoa.\"\nPromotion:\nWarlords of Draenor Collector's Edition"}
MultiLanguageItemData['de'][109014] = {name = "[q3]Küken des Schreckens", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Lehrt Euch, wie man ein Küken des Schreckens beschwört.\n[q2]Mit Rechtsklick Euer Küken des Schreckens beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][109023] = {name = "Serathil", additional_info = "Questgegenstand\n[q]\"Diese Klinge brodelt vor urzeitlicher Macht. Nur die fähigsten Oger können den Willen der Waffe brechen.\""}
