MultiLanguageItemData['de'][109025] = {name = "Probe Schwarzfelserz", additional_info = "Questgegenstand\n[q]\"Dieses unbearbeitete Erz ist das Hauptmaterial, das die Eiserne Horde für den Maschinenbau verwendet. Es kann zu widerstandsfähigem Metall verarbeitet oder als Legierung mit anderen Bestandteilen als Sprengstoff verwendet werden.\""}
