MultiLanguageItemData['de'][109060] = {name = "[q3]Rylakschuppenweste", additional_info = "Wird beim Aufheben gebunden\n{Brust} {Kette}\n11 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]+ 5 Vielseitigkeit\nHaltbarkeit 140 / 140\nVerkaufspreis:"}
MultiLanguageItemData['de'][109061] = {name = "[q3]Ku'targs gnadenloser Handschutz", additional_info = "Wird beim Aufheben gebunden\n{Hände} {Kette}\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+5 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 50 / 50\nVerkaufspreis:"}
MultiLanguageItemData['de'][109062] = {name = "[q3]Magierturm, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euren Magierturm auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\n Level 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\n Level 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:"}
MultiLanguageItemData['de'][109063] = {name = "[q3]Magierturm, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euren Magierturm auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\n Level 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\n Level 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nBenötigt den Erfolg \"Portalsteine schlagen Portalscheren\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][109065] = {name = "[q3]Mondsturzgasthaus, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euer Mondsturzgasthaus auf Stufe 3 ausbauen könnt.\n\n Level 1\nQuartiert jeden Tag einen Abenteurer in Eurem Gasthaus ein, der eine Dungeonquest mit großzügigen Belohnungen anbietet.\n\n Level 2\nHeuert jede Woche zufällige Anhänger an. Ihr könnt bestimmte Eigenschaften und Fähigkeiten angeben, an denen Ihr besonders interessiert seid.\n\n Level 3\nSchaltet die besonders lukrativen Missionen für Garnisonsressourcen frei.\nBenötigt den Erfolg \"Bleibt ein Weilchen und hört zu\".\nVerkaufspreis:"}
