MultiLanguageItemData['de'][109164] = {name = "Klebrige Teerbombe", additional_info = "Questgegenstand\n[q2]Benutzen: Wirft eine klebrige Teerbombe, um Brüterkäfige in Aguraks Ende zu zerstören.\n[q]\"Die Bombe erst dann einer offenen Flamme aussetzen, wenn sie einsatzbereit ist.\""}
MultiLanguageItemData['de'][109167] = {name = "[q3]Findels Plünderang", additional_info = "Wird bei Benutzung gebunden\nSpielzeug\n[q2]Benutzen: Sammelt die Beute von einer Leiche in der Nähe ein. Kann nur in Draenor verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][109168] = {name = "[q4]Eisenschredders Schredder", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\n{Distanz} {Schusswaffe}\n7 - 13 Schaden Geschwindigkeit 3.00\n(3.3 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\n[q]\"Für Ingenieure ein Kunstwerk. Für Jäger ein Werkzeug für die Kunst des Tötens.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109171] = {name = "[q4]Nachtsichtmechbrille", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\n{Kopf} {Leder}\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\n[q2]Benutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:"}
