MultiLanguageItemData['de'][109174] = {name = "[q4]Klingenschutzmechbrille", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\n{Kopf} {Platte}\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\n[q2]Benutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][109183] = {name = "[q3]Weltschrumpfer", additional_info = "Spielzeug\n[q2]Benutzen: Schrumpft die gesamte Welt 5 Min. lang oder bis Ihr angreift. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)\n[q]\"Übermäßiger Gebrauch kann zu dauerhafter Schrumpfung führen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109184] = {name = "Tarner 54", additional_info = "[q2]Benutzen: Umgibt den Anwender mit einem Tarnfeld, solange er stillhält. Kann nicht im Kampf verwendet werden. Nach einer Bewegung bleibt das Feld noch bis zu 6 Sek. lang erhalten.\n\n Der Tarner teilt sich eine Abklingzeit mit allen Tränken außer Heiltränken. Funktioniert nicht über Stufe 49. (5 Min Abklingzeit)\n[q]\"Unsichtbarkeit ist für Schwächlinge!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109186] = {name = "Hagras Splitter", additional_info = "Questgegenstand\n[q]\"Beim Berühren des Splitters habt Ihr das Gefühl, dass Eure Seele von etwas Öligem und Schmutzigem überzogen wird.\""}
MultiLanguageItemData['de'][109187] = {name = "Grogals Splitter", additional_info = "Questgegenstand\n[q]\"Die Dunkelheit im Innern vibriert, als ob etwas zu entkommen versuchen würde.\""}
MultiLanguageItemData['de'][109192] = {name = "[q0]Lichtbringer", additional_info = "[q]\"Dieser abgenutzte Streitkolben gehörte einst einer Wache Shattraths. Noch immer dringt aus seinem Inneren Licht, auch wenn es langsam zu verblassen scheint.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109196] = {name = "Vom Kampf gezeichnetes Frostwolfbanner", additional_info = "Questgegenstand\nEinzigartig\n[q2]Benutzen: Rammt ein vom Kampf gezeichnetes Frostwolfbanner in die Leichname von getöteten Donnerfürsten im Rippenbrecherkriegslager. (2 Sek. Abklingzeit)"}
