MultiLanguageItemData['de'][109222] = {name = "Draenischer Manatrank", additional_info = "[q2]Benutzen: Stellt 1700 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][109223] = {name = "Heiltonikum", additional_info = "[q2]Benutzen: Stellt 3400 Gesundheit wieder her. (5 Min Abklingzeit)\n[q]\"Richtig vorbereitet kann das Gift des Seeskorpions Gesundheit wiederherstellen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109224] = {name = "Seelensplitter von Gul'var", additional_info = "Questgegenstand\n[q2]Benutzen: Verbindet die Seelensplitter in der Schmiede von Gul'var, um Gul'dans Seelenfalle herzustellen."}
MultiLanguageItemData['de'][109225] = {name = "Gul'dans Seelenfalle", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Das Ganze fühlt sich nach mehr als die Summe seiner Teile an.\""}
MultiLanguageItemData['de'][109226] = {name = "Draenischer Trank der Verjüngung", additional_info = "[q2]Benutzen: Stellt 3400 Gesundheit und 850 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][109246] = {name = "Gul'dans Seelenfalle", additional_info = "Questgegenstand\n[q2]Benutzen: Fesselt Gul'dans Seele und setzt ihn gefangen, um ihn zu Erzmagier Khadgar beim Außenposten Sternenfall zurückzubringen. (20 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][109248] = {name = "Entwurf einer Belagerungswaffe", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Auf dem Plan ist eine barbarische und brutale Waffe abgebildet.\""}
MultiLanguageItemData['de'][109253] = {name = "[q2]Ultimatives gnomisches Armeemesser", additional_info = "+10 Fertigkeit in Bergbau von Draenor.\n +10 Fertigkeit in Kräuterkunde von Draenor.\n +10 Fertigkeit in Kürschnerei von Draenor.\n[q]\"Beinhaltet alles erforderliche Handwerkszeug.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109254] = {name = "[q3]Sägewerk, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr das Sägewerk in Eurer Garnison auf Stufe 2 aufwerten könnt.\n\n Level 1\nErmöglicht Euch, kleine Bäume in Draenor zu markieren, die gefällt werden sollen. Das so gewonnene Holz kann in Arbeitsaufträge für Garnisonsvorräte umgewandelt werden.\n\n Level 2\nErmöglicht, mittelgroße Bäume zu markieren, um zusätzliches Holz zu gewinnen.\n\n Level 3\nMit dem Sägewerk können größere Bäume markiert werden, was die Holzproduktion steigert.\nBenötigt den Abschluss der Außenpostenquests in den Spitzen von Arak oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][109255] = {name = "[q3]Sägewerk, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr das Sägewerk in Eurer Garnison auf Stufe 3 aufwerten könnt.\n\n Level 1\nErmöglicht Euch, kleine Bäume in Draenor zu markieren, die gefällt werden sollen. Das so gewonnene Holz kann in Arbeitsaufträge für Garnisonsvorräte umgewandelt werden.\n\n Level 2\nErmöglicht, mittelgroße Bäume zu markieren, um zusätzliches Holz zu gewinnen.\n\n Level 3\nMit dem Sägewerk können größere Bäume markiert werden, was die Holzproduktion steigert.\nBenötigt den Erfolg \"Das Sägewerk aufwerten\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][109256] = {name = "[q3]Ingenieurlabor, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Ingenieurlabor auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Ingenieursgegenständen und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Ingenieurskunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Ingenieursmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][109257] = {name = "[q3]Ingenieurlabor, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Euer Ingenieurlabor auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Ingenieursgegenständen und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Ingenieurskunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Ingenieursmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Ein paar Aufträge mehr\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][109258] = {name = "[q3]Ingenieurlabor, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Ingenieurlabor bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Ingenieursgegenständen und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Ingenieurskunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Ingenieursmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:"}
MultiLanguageItemData['de'][109259] = {name = "Zauberbuch des Schattenrats", additional_info = "Questgegenstand\n[q]\"Wenn dieses Buch gefunden wird, bitte den Zauber auf Seite 42 wirken.\""}
MultiLanguageItemData['de'][109261] = {name = "Alchemistenkessel", additional_info = "Wird beim Aufheben gebunden\n[q]\"Liefert metamorphische Kristalle und alchemische Katalysatoren.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][109262] = {name = "[q3]Draenischer Stein der Weisen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n[q2]Anlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie von Draenor\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109557] = {name = "Mutationsserum", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Auf Grulk anwenden, um seine Mutantenstärke wiederherzustellen.\""}
MultiLanguageItemData['de'][109558] = {name = "[q3]Eine Abhandlung über die Alchemie Draenors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Bildet Euch in der Alchemie von Draenor aus und lehrt Euch einige Rezepte.\nBenötigtAlchemie\n(1)\n[q]\"Eine Einführung in die Geheimnisse der draenischen Alchemie.\""}
MultiLanguageItemData['de'][109574] = {name = "[q3]GUMM-E", additional_info = "Wird bei Benutzung gebunden\nEinzigartig: Gegenstand aus dem Ingenieurlabor (1)\n[q2]Benutzen: Stellt einen tragbaren Briefkasten auf, der 5 Min. lang bestehen bleibt. (3 Std. Abklingzeit)\n3 Aufladungen\n[q]\"Dieser spezielle Briefkasten ist normalerweise zu kompliziert für den Durchschnittsbürger, daher besitzt er extragroße Knöpfe und eine Anleitung.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][109575] = {name = "Auch'naaru", additional_info = "Questgegenstand\n[q]\"Eines der drei Fragmente des Herzens von Auchindoun.\""}
MultiLanguageItemData['de'][109576] = {name = "[q3]Mondsturzausgrabung, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Mondsturzausgrabung auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\n Level 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt Mine\nVerkaufspreis:"}
MultiLanguageItemData['de'][109577] = {name = "[q3]Kräutergarten, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Kräutergarten in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nLässt täglich aus draenischen Samen Kräuter heranwachsen und macht Kräuter im Garten verfügbar.\n\n Level 2\nErmöglicht es Anhängern mit der Eigenschaft 'Kräuterkunde', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Erhöht außerdem die Menge an Kräutern, die im Garten geerntet werden können und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nPflanzt einen einzigartigen Draenorobstbaum in Eurem Garten, der Nahrungsstärkungseffekte gewährt. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt Kräutergarten\nVerkaufspreis:"}
MultiLanguageItemData['de'][109578] = {name = "[q3]Angelhütte", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Angelhütte in Eurer Garnison reparieren könnt.\n\n Level 1\nErmöglicht es Euch, in den Gewässern der Garnison kleine draenische Fische zu fangen. Gewährt außerdem Zugriff auf tägliche Angelquests.\n\n Level 2\nErmöglicht es Euch, mittelgroße draenische Fische in den Gewässern der Garnison zu fangen.\n\n Level 3\nErmöglicht es Euch, riesige draenische Fische in den Gewässern der Garnison fangen. Gewährt zusätzlich eine Chance, einen einzigartigen Fisch zu fangen, der dazu verwendet werden kann, mysteriöse Kreaturen an Land zu locken.\nVerkaufspreis:"}
MultiLanguageItemData['de'][109584] = {name = "[q2]Ogerschreiben", additional_info = "[q]\"Schlüsselstein, der archäologische Artefakte der Oger mit fehlenden Fragmenten vervollständigen kann.\"\nVerkaufspreis:"}
