MultiLanguageItemData['de'][109599] = {name = "Neuraler Stummschalter", additional_info = "[q2]Benutzen: Macht Euch immun gegen manche Ärgernisse. Bleibt über den Tod hinaus bestehen Hält 12 Stunden lang an.\n[q]\"Ärgernisse schließen 'Glaubenssprung', Fähigkeiten zur Bedrohungsumleitung und manche Gerätschaften wie den Wechselblaster ein.\"\nVerkaufspreis:"}
