MultiLanguageItemData['de'][110288] = {name = "Arens Thermometer", additional_info = "Questgegenstand\n[q2]Benutzen: Lest die Temperatur in der Nähe des zischenden Geysirs im Rauchfelskessel ab. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][110289] = {name = "Köder für dicke Schläfer", additional_info = "Einzigartig\n[q2]Benutzen: Dicke Schläfer schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n[q]\"Nützlich beim Fischen in Nagrand. Dicke Schläfer finden alles Süße unwiderstehlich.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][110290] = {name = "Köder für blinde Seestöre", additional_info = "Einzigartig\n[q2]Benutzen: Blinde Seestöre schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n[q]\"Nützlich beim Fischen im Schattenmondtal. Die Bewegungen der am Boden lebenden Sandkrebse erregen die Aufmerksamkeit blinder Seestöre.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][110291] = {name = "Köder für Feuerammoniten", additional_info = "Einzigartig\n[q2]Benutzen: Feuerammoniten schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n[q]\"Nützlich beim Fischen im Frostfeuergrat. Frostfeuerfrüchte sind für die meisten Humanoiden tödlich, doch Feuerammoniten sind ganz wild darauf.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][110292] = {name = "Köder für Seeskorpione", additional_info = "Einzigartig\n[q2]Benutzen: Seeskorpione schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n[q]\"Nützlich beim Fischen im Meer. Seeskorpione reißen Seesternen gerne die Beine aus und verschlingen sie einzeln.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][110293] = {name = "Köder für Tiefenschluckaale", additional_info = "Einzigartig\n[q2]Benutzen: Tiefenschluckaale schenken Eurer Angelrute 10 Min. lang erhöhte Aufmerksamkeit.\n[q]\"Nützlich beim Fischen in den Spitzen von Arak. Froschfische haben eine so seltsame Gestalt, dass nur Schluckaale sie fressen können.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][110294] = {name = "Köder für Schwarzwasserpeitschflossen", additional_info = "Einzigartig\n[q2]Benutzen: Erhöht 10 Min. lang die Chance, Schwarzwasserpeitschflossen zu fangen.\n[q]\"Nützlich beim Fischen in Talador. Sandklaffmuscheln sind die Lieblingsspeise der Schwarzwasserpeitschflossen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][110295] = {name = "Herz von Gorgorek", additional_info = "Questgegenstand"}
MultiLanguageItemData['de'][110313] = {name = "Wolfsflaum", additional_info = "Questgegenstand\n[q]\"Riecht nach Wildnis... und nach Moschus. Aber vorrangig nach Wildnis.\""}
MultiLanguageItemData['de'][110375] = {name = "Borgals Totem der Flammenbindung", additional_info = "Questgegenstand\n[q]\"Es tropft noch immer Lava daran herab.\""}
MultiLanguageItemData['de'][110378] = {name = "Borgals Totem der Geisterbindung", additional_info = "Questgegenstand\n[q]\"Ihr hört ein leises Flüstern, könnt jedoch nicht verstehen, was gesagt wird.\""}
MultiLanguageItemData['de'][110379] = {name = "Borgals Totem der Wasserbindung", additional_info = "Questgegenstand\n[q]\"Vom faulen Wasser, das dieses Totem bedeckt, sollte man sich besser fernhalten.\""}
MultiLanguageItemData['de'][110380] = {name = "Borgals Totem der Windbindung", additional_info = "Questgegenstand\n[q]\"Dem Totem hängt ein übler Geruch an.\""}
