MultiLanguageItemData['de'][110391] = {name = "Unbearbeitete Kraftkristalle", additional_info = "Questgegenstand\n[q]\"Obwohl diese Kristalle roh und unbearbeitet sind, strahlen sie arkane Energie aus.\""}
MultiLanguageItemData['de'][110394] = {name = "Leuchtender Seelensplitter", additional_info = "Questgegenstand\n[q2]Benutzen: Läutert den Geist einer besiegten wahnsinnigen Seele. (3 Sek. Abklingzeit)\n[q]\"Von diesem zarten Kristallsplitter geht ein schwaches Licht aus.\""}
MultiLanguageItemData['de'][110418] = {name = "Kristallriesenherz", additional_info = "Questgegenstand\n[q]\"Das Herz fühlt sich kalt an und in seinem Innern pocht arkane Energie.\""}
MultiLanguageItemData['de'][110424] = {name = "[q3]Wilder Safarihelm", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Erhöht die von Kampfhaustieren gewonnene Erfahrung um 20%. (3 Sek. Abklingzeit)\nBenötigt Kampfhaustiertraining\n[q]\"Die Haustierjagd ist eine gefährliche Angelegenheit. Tragt dabei immer Euren Hut.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][110425] = {name = "[q3]Gnomischer Feiervollstrecker", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bringt Euch für ein Foto in Pose! (30 Min Abklingzeit)"}
MultiLanguageItemData['de'][110426] = {name = "[q2]Goblinisches heißes Eisen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Versucht, das goblinische heiße Eisen einem verbündeten Spielercharakter zuzuwerfen. Falls er Platz in seinem Rucksack hat, wird er es fangen... vorausgesetzt, Ihr könnt es sicher werfen! (2 Sek. Abklingzeit)\nBenötigtWerterhaltungsgesellschaft des Dampfdruckkartells\n- Wohlwollend\nVerkaufspreis:"}
