MultiLanguageItemData['de'][110428] = {name = "[q3]Goblinischer Bodybuilderwettkampf", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Bringt Eure Muskeln zur Geltung! (30 Min Abklingzeit)"}
MultiLanguageItemData['de'][110431] = {name = "Lederwasserball", additional_info = "[q2]Benutzen: Werft den Ball einem freundlich gesinnten Spieler zu. Falls er Platz in seinem Rucksack hat, wird er ihn fangen! (10 Sek. Abklingzeit)\nVerkaufspreis:"}
