MultiLanguageItemData['de'][111349] = {name = "[q3]Eine Abhandlung über den Bergbau auf Draenor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch im Bergbau von Draenor aus.\nBenötigt Bergbau (1)\n[q]\"Ein Überblick über die Eigenschaften der wertvollen Mineralien Draenors und ihrer Abbaumethoden.\""}
MultiLanguageItemData['de'][111350] = {name = "[q3]Ein Kompendium der Kräuter Draenors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Kräuterkunde von Draenor aus.\nBenötigt Kräuterkunde (1)\n[q]\"Enthält eine Übersicht der magischen Kräuter Draenors und wie man sie erntet.\""}
MultiLanguageItemData['de'][111351] = {name = "[q3]Ratgeber zum Kürschnern auf Draenor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Kürschnerei von Draenor aus.\nBenötigt Kürschnerei (1)\n[q]\"Wie man Draenors Tiere häutet.\""}
MultiLanguageItemData['de'][111356] = {name = "[q3]Anglerhandbuch für Draenor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Bildet Euch in der Angelkunst von Draenor aus.\nBenötigt Angeln (1)\n[q]\"Ein Überblick über Draenors Fische und wie man sie fängt.\""}
MultiLanguageItemData['de'][111357] = {name = "[q2]Mörserschützenpfeife", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Beschwört die Unterstützung eines Zwergenmörseringenieurs, der Gegner in der Nähe angreift. Nach 30 Sek. verschwindet der Ingenieur.\n[q]\"Am hinteren Ende ist eine kleine Bombe eingraviert.\"\nVerkaufspreis:"}
