MultiLanguageItemData['de'][111387] = {name = "[q3]Kochen auf Draenor leicht gemacht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Kochkunst von Draenor aus und lehrt Euch einige Rezepte.\nBenötigt Kochkunst (1)\n[q]\"Lehrt Euch Draenorkochkunst und ein paar einfache Rezepte.\""}
