MultiLanguageItemData['de'][111457] = {name = "Festmahl des Blutes", additional_info = "[q2]Benutzen: Sättigt bis zu 30 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl des Blutes.\n\n Dabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111458] = {name = "Festmahl der Gewässer", additional_info = "[q2]Benutzen: Sättigt bis zu 10 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl der Gewässer.\n\n Dabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\nVerkaufspreis:"}
