MultiLanguageItemData['de'][111816] = {name = "[q3]Maßschneiderei, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Maßschneiderei bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Schneidereierzeugnissen und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Schneiderei', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Schneidereimissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111817] = {name = "[q3]Verzauberungsatelier, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Verzauberungsatelier bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Gegenständen der Verzauberkunst und ermöglicht Charakteren ohne Verzauberfertigkeit, Gegenstände zu entzaubern. Gewährt außerdem Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Verzauberkunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Verzauberkunstmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111818] = {name = "[q3]Gerberei, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Gerberei bauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Lederverarbeitung und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Lederverarbeitung', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Lederverarbeitungsmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111820] = {name = "[q3]Wechselblaster", additional_info = "Wird bei Benutzung gebunden\n[q2]Benutzen: Tauscht Eure Position mit der eines anderen Gruppenmitglieds. Kann nicht im Kampf genutzt werden. (1 Min Abklingzeit)\n[q]\"Achtung: Der Tausch mit einem Ziel, das einen neuralen Stummschalter verwendet, ist lebensgefährlich.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][111821] = {name = "[q4]Blingtron 5000", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Setzt den verbesserten Blingtron 5000 zusammen, einen wilden, aber großzügigen Roboter. Einerseits lässt er Spielercharakteren einmal am Tag kleine Präsente zukommen, anderseits bekämpft er andere Blingtron-Einheiten bis zum Tode. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)"}
MultiLanguageItemData['de'][111842] = {name = "Sternwurzelknolle", additional_info = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (20)\n[q2]Benutzen: Stellt 32 Gesundheit wieder her und verringert 10 Sek. lang den erlittenen Schaden um 40%. Kann nur in Ashran verwendet werden. (3 Min Abklingzeit)"}
