MultiLanguageItemData['de'][111922] = {name = "[q3]Verzauberkunst von Draenor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lernt die Geheimnisse der Verzauberkunst von Draenor und einige Rezepte kennen.\nBenötigt Verzauberkunst (1)\n\"Eine Einführung in die Geheimnisse der draenischen Verzauberkunst.\""}
MultiLanguageItemData['de'][111923] = {name = "[q3]Inschriftenkunde von Draenor", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Bildet Euch in der Inschriftenkunde von Draenor aus und lehrt Euch einige Rezepte.\nBenötigt Inschriftenkunde (1)\n\"Eine Einführung in die Geheimnisse der draenischen Inschriftenkunde\""}
MultiLanguageItemData['de'][111924] = {name = "[q3]Gnomische Werkstatt, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine gnomische Werkstatt bauen könnt.\n\n Level 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\n Level 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\n Level 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nVerkaufspreis:"}
MultiLanguageItemData['de'][111926] = {name = "[q4]Kodex des Aufstiegs", additional_info = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Priester\n[q2]Benutzen: Lehrt Euch den Zauber 'Aufstieg'. Hält 1 Stunde lang an. Kann nur in Ashran verwendet werden."}
MultiLanguageItemData['de'][111927] = {name = "[q3]Angelhütte, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Angelhütte in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht es Euch, in den Gewässern der Garnison kleine draenische Fische zu fangen. Gewährt außerdem Zugriff auf tägliche Angelquests.\n\n Level 2\nErmöglicht es Euch, mittelgroße draenische Fische in den Gewässern der Garnison zu fangen.\n\n Level 3\nErmöglicht es Euch, riesige draenische Fische in den Gewässern der Garnison fangen. Gewährt zusätzlich eine Chance, einen einzigartigen Fisch zu fangen, der dazu verwendet werden kann, mysteriöse Kreaturen an Land zu locken.\nBenötigt Angelhütte\nVerkaufspreis:"}
MultiLanguageItemData['de'][111928] = {name = "[q3]Angelhütte, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Angelhütte in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht es Euch, in den Gewässern der Garnison kleine draenische Fische zu fangen. Gewährt außerdem Zugriff auf tägliche Angelquests.\n\n Level 2\nErmöglicht es Euch, mittelgroße draenische Fische in den Gewässern der Garnison zu fangen.\n\n Level 3\nErmöglicht es Euch, riesige draenische Fische in den Gewässern der Garnison fangen. Gewährt zusätzlich eine Chance, einen einzigartigen Fisch zu fangen, der dazu verwendet werden kann, mysteriöse Kreaturen an Land zu locken.\nBenötigt den Erfolg \"Draenorangler\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111929] = {name = "[q3]Alchemielabor, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euer Alchemielabor auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Alchemie und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Alchemie', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Alchemiemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111930] = {name = "[q3]Alchemielabor, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euer Alchemielabor auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Alchemie und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Alchemie', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Alchemiemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Ein paar Aufträge mehr\".\nVerkaufspreis:"}
