MultiLanguageItemData['de'][111955] = {name = "[q3]Skogs Tuch", additional_info = "Wird beim Aufheben gebunden\nRücken\n3 Rüstung\n+2 Stärke\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111956] = {name = "[q3]Kaserne, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Kaserne bauen könnt."}
MultiLanguageItemData['de'][111957] = {name = "[q3]Wiederverwertung, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Wiederverwertung bauen könnt.\n\n Level 1\nErmöglicht, bei Missionen gelegentlich Bergungsgut zu finden.\n\n Level 2\nErhöht die Wahrscheinlichkeit, bei Missionen Bergungsgut zu finden. Zusätzlich besteht jetzt die Chance, dass sich im Bergungsgut auch Gegenstände für Eure Anhänger befinden.\n\n Level 3\nErhöht drastisch die Wahrscheinlichkeit, dass bei Missionen Bergungsgut gefunden wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111958] = {name = "[q3]Lagerhaus, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Lagerhaus bauen könnt.\n\n Level 1\nErmöglicht Euch Zugang zu Eurer persönlichen Bank und erhöht die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 5.\n\n Level 2\nErmöglicht Euch Zugang zu Eurer Gildenbank.\n\n Level 3\nErmöglicht Euch Zugriff auf einen astralen Händler, der Transmogrifikations- und Leerenlagerdienste anbietet. Erhöht außerdem die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 15.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111959] = {name = "[q3]Scheune, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison eine Scheune bauen könnt.\n\n Level 1\nErmöglicht es Euch Grollhufe, Elekks, Wölfe und Talbuks zu fangen, um Leder und Pelze zu gewinnen. die in Rezepten für Lederverarbeitung und Schneiderei benötigt werden.\n\n Level 2\nErlaubt es Euch, Eber und Flussbestien fangen, deren seltenes Fleisch zur stärksten Nahrung verarbeitet werden kann.\n\n Level 3\nErmöglicht es Euch, Elitetiere zu fangen, um Wildblut zu erhalten, das für alle hergestellten epischen Rüstungen und Waffen verwendet wird.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111960] = {name = "[q3]Mondsturzgasthaus, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Mondsturzgasthaus bauen könnt.\n\n Level 1\nQuartiert jeden Tag einen Abenteurer in Eurem Gasthaus ein, der eine Dungeonquest mit großzügigen Belohnungen anbietet.\n\n Level 2\nHeuert jede Woche zufällige Anhänger an. Ihr könnt bestimmte Eigenschaften und Fähigkeiten angeben, an denen Ihr besonders interessiert seid.\n\n Level 3\nSchaltet die besonders lukrativen Missionen für Garnisonsressourcen frei.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111961] = {name = "[q3]Sägewerk, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt die erforderlichen Pläne zur Errichtung eines Sägewerkes.\n\n Dieses Gebäude generiert eine tägliche Lieferung von Garnisonsmaterialien.\n\n Level 1\nErmöglicht Euch, kleine Bäume in Draenor zu markieren, die gefällt werden sollen. Das so gewonnene Holz kann in Arbeitsaufträge für Garnisonsvorräte umgewandelt werden.\n\n Level 2\nErmöglicht, mittelgroße Bäume zu markieren, um zusätzliches Holz zu gewinnen.\n\n Level 3\nMit dem Sägewerk können größere Bäume markiert werden, was die Holzproduktion steigert.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111962] = {name = "[q3]Heiligtum des Gladiators, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison ein Heiligtum des Gladiators bauen könnt.\n\n Level 1\nErhöht Eure Erholung in den Außengebieten von Draenor, wenn Ihr Euch nicht im Kampf befindet, und ermöglicht das Sammeln gebrochener Knochen von gegnerischen Spielercharakteren, die Ihr besiegt habt (benötigt für Tribut des Eroberers).\n\n Level 2\nErmöglicht sicheres Fallen und Unterwasseratmung in Außengebieten von Draenor. Ermöglicht außerdem Nemesisquests, für die Ihr gegnerische Spielercharaktere aus bestimmten Völkern besiegen müsst.\n\n Level 3\nWenn Ihr über weniger als 35% Gesundheit verfügt, wird sämtlicher erlittene Schaden in Außengebieten von Draenor um 50% verringert. Gewährt außerdem Zugang zum Gladiatorenturnier im Kolosseum von Hochfels.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111963] = {name = "[q3]Handelsposten, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Handelsposten bauen könnt.\n\n Level 1\nJeden Tag kommt ein Händler vorbei, bei dem Ihr Handwerkswaren kaufen könnt. Ermöglicht, Handwerksmaterialien gegen Garnisonsressourcen einzutauschen.\n\n Level 2\nGewährt Zugang zur Fraktion Sha'tarverteidigung (Allianz) oder Lachender Schädel (Horde). Schaltet außerdem ein Auktionskonstrukt frei, das jedoch erst mit speziellen Teilen aus ganz Draenor repariert werden muss.\n\n Level 3\nErhöht den Rufzuwachs in Draenor um 20%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111964] = {name = "[q3]Zwergenbunker, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Zwergenbunker bauen könnt.\n\n Level 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\n Level 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\n Level 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nVerkaufspreis:"}
MultiLanguageItemData['de'][111965] = {name = "[q3]Magierturm, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Magierturm bauen könnt.\n\n Level 1\nErmöglicht das Sammeln von Ogerportalsteinen auf Draenor. Diese Ogerportalsteine erlauben es Euch, ein Ogerportal Eurer Wahl in Draenor mit Energie zu versorgen. Erzeugt außerdem während des Kampfes gelegentlich Runen der Kraft.\n\n Level 2\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 2)\n\n Level 3\nGewährt Euch Zugriff auf ein weiteres Ogerportal. (Insgesamt 3)\nVerkaufspreis:"}
MultiLanguageItemData['de'][111966] = {name = "[q3]Zwergenbunker, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euren Zwergenbunker auf Stufe 2 ausbauen könnt.\n\n Level 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\n Level 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\n Level 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111967] = {name = "[q3]Zwergenbunker, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euren Zwergenbunker auf Stufe 3 ausbauen könnt.\n\n Level 1\nVerdoppelt die Chance auf seltene oder epische Bonusaufwertungen durch Quests und erhöht die Stärke der Aufwertung. Lässt Euch außerdem Rüstungsfetzen von den Orcklans Draenors zur Rüstungstransmogrifikation sammeln.\n\n Level 2\nErmöglicht Arbeitsaufträge für Waffen und Rüstung von Anhängern im Tausch gegen Garnisonsressourcen. Schaltet außerdem zusätzliche Vorlagen für die Rüstungstransmogrifikation frei.\n\n Level 3\nGewährt jede Woche kostenlos eines Eurer drei Siegel des unausweichlichen Schicksals (Bonuswurfmarken).\nBenötigt den Erfolg \"Die Reihen füllen\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111968] = {name = "[q3]Scheune, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Scheune in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht es Euch Grollhufe, Elekks, Wölfe und Talbuks zu fangen, um Leder und Pelze zu gewinnen. die in Rezepten für Lederverarbeitung und Schneiderei benötigt werden.\n\n Level 2\nErlaubt es Euch, Eber und Flussbestien fangen, deren seltenes Fleisch zur stärksten Nahrung verarbeitet werden kann.\n\n Level 3\nErmöglicht es Euch, Elitetiere zu fangen, um Wildblut zu erhalten, das für alle hergestellten epischen Rüstungen und Waffen verwendet wird.\nBenötigt den Abschluss der Außenpostenquests in den Spitzen von Arak oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111969] = {name = "[q3]Scheune, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Scheune in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht es Euch Grollhufe, Elekks, Wölfe und Talbuks zu fangen, um Leder und Pelze zu gewinnen. die in Rezepten für Lederverarbeitung und Schneiderei benötigt werden.\n\n Level 2\nErlaubt es Euch, Eber und Flussbestien fangen, deren seltenes Fleisch zur stärksten Nahrung verarbeitet werden kann.\n\n Level 3\nErmöglicht es Euch, Elitetiere zu fangen, um Wildblut zu erhalten, das für alle hergestellten epischen Rüstungen und Waffen verwendet wird.\nBenötigt den Erfolg \"Meisterfallensteller\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111970] = {name = "[q3]Kaserne, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Kaserne in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nSchaltet Patrouillenmissionen frei. Patrouillenmissionen erzielen einen erhöhten Erfahrungsbonus für Anhänger.\n\n Level 2\nGestattet es einem Eurer Anhänger mit der Eigenschaft 'Leibwächter', Euch in Gebieten auf Draenor zu begleitet.\n\n Level 3\nErhöht die maximale Anzahl an Anhängern um 5 und gewährt Zugriff auf Wachen und Banner spezifischer Völker.\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111971] = {name = "[q3]Kaserne, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Kaserne in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nSchaltet Patrouillenmissionen frei. Patrouillenmissionen erzielen einen erhöhten Erfahrungsbonus für Anhänger.\n\n Level 2\nGestattet es einem Eurer Anhänger mit der Eigenschaft 'Leibwächter', Euch in Gebieten auf Draenor zu begleitet.\n\n Level 3\nErhöht die maximale Anzahl an Anhängern um 5 und gewährt Zugriff auf Wachen und Banner spezifischer Völker.\nBenötigt den Erfolg \"Patrouillen in Draenor\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111972] = {name = "[q3]Verzauberungsatelier, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr das Verzauberungsatelier in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Gegenständen der Verzauberkunst und ermöglicht Charakteren ohne Verzauberfertigkeit, Gegenstände zu entzaubern. Gewährt außerdem Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Verzauberkunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Verzauberkunstmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111973] = {name = "[q3]Verzauberungsatelier, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr das Verzauberungsatelier in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Gegenständen der Verzauberkunst und ermöglicht Charakteren ohne Verzauberfertigkeit, Gegenstände zu entzaubern. Gewährt außerdem Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Verzauberkunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Verzauberkunstmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Ein paar Aufträge mehr\".\nVerkaufspreis:"}
