MultiLanguageItemData['de'][111976] = {name = "[q3]Wiederverwertung, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Wiederverwertung in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht, bei Missionen gelegentlich Bergungsgut zu finden.\n\n Level 2\nErhöht die Wahrscheinlichkeit, bei Missionen Bergungsgut zu finden. Zusätzlich besteht jetzt die Chance, dass sich im Bergungsgut auch Gegenstände für Eure Anhänger befinden.\n\n Level 3\nErhöht drastisch die Wahrscheinlichkeit, dass bei Missionen Bergungsgut gefunden wird.\nBenötigt Wiederverwertung\nVerkaufspreis:"}
MultiLanguageItemData['de'][111977] = {name = "[q3]Wiederverwertung, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Wiederverwertung in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht, bei Missionen gelegentlich Bergungsgut zu finden.\n\n Level 2\nErhöht die Wahrscheinlichkeit, bei Missionen Bergungsgut zu finden. Zusätzlich besteht jetzt die Chance, dass sich im Bergungsgut auch Gegenstände für Eure Anhänger befinden.\n\n Level 3\nErhöht drastisch die Wahrscheinlichkeit, dass bei Missionen Bergungsgut gefunden wird.\nBenötigt den Erfolg \"Bergungen zahlen sich aus\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111978] = {name = "[q3]Schreibstube, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Schreibstube in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Inschriftenkunde und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Inschriftenkunde', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Inschriftenkundemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:"}
