MultiLanguageItemData['de'][111981] = {name = "[q3]Heiligtum des Gladiators, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Euer Heiligtum des Gladiators auf Stufe 3 ausbauen könnt.\n\n Level 1\nErhöht Eure Erholung in den Außengebieten von Draenor, wenn Ihr Euch nicht im Kampf befindet, und ermöglicht das Sammeln gebrochener Knochen von gegnerischen Spielercharakteren, die Ihr besiegt habt (benötigt für Tribut des Eroberers).\n\n Level 2\nErmöglicht sicheres Fallen und Unterwasseratmung in Außengebieten von Draenor. Ermöglicht außerdem Nemesisquests, für die Ihr gegnerische Spielercharaktere aus bestimmten Völkern besiegen müsst.\n\n Level 3\nWenn Ihr über weniger als 35% Gesundheit verfügt, wird sämtlicher erlittene Schaden in Außengebieten von Draenor um 50% verringert. Gewährt außerdem Zugang zum Gladiatorenturnier im Kolosseum von Hochfels.\nBenötigt den Erfolg \"Der Knochensammler\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111982] = {name = "[q3]Lagerhaus, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr das Lagerhaus in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht Euch Zugang zu Eurer persönlichen Bank und erhöht die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 5.\n\n Level 2\nErmöglicht Euch Zugang zu Eurer Gildenbank.\n\n Level 3\nErmöglicht Euch Zugriff auf einen astralen Händler, der Transmogrifikations- und Leerenlagerdienste anbietet. Erhöht außerdem die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 15.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111983] = {name = "[q3]Lagerhaus, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr das Lagerhaus in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht Euch Zugang zu Eurer persönlichen Bank und erhöht die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 5.\n\n Level 2\nErmöglicht Euch Zugang zu Eurer Gildenbank.\n\n Level 3\nErmöglicht Euch Zugriff auf einen astralen Händler, der Transmogrifikations- und Leerenlagerdienste anbietet. Erhöht außerdem die Gesamtzahl an aktiven Arbeitsaufträgen für alle Gebäude um 15.\nBenötigt den Erfolg \"Ich wär' so gerne Millionär, auf Draenor ist das ganz schön schwer\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111984] = {name = "[q3]Gnomische Werkstatt, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Eure gnomische Werkstatt auf Stufe 2 ausbauen könnt.\n\n Level 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\n Level 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\n Level 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111985] = {name = "[q3]Gnomische Werkstatt, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr Eure gnomische Werkstatt auf Stufe 3 ausbauen könnt.\n\n Level 1\nSchaltet einen persönlichen Ingenieur frei, der jeden Tag eine nützliche Erfindung ersinnt. Herausragende Leistung!\n\n Level 2\nEuer Ingenieur erhält Zugriff auf fünf tolle neue Gerätschaften.\n\n Level 3\nErmöglicht einmal pro Tag den Bau einer Belagerungsmaschine. Nutzt sie, um in Draenor siegreich zu sein!\nBenötigt den Erfolg \"Tödliche Technik\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111986] = {name = "[q3]Handelsposten, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr den Handelsposten in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nJeden Tag kommt ein Händler vorbei, bei dem Ihr Handwerkswaren kaufen könnt. Ermöglicht, Handwerksmaterialien gegen Garnisonsressourcen einzutauschen.\n\n Level 2\nGewährt Zugang zur Fraktion Sha'tarverteidigung (Allianz) oder Lachender Schädel (Horde). Schaltet außerdem ein Auktionskonstrukt frei, das jedoch erst mit speziellen Teilen aus ganz Draenor repariert werden muss.\n\n Level 3\nErhöht den Rufzuwachs in Draenor um 20%.\nBenötigt den Abschluss der Außenpostenquests in den Spitzen von Arak oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111987] = {name = "[q3]Handelsposten, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr den Handelsposten in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nJeden Tag kommt ein Händler vorbei, bei dem Ihr Handwerkswaren kaufen könnt. Ermöglicht, Handwerksmaterialien gegen Garnisonsressourcen einzutauschen.\n\n Level 2\nGewährt Zugang zur Fraktion Sha'tarverteidigung (Allianz) oder Lachender Schädel (Horde). Schaltet außerdem ein Auktionskonstrukt frei, das jedoch erst mit speziellen Teilen aus ganz Draenor repariert werden muss.\n\n Level 3\nErhöht den Rufzuwachs in Draenor um 20%.\nBenötigt den Erfolg \"Wilde Freunde\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111988] = {name = "[q3]Gerberei, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr die Gerberei in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Erzeugnissen der Lederverarbeitung und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Lederverarbeitung', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Lederverarbeitungsmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:"}
