MultiLanguageItemData['de'][111992] = {name = "[q3]Maßschneiderei, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Maßschneiderei auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Schneidereierzeugnissen und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Schneiderei', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Schneidereimissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Abschluss der Außenpostenquests in Talador oder Stufe 30.\nVerkaufspreis:"}
MultiLanguageItemData['de'][111993] = {name = "[q3]Maßschneiderei, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Maßschneiderei auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht die Herstellung von Schneidereierzeugnissen und gewährt Arbeitsaufträge.\n\n Level 2\nErmöglicht Anhängern mit der Eigenschaft 'Schneiderei', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nSchaltet Schneidereimissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Ein paar Aufträge mehr\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111996] = {name = "[q3]Mondsturzausgrabung, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenötigt eine Allianz-Rasse\nBenutzen: Gewährt Pläne, mit denen Ihr Eure Mondsturzausgrabung auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\n Level 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Sammler draenischer Steine\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111997] = {name = "[q3]Kräutergarten, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Pläne, mit denen Ihr den Kräutergarten in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nLässt täglich aus draenischen Samen Kräuter heranwachsen und macht Kräuter im Garten verfügbar.\n\n Level 2\nErmöglicht es Anhängern mit der Eigenschaft 'Kräuterkunde', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Erhöht außerdem die Menge an Kräutern, die im Garten geerntet werden können und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\n Level 3\nPflanzt einen einzigartigen Draenorobstbaum in Eurem Garten, der Nahrungsstärkungseffekte gewährt. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig.\nBenötigt den Erfolg \"Sammler draenischer Samenkörner\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][111998] = {name = "[q3]Menagerie, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Menagerie in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nLockt Elitehaustiere an, mit denen Ihr kämpfen könnt, um Belohnungen zu erhalten. Ermöglicht es Euch, 5 Eurer Kampfhaustiere in Eurer Garnison unterzubringen.\n\n Level 2\nErhöht die Erfolgschance Eurer Haustierfallen und verringert die Abklingzeit für das Wiederbeleben von Kampfhaustieren in Draenor. Ermöglicht es Euch außerdem, bis zu 10 Haustiere in Eurer Garnison unterzubringen.\n\n Level 3\nSchaltet täglich einen Haustierkampf mit einzigartigen Belohnungen frei.\nBenötigt Haustiermenagerie\nVerkaufspreis:"}
MultiLanguageItemData['de'][111999] = {name = "[q3]Menagerie, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr die Menagerie in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nLockt Elitehaustiere an, mit denen Ihr kämpfen könnt, um Belohnungen zu erhalten. Ermöglicht es Euch, 5 Eurer Kampfhaustiere in Eurer Garnison unterzubringen.\n\n Level 2\nErhöht die Erfolgschance Eurer Haustierfallen und verringert die Abklingzeit für das Wiederbeleben von Kampfhaustieren in Draenor. Ermöglicht es Euch außerdem, bis zu 10 Haustiere in Eurer Garnison unterzubringen.\n\n Level 3\nSchaltet täglich einen Haustierkampf mit einzigartigen Belohnungen frei.\nBenötigt den Erfolg \"Draenischer Haustierkämpfer\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][112001] = {name = "[q3]Stall, Stufe 1", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr in Eurer Garnison einen Stall errichten könnt.\n\n Level 1\nErmöglicht das Fangen und Ausbilden spezieller Reittiere auf Draenor. Lässt Euch außerdem im Freien von Draenor von Eurem Reittier aus mit Objekten interagieren.\n\n Level 2\nGegnerische Angriffe machen Euch nicht mehr benommen, während Ihr im Freien von Draenor auf einem Reittier unterwegs seid.\n\n Level 3\nErhöht die Reitgeschwindigkeit in Draenor um 20%.\nVerkaufspreis:"}
MultiLanguageItemData['de'][112002] = {name = "[q3]Stall, Stufe 2", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr den Stall in Eurer Garnison auf Stufe 2 ausbauen könnt.\n\n Level 1\nErmöglicht das Fangen und Ausbilden spezieller Reittiere auf Draenor. Lässt Euch außerdem im Freien von Draenor von Eurem Reittier aus mit Objekten interagieren.\n\n Level 2\nGegnerische Angriffe machen Euch nicht mehr benommen, während Ihr im Freien von Draenor auf einem Reittier unterwegs seid.\n\n Level 3\nErhöht die Reitgeschwindigkeit in Draenor um 20%.\nBenötigt den Abschluss der Außenpostenquests in Nagrand oder Stufe 40.\nVerkaufspreis:"}
MultiLanguageItemData['de'][112003] = {name = "[q3]Stall, Stufe 3", additional_info = "Garnisonsbauplan\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Gewährt Pläne, mit denen Ihr den Stall in Eurer Garnison auf Stufe 3 ausbauen könnt.\n\n Level 1\nErmöglicht das Fangen und Ausbilden spezieller Reittiere auf Draenor. Lässt Euch außerdem im Freien von Draenor von Eurem Reittier aus mit Objekten interagieren.\n\n Level 2\nGegnerische Angriffe machen Euch nicht mehr benommen, während Ihr im Freien von Draenor auf einem Reittier unterwegs seid.\n\n Level 3\nErhöht die Reitgeschwindigkeit in Draenor um 20%.\nBenötigt den Erfolg \"Meister der Reittiere\".\nVerkaufspreis:"}
MultiLanguageItemData['de'][112005] = {name = "[q4]Buchband des Gefängniswärters", additional_info = "Ashran\nWird beim Aufheben gebunden\nEinzigartig (5)\nKlassen: Paladin\n[q2]Benutzen: Lehrt Euch den Zauber 'Urteil des Gefängniswärters'. Hält 1 Stunde lang an. Kann nur in Ashran verwendet werden."}
MultiLanguageItemData['de'][112006] = {name = "\"Zahnstocher\" der Gordunni", additional_info = "Questgegenstand\n[q]\"Die Klinge ist über und über mit Schmutz bedeckt.\""}
MultiLanguageItemData['de'][112015] = {name = "[q3]Verlassenengehirn", additional_info = "Volks-PvP-Marke\nAshran\nWird beim Aufheben gebunden\n[q]\"Immer noch warm und pulsierend.\""}
MultiLanguageItemData['de'][112020] = {name = "Garnisonsbaupläne", additional_info = "Questgegenstand\n[q]\"Da ist zwar ein Loch in der Mitte, doch sie sind immer noch intakt.\""}
MultiLanguageItemData['de'][112022] = {name = "Rezept: Mächtiger Schattenschutztrank", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines mächtigen Schattenschutztranks.\nBenötigtAlchemie\n(400)\nBenötigt Alchemischer Katalysator - Lotus\nVerkaufspreis:\nMächtiger Schattenschutztrank\n[q2]Benutzen: Absorbiert 1134 Schattenschaden. Hält 2 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallisiertes Leben (2), Kristallphiole"}
MultiLanguageItemData['de'][112023] = {name = "Rezept: Draenischer Stein der Weisen", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Steins der Weisen.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis:\n[q3]Draenischer Stein der Weisen\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n[q2]Anlegen: Ihr habt eine Chance, bei hervorgerufener Heilung oder verursachtem Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 23 zu erhöhen. Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 55s Abklingzeit)\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie von Draenor\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis: \nBenötigt Alchemischer Katalysator (5), Echteisenerz"}
MultiLanguageItemData['de'][112024] = {name = "Rezept: Draenisches Fläschchen der Beweglichkeit", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Beweglichkeit.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenisches Fläschchen der Beweglichkeit\n[q2]Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Feuerwurz (4), Sternenblume (4)"}
MultiLanguageItemData['de'][112025] = {name = "Rezept: Draenorfläschchen des Tempos", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines Draenorfläschchens des Tempos.\nBenötigtAlchemie\n(1)\nVerkaufspreis: \n[UNUSED]\n[q2]Benutzen: Erhöht das Tempo 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator , Magisches Wasser , Frostwurz (5)"}
MultiLanguageItemData['de'][112026] = {name = "Rezept: Draenisches Fläschchen der Intelligenz", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Intelligenz.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenisches Fläschchen der Intelligenz\n[q2]Benutzen: Erhöht die Intelligenz 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Sternenblume (4), Taladororchidee (4)"}
MultiLanguageItemData['de'][112027] = {name = "Rezept: Draenisches Fläschchen der Stärke", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Stärke.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenisches Fläschchen der Stärke\n[q2]Benutzen: Erhöht die Stärke 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Nagrandpfeilkelch (4), Gorgrondfliegenfalle (4)"}
MultiLanguageItemData['de'][112030] = {name = "Rezept: Draenisches Fläschchen der Ausdauer", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Fläschchens der Ausdauer.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenisches Fläschchen der Ausdauer\n[q2]Benutzen: Erhöht die Ausdauer 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Taladororchidee (4), Nagrandpfeilkelch (4)"}
MultiLanguageItemData['de'][112031] = {name = "Rezept: Großes draenisches Fläschchen der Beweglichkeit", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Beweglichkeit.\nBenötigtAlchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Beweglichkeit erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Beweglichkeit\n[q2]Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Wasser , Draenisches Fläschchen der Beweglichkeit (5)"}
MultiLanguageItemData['de'][112032] = {name = "Rezept: Großes Draenorfläschchen des Tempos", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines großen Draenorfläschchens des Tempos.\nBenötigtAlchemie\n(1)\nVerkaufspreis:\n[UNUSED]\n[q2]Benutzen: Erhöht das Tempo 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator , Magisches Feuer , [Tyrannical Gladiator's Medallion of Meditation] , Schattentau"}
MultiLanguageItemData['de'][112033] = {name = "Rezept: Großes draenisches Fläschchen der Intelligenz", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Intelligenz.\nBenötigtAlchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Intelligenz erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Intelligenz\n[q2]Benutzen: Erhöht die Intelligenz 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Feuer , Draenisches Fläschchen der Intelligenz (5)"}
MultiLanguageItemData['de'][112034] = {name = "Rezept: Großes draenisches Fläschchen der Stärke", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Stärke.\nBenötigtAlchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Stärke erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Stärke\n[q2]Benutzen: Erhöht die Stärke 1 Stunde lang um 31 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Feuer , Draenisches Fläschchen der Stärke (5)"}
MultiLanguageItemData['de'][112037] = {name = "Rezept: Großes draenisches Fläschchen der Ausdauer", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines großen draenischen Fläschchens der Ausdauer.\nBenötigtAlchemie von Draenor\n(1)\nMuss draenisches Fläschchen der Ausdauer erlernt haben.\nVerkaufspreis:\nGroßes draenisches Fläschchen der Ausdauer\n[q2]Benutzen: Erhöht die Ausdauer 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Alchemischer Katalysator (5), Magisches Wasser , Draenisches Fläschchen der Ausdauer (5)"}
MultiLanguageItemData['de'][112038] = {name = "Rezept: Draenischer Trank der Beweglichkeit", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Beweglichkeit.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenischer Trank der Beweglichkeit\n[q2]Benutzen: Erhöht Eure Beweglichkeit 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Feuerwurz (3)"}
