MultiLanguageItemData['de'][112040] = {name = "Rezept: Draenischer Trank der Stärke", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Stärke.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenischer Trank der Stärke\n[q2]Benutzen: Erhöht Eure Stärke 25 Sek. lang um 116 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Nagrandpfeilkelch (3)"}
MultiLanguageItemData['de'][112041] = {name = "Rezept: Draenischer Trank der Rüstung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Rüstung.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenischer Trank der Vielseitigkeit\n[q2]Benutzen: Erhöht Eure Vielseitigkeit 25 Sek. lang um 31 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Frostwurz (3)"}
MultiLanguageItemData['de'][112042] = {name = "Rezept: Draenischer Trank der Manakanalisierung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Manakanalisierung.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenischer Trank der Manakanalisierung\n[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 255 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Sternenblume (3)"}
MultiLanguageItemData['de'][112043] = {name = "Rezept: Draenischer Manatrank", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Manatranks.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenischer Manatrank\n[q2]Benutzen: Stellt 1700 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Kristallphiole , Gorgrondfliegenfalle (3)"}
MultiLanguageItemData['de'][112045] = {name = "Rezept: Draenischer Trank der Verjüngung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung eines draenischen Tranks der Verjüngung.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis: \nDraenischer Trank der Verjüngung\n[q2]Benutzen: Stellt 3400 Gesundheit und 850 Mana wieder her. (5 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Heiltonikum , Draenischer Manatrank"}
MultiLanguageItemData['de'][112047] = {name = "Rezept: Transmorphische Tinktur", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch die Herstellung einer transmorphischen Tinktur.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis:\nTransmorphische Tinktur\n[q2]Benutzen: Vertauscht für kurze Zeit das Geschlecht des Anwenders.\nVerkaufspreis:\nBenötigt Sichelöl , Frostwurz (5)"}
MultiLanguageItemData['de'][112049] = {name = "Rezept: Alchemischer Katalysator - Feuerwurz", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Lehrt Euch, mit Feuerwurz einen Alchemistenkessel herzustellen.\n[q2]Liefert die erforderlichen Reagenzien, um die mächtigsten alchemistischen Gegenstände von Draenor zu erschaffen. Kann nur einmal am Tag verwendet werden. Teilt eine Abklingzeit mit anderen Alchemistenkesseln.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis:"}
