MultiLanguageItemData['de'][115289] = {name = "[q5]Siegel des Zaubererkönigs", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Ein faustgroßer Ring, in den Mar'goks persönliches Siegel eingraviert ist und der vor magischer Energie brummt.\""}
