MultiLanguageItemData['de'][116394] = {name = "[q3]Bauhinweise für ein Außenpostengebäude", additional_info = "Wird beim Aufheben gebunden\n[q]\"Bei Architekten in Ashran begehrt. Handgeschriebene Aufzeichnungen zum Bau eines Außenpostengebäudes einschließlich zahlreicher 'Verbesserungen', die energisch durchgestrichen wurden.\""}
