MultiLanguageItemData['de'][116655] = {name = "[q3]Dorrhautklippentrampler", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Dorrhautklippentrampler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Bei dieser Grollhufart sind die Hufe mit kleinen Kerben bedeckt, was es ihr erleichtert, ungefährdet Bergregionen auf der Suche nach Nahrung zu erklimmen.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n\n|"}
MultiLanguageItemData['de'][116656] = {name = "[q3]Zugerittener Eishuf", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren zugerittenen Eishuf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Bevor Euch dieses Reittier gehörte, hattet Ihr ja nicht die geringste Ahnung davon, wie schwer es in Draenor werden würde. Grollhufhaare überall!\"\nHerkunft:\nStall der Garnison"}
MultiLanguageItemData['de'][116657] = {name = "[q3]Alte Lederhaut", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Eure alte Lederhaut oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten"}
MultiLanguageItemData['de'][116658] = {name = "[q3]Tundraeishuf", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Tundraeishuf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Das durchscheinende Unterfell dieser Art ist eine perfekte Isolierung für den Einsatz in kalten Umgebungen.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel"}
MultiLanguageItemData['de'][116659] = {name = "[q4]Bluthufbulle", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Bluthufbullen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Schon lange jagen die Mitglieder des Kriegshymnenklans diese Grollhufe, um ihre blutrote Haut für Schlachtstandarten zu verwenden.\"\nBeute von:\nNakk der Donnerer\nOrt:\nNagrand"}
MultiLanguageItemData['de'][116660] = {name = "[q4]Eisenhufzerstörer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Eisenhufzerstörer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Es wird behauptet, dass Schwarzfaust die feurige Rüstung für die Schlachtgrollhufe der Eisernen Horde selbst entworfen hat.\"\nBeute von:\nSchwarzfaust\nOrt:\nSchwarzfelsgießerei (Mythisch)"}
MultiLanguageItemData['de'][116661] = {name = "[q4]Scheckiger Wiesentrampler", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren scheckigen Wiesentrampler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Mit seinem langen Rüssel kann dieser Elekk Nahrung erschnüffeln, Gefahren umgehen und Leckerlis aus Eurer Tasche stibitzen, wenn Ihr gerade nicht hinseht.\"\nBeute von:\nLuk'hok\nZone:\nNagrand"}
MultiLanguageItemData['de'][116662] = {name = "[q3]Zugerittener Wiesentrampler", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren zugerittenen Wiesentrampler oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Draenei haben schon vor langer Zeit die Elekkhaltung perfektioniert und schmücken die Kreaturen mit lichtgetränkten Kristallen, um sie gefügig zu machen.\"\nQuest:\nStall der Garnison"}
MultiLanguageItemData['de'][116663] = {name = "[q3]Schattenfellperlzahn", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Schattenfellperlzahn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Einigen Legenden zufolge haben die Draenei sich mit den Elekks angefreundet, nachdem eines dieser wilden Tiere einen verletzten Späher vor einem Rudel bösartiger Schotlinge beschützt hatte.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageItemData['de'][116664] = {name = "[q3]Staubige Steinhaut", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Eure staubige Steinhaut oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtExarchenrat\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"Seit Ihr dieses Reittier erworben habt, habt Ihr merkwürdige Fieberträume von einer Parade tanzender und trötender rosa Elekks. Elekks hin, Elekks her, in rosa, da stör'n sie Euch sehr!\"\nVerkäufer:\nVerteidiger Nuurem\nFraktion:\nExarchenrat - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116665] = {name = "[q3]Gepanzerter Eisenzahn", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren gepanzerten Eisenzahn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtSha'tarverteidigung\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"Es wird behauptet, dass ein Elekk nie etwas vergisst. Es ist also kein Wunder, dass dieses Tier die Eiserne Horde verachtet, wenn man bedenkt, was für Qualen die Orcs ihm angetan haben.\"\nVerkäufer:\n\nFraktion:\nSha'tarverteidigung - Ehrfürchtig\nOrt:\nGarnison - Handelsposten\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116666] = {name = "[q3]Schwarzstahlkampfeber", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Weigert sich zu rennen, wenn sein Schädel nicht mit schweren Metallstacheln bedeckt ist. Das stärkt sein Ego.\"\nErfolg:\nRuhm des Draenorschlachtzüglers"}
MultiLanguageItemData['de'][116667] = {name = "[q3]Felshauerkampfeber", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Schwarzstahlkampfeber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Angelockt werden potenzielle Partner nicht etwa durch den Metallhelm, sondern durch den fetzigen Irokesenschnitt.\"\nVerkäufer:\nHändlerin Araanda\nZone:\nMondsturz\nKosten:\n\nVerkäufer:\nHändler Darakk\nZone:\nFrostwall\nKosten:\n\n|"}
MultiLanguageItemData['de'][116668] = {name = "[q3]Gepanzerter Frosteber", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren gepanzerten Frosteber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ernährt sich praktisch ausschließlich von gefrorenen Beeren. Gibt sich jedoch auch mit dem Geschmack von langsamen Fremdlingen zufrieden.\"\nErfolg:\nFortgeschrittene Viehhaltung"}
MultiLanguageItemData['de'][116669] = {name = "[q3]Gepanzerter Klingenrücken", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren gepanzerten Klingenrücken oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Passt bloß auf, dass er... NIEMALS... Schinken in Eurer Tasche riecht.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel"}
MultiLanguageItemData['de'][116670] = {name = "[q3]Frostebenenkampfeber", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Frostebenenkampfeber oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ohne dieses coole Hauerpiercing würde er sich in dem Outfit echt bekloppt vorkommen.\"\nErfolg:\nRuhm des Draenorhelden"}
MultiLanguageItemData['de'][116671] = {name = "[q3]Wilder Geiferzahn", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren wilden Geiferzahn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtDie Säbelzahnpirscher\n- Wohlwollend\n\n\n[q]\"Wenn Ihr gemütlich reiten möchtet, sucht Euch doch einen \"zahmen Glückshauer\" oder so.\"\nVerkäufer:\nZ'tenga der Wanderer\nZone:\nTanaandschungel\nFraktion:\nDie Säbelzahnpirscher - Wohlwollend\nKosten:\n1.000"}
MultiLanguageItemData['de'][116672] = {name = "[q3]Domestizierter Klingenrücken", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren domestizierten Klingenrücken oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtWerterhaltungsgesellschaft des Dampfdruckkartells\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"Domestiziert\" heißt nicht \"freundlich\". Bringt also Leckerlis mit.\nVerkäufer:\nGazrix Kolbenfresser/Mimi Wirbelwolke\nFraktion:\nWerterhaltungsgesellschaft des Dampfdruckkartells - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116673] = {name = "[q3]Riesige Kaltschnauze", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Eure riesige Kaltschnauze oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Schnauze ist nicht nur kalt, sondern auch nass. Es gibt angenehmere Methoden, aufgeweckt zu werden.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageItemData['de'][116674] = {name = "[q4]Mächtiger Grauhauer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren mächtigen Grauhauer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Wirft seine Hauer einmal im Jahr ab und ist äußert schüchtern, bis sie nachgewachsen sind.\"\nBeute von:\nGorok\nZone:\nFrostfeuergrat"}
MultiLanguageItemData['de'][116675] = {name = "[q3]Zugerittener Felshauer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren zugerittenen Felshauer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Gründlich darin ausgebildet, wie man schnaubt, trötet und auf den Gesichtern seiner Feinde herumtrampelt.\"\nQuest:\nStall der Garnison"}
MultiLanguageItemData['de'][116676] = {name = "[q3]Zugerittener Flussfläzer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren zugerittenen Flussfläzer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Flussfläzer gehören zu den kräftigsten Tieren in Draenor, was ihnen mehr Ausdauer und eine markante Färbung verleiht.\"\nQuest:\nStall der Garnison"}
