MultiLanguageItemData['de'][116766] = {name = "Apexisschlüsselstein", additional_info = "Questgegenstand\nEinzigartig (4)\n[q]\"Dieser hell leuchtende Stein ist mit symmetrischen Runen bedeckt.\""}
MultiLanguageItemData['de'][116767] = {name = "[q4]Saphirblaue Flussbestie", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Eure saphirblaue Flussbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Farbe des Tiers ähnelt dem klaren Blau der Flüsse Draenors und macht es für Raubtiere im Wasser nahezu unsichtbar.\"\nBeute von:\nSchlickhaut\nZone:\nTalador"}
MultiLanguageItemData['de'][116768] = {name = "[q3]Mooshautflussfläzer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Mooshautflussfläzer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n[q]\"Die Mooshaut verteidigt ihr Gebiet aggressiv und versteckt sich häufig im Buschwerk an Flüssen, um ahnungslose Passanten zu attackieren.\"\nVerkäufer:\nDämmerungssucher Krek / Dämmerungssucher Alkset\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n50. + 5.000"}
MultiLanguageItemData['de'][116769] = {name = "[q3]Schlammrückenflussbestie", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Eure Schlammrückenflussbestie oder gibt sie wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein spezielles Gewebe an den Fußsohlen des Schlammrückens gewährt ihm zusätzlichen Halt in Schlamm und auf rutschigen Untergründen.\"\nGarnisonsmission:\nIst es ein Schiff? Ist es ein Flugzeug? Nein, nur eine Flussbestie!"}
MultiLanguageItemData['de'][116771] = {name = "[q4]Sonnenfalke der Spitzen", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Sonnenfalken der Spitzen oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n\"Wenn man in die Augen dieses mystischen Wesens blickt, hat man das Gefühl, man würde in das Herz der Sonne starren. Beim Reiten ist das Tragen einer Schutzbrille anzuraten.\"\nBeute von:\nRukhmar"}
MultiLanguageItemData['de'][116772] = {name = "[q3]Schattenmähnenstürmer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Schattenmähnenstürmer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtAusgestoßene Arakkoa\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"Draeneidichter bezeichnen die Farbe dieses Talbuks als Schatten des Mondlichts im aschgrauen Wald.\"\nVerkäufer:\nRabensprecher Skeega / Schattenweiser Brakoss\nFraktion:\nAusgestoßene Arakkoa - Ehrfürchtig\nOrt:\nSturmschild/Kriegsspeer\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116773] = {name = "[q4]Flinker Brisenschreiter", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren flinken Brisenschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Die Draenei haben dieses Reittier, das schnellste aller Talbuks, mit der Aufgabe betraut, ihre Boten und Nachrichten sicher an ihre Ziele zu bringen.\"\nBeute von:\nPfadläufer\nZone:\nSchattenmondtal"}
MultiLanguageItemData['de'][116774] = {name = "[q3]Zugerittenes Silberfell", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euer zugerittenes Silberfell oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieser Talbuk ist aufgrund seiner Intelligenz beliebt und wird darauf trainiert, im Kampf zu treten und Gegner aufzuspießen.\"\nOrt:\nStall der Garnison"}
MultiLanguageItemData['de'][116775] = {name = "[q3]Brisenschreiterhengst", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Brisenschreiterhengst oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtVol'jins Speer\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"Die rote Färbung des Brisenschreiters spiegelt sein Temperament wider: lebhaft, stürmisch und tapfer.\"\nVerkäufer:\nDazzerian\nFraktion:\nVol'jins Speer - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116776] = {name = "[q3]Heller Dornzehrer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren hellen Dornzehrer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtWrynns Vorhut\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"Dieser Talbuk ernährt sich ausschließlich von Disteln und Dornen, weshalb sein Inneres genauso widerstandsfähig ist, wie sein Äußeres.\"\nVerkäufer:\nMagor Geistbeuger\nFraktion:\nWrynns Vorhut - Ehrfürchtig\nOrt:\nSturmschild\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116777] = {name = "[q4]Boshafter Kriegswidder", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\nBenötigt eine Allianz-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren boshaften Kriegswidder oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Bevor er Eure empfindlichsten Körperregionen nicht mit seinem Kopf rammt, hat er Euch nicht wirklich als seinen Reiter akzeptiert.\"\nVerkäufer:\nNekrolord Sipe\nZone:\nSturmwind\nKosten:\n1"}
MultiLanguageItemData['de'][116778] = {name = "[q4]Boshafter Kriegsraptor", additional_info = "[q7]Wird an Kriegsmeute gebunden\nReittier\nBenötigt eine Horde-Rasse\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren boshaften Kriegsraptor oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis: \n[q]\"Weil scharfe Zähne und Klauen einfach nicht ausreichen.\"\nVerkäufer:\nTodeswache Netharian\nZone:\nOrgrimmar\nKosten:\n1"}
MultiLanguageItemData['de'][116779] = {name = "[q3]Stahlzahngarn", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Stahlzahngarn oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Ein Trainer versuchte einst, das Maul des Stahlrachenwolfs mit Metalldekorationen zu verschönern. Drei Tage hat es gedauert, bis er sein Material zurückhatte.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageItemData['de'][116780] = {name = "[q3]Terrorzahn des Kriegshymnenklans", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Terrorzahn des Kriegshymnenklans oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieses Tier hat einen eisernen Willen, doch wenn Ihr ihm einen Grollhufknochen zum Zerkauen bringt, ist es ganz lieb.\"\nBeute von:\nRache, Todeskralle, Terrorfaust, Verdammniswalze\nZone:\nTanaandschungel"}
MultiLanguageItemData['de'][116781] = {name = "[q3]Gepanzerter Frostwolf", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren gepanzerten Frostwolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Er ist dazu ausgebildet, das harsche Wetter des Frostfeuergrats zu überleben, also kuschelt er, als würde sein Leben davon abhängen.\"\nErfolg:\nStallmeister"}
MultiLanguageItemData['de'][116782] = {name = "[q3]Eisenflankenkriegswolf", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Eisenflankenkriegswolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtOrcs des Lachenden Schädels\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"An seinem Schwanz hängt ein gepanzerter Stachel. Wenn Ihr seinen Bauch unbedingt kraulen wollt, tut Ihr es auf eigene Gefahr.\"\nVerkäufer:\nHau'tot\nFraktion:\nLachender Schädel - Ehrfürchtig\nOrt:\nGarnison - Handelsposten (Horde)\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116784] = {name = "[q3]Zugerittener Knurrer", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren zugerittenen Knurrer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Als Welpe unheimlich süß. Jetzt nicht mehr so sehr.\"\nQuest:\nStall der Garnison"}
MultiLanguageItemData['de'][116785] = {name = "[q4]Schneller Frostwolf", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren schnellen Frostwolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigtFrostwolforcs\n- Ehrfürchtig\nVerkaufspreis:\n[q]\"In den kalten Höhen des Frostfeuergrats jagen die Frostwölfe allem nach, was sie fangen können. Die Schnellsten von ihnen bekommen reichlich zu beißen.\"\nVerkäufer:\nBeska Rothauer\nFraktion:\nFrostwolforcs - Ehrfürchtig\nOrt:\nKriegsspeer\nKosten:\n5. + 5.000"}
MultiLanguageItemData['de'][116786] = {name = "[q3]Rauchgrauer Terrorwolf", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren rauchgrauen Terrorwolf oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Man vermutet, dass sie größtenteils im Norden hausen. Können Hochzeiten absolut nicht leiden.\"\nBeute von:\nZurückgelassener Invasorenschatz"}
MultiLanguageItemData['de'][116788] = {name = "[q4]Todesrad des Kriegsherrn", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euer Todesrad des Kriegsherrn oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Dieses brüllende Ungetüm wird häufig als \"Goblinrasenmäher\" bezeichnet, da dieses knurrende Monstrum Feinde behandelt, als wären sie aus Gras... das bereit ist, gemäht zu werden.\"\nErfolg:\nKategorie:\nHeldentaten"}
MultiLanguageItemData['de'][116789] = {name = "[q4]Kettenrad des Champions", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euer Kettenrad des Champions oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Menschen, Gnome und Zwerge haben gemeinsam dieses gepanzerte Meisterstück geschaffen, das einen Tauren im Handumdrehen in mundgerechte Stücke zerteilt.\"\nVerkäufer:\nPaulie\nZone:\nSturmwind, Altstadt\nKosten:"}
MultiLanguageItemData['de'][116791] = {name = "[q3]Kriegsyeti des Herausforderers", additional_info = "Wird beim Aufheben gebunden\nReittier\n[q0](Accountweit)\n[q2]Benutzen: Lehrt Euch, wie man dieses Reittier beschwört.\n[q2]Beschwört Euren Kriegsyeti des Herausforderers oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\n[q]\"Glücklicherweise bewegen sie sich schnell und hinterlassen nur den Geruch.\"\nErfolg:\nHerausforderungskriegsherr: Silber"}
