MultiLanguageItemData['de'][118327] = {name = "Rezeptidee: Gorgronder Fischsuppe", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die Zubereitung einer Gorgronder Fischsuppe.\n[q2]Rezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBenötigt Kochkunst von Draenor (1)\n\n\nGorgronder Fischsuppe\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet für 1 Stunde 10 Vielseitigkeit.\n\n Wenn Ihr dieses Gericht kostet, besteht eine Chance, dass Ihr das Rezept erlernt.\nVerkaufspreis: \nBenötigt Grollhufwürstchen (5), Sämige Schleichersuppe (5), Gorgrondfliegenfalle"}
MultiLanguageItemData['de'][118328] = {name = "Rezeptidee: Festmahl des Blutes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die Zubereitung eines Festmahls des Blutes.\n[q2]Rezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBenötigt Kochkunst von Draenor (1)\n\n\nFestmahl des Blutes\n[q2]Benutzen: Sättigt bis zu 30 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl des Blutes.\n\n Dabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\nVerkaufspreis:\nBenötigt Rohes Elekkfleisch (10), Rohes Eberfleisch (10), Rohes Talbukfleisch (10), Rohes Flussbestienfleisch (10), Rylakei (10), Rohes Grollhuffleisch (10)"}
MultiLanguageItemData['de'][118329] = {name = "Rezeptidee: Festmahl der Gewässer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die Zubereitung eines Festmahls der Gewässer.\n[q2]Rezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBenötigt Kochkunst von Draenor (1)\n\n\nFestmahl der Gewässer\n[q2]Benutzen: Sättigt bis zu 10 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl der Gewässer.\n\n Dabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\nVerkaufspreis:\nBenötigt Seeskorpionsegment (10), Fleisch eines Tiefenschluckaals (10), Fleisch eines blinden Seestörs (10), Fleisch eines dicken Schläfers (10), Feuerammonittentakel (10), Fleisch eines kieferlosen Schleichers (10)"}
