MultiLanguageItemData['de'][120132] = {name = "Recipe: Secrets of Draenor Alchemy", additional_info = "Wird beim Aufheben gebunden\nBenutzen: Teaches you how to research Secrets of Draenor Alchemy.\n[q2]Abklingzeit wird täglich abgeschlossen.\nBenötigtAlchemie von Draenor\n(1)\nVerkaufspreis:\nAlchemiegeheimnis von Draenor\nWird beim Aufheben gebunden\n[q]\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Frostwurz (5)"}
MultiLanguageItemData['de'][120134] = {name = "Recipe: Secrets of Draenor Engineering", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teaches you how to research Secrets of Draenor Engineering.\nStellt einmal pro Tag Eure Kenntnisse der Ingenieurskunst zusammen. Geheimnisse können gegen Rezepte getauscht werden.\nBenötigt Ingenieurskunst (1)\nVerkaufspreis:\nIngenieursgeheimnis von Draenor\nWird beim Aufheben gebunden\n[q]\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Echteisenerz (5)"}
MultiLanguageItemData['de'][120135] = {name = "Recipe: Secrets of Draenor Enchanting", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teaches you how to research Secrets of Draenor Enchanting.\nStellt einmal pro Tag Eure Kenntnisse der Verzauberkunst zusammen. Geheimnisse können gegen Rezepte getauscht werden.\nBenötigt Verzauberkunst (1)\nVerkaufspreis:\nVerzaubergeheimnis von Draenor\nWird beim Aufheben gebunden\n[q]\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Draenischer Staub (3)"}
MultiLanguageItemData['de'][120136] = {name = "Recipe: Secrets of Draenor Inscription", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teaches you how to research Secrets of Draenor Inscription.\nStellt einmal pro Tag Eure Kenntnisse der Inschriftenkunde zusammen. Geheimnisse können gegen Rezepte getauscht werden.\nBenötigt Inschriftenkunde (1)\nVerkaufspreis:\nInschriftengeheimnis von Draenor\nWird beim Aufheben gebunden\n[q]\"Kann in Eurer Garnison im jeweiligen Handwerksgebäude oder in Ashran gegen Rezepte eingetauscht werden.\"\nVerkaufspreis:\nBenötigt Himmelblaue Pigmente (2)"}
MultiLanguageItemData['de'][120137] = {name = "[q3]Foliant der Verwandlung: Bärenjunges", additional_info = "Klassen: Magier\n[q2]Benutzen: Lehrt Euch 'Verwandlung: Bärenjunges'.\n[q2]Verwandelt den Gegner in ein Eisbärenjunges, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][120138] = {name = "[q3]Foliant der Verwandlung: Affe", additional_info = "Klassen: Magier\n[q2]Benutzen: Lehrt Euch 'Verwandlung: Affe'.\n[q2]Verwandelt den Gegner in ein Äffchen, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][120139] = {name = "[q3]Foliant der Verwandlung: Pinguin", additional_info = "Wird beim Aufheben gebunden\nKlassen: Magier\n[q2]Benutzen: Lehrt Euch 'Verwandlung: Pinguin'.\n[q2]Verwandelt den Gegner in einen Pinguin, der 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:"}
MultiLanguageItemData['de'][120140] = {name = "[q3]Foliant der Verwandlung: Stachelschwein", additional_info = "Klassen: Magier\n[q2]Benutzen: Lehrt Euch 'Verwandlung: Stachelschwein'.\n[q2]Verwandelt den Gegner in ein Stachelschwein, das 1 Min. lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\n Wirkt nur bei Tieren, Humanoiden und Kleintieren. [ Glyphe 'Kleintierverwandlung' : Bei Kleintieren kann der Zauber mehrere Ziele verwandeln, und die Verwandlung hält 1 Tag lang an ]\nVerkaufspreis:"}
