MultiLanguageItemData['de'][120163] = {name = "[q2]Thruks Angelrute", additional_info = "Wird beim Aufheben gebunden\nWerkzeug für Angeln Haltbarkeit 40 / 40\n[q2]Anlegen: +3 Angelfertigkeit.\nBenötigt Angeln (1)\nVerkaufspreis:"}
MultiLanguageItemData['de'][120164] = {name = "[q3]Thruks hochbelastbare Angelrute", additional_info = "Wird beim Aufheben gebunden\n{Zweihändig} {Stab}\n5 - 8 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 90 / 90\nVerkaufspreis:"}
MultiLanguageItemData['de'][120165] = {name = "[q3]Thruks Filetiermesser", additional_info = "Wird beim Aufheben gebunden\n{Einhändig} {Dolch}\n1 - 2 Schaden Geschwindigkeit 1.80\n(0.8 Schaden pro Sekunde)\n+8 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]+ 1 Vielseitigkeit\nHaltbarkeit 55 / 55\nVerkaufspreis:"}
MultiLanguageItemData['de'][120166] = {name = "[q3]Blutbespritztes Gewand", additional_info = "Wird beim Anlegen gebunden\n{Brust} {Stoff}\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]+ 3 Vielseitigkeit\nHaltbarkeit 125 / 125\nVerkaufspreis:"}
MultiLanguageItemData['de'][120167] = {name = "[q3]Blutiger Zwielichtumhang", additional_info = "Wird beim Aufheben gebunden\nRücken\n2 Rüstung\n+2 [Beweglichkeit oder Stärke oder Intelligenz]\n+2 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]+ 1 Vielseitigkeit\nVerkaufspreis:"}
MultiLanguageItemData['de'][120168] = {name = "Topf Fertignudeln", additional_info = "Völker: Pandaren , Pandaren\n[q2]Benutzen: Stellt im Verlauf von 20 Sek. Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 385 Vielseitigkeit.\n[q]\"Einfach Wasser hinzufügen und erhitzen. Ideal für abenteuerlustige Pandaren, egal wo diese gerade unterwegs sind.\"\nVerkaufspreis:"}
