MultiLanguageItemData['de'][122710] = {name = "Rezept: Uralchemie", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die uneingeschränkte Herstellung von alchemischen Katalysatoren.\nBenötigtAlchemie von Draenor\n(1)\n\n\n[q2]Alchemischer Katalysator\nHandwerksmaterial\n[q]\"Beschleunigt Reaktionen, die sonst Tausende von Jahren benötigen würden, und ist daher unerlässlich für die Alchemie auf Draenor.\"\nBenötigt Urgeist , Feuerwurz (2), Gorgrondfliegenfalle (2), Nagrandpfeilkelch (2), Sternenblume (2), Taladororchidee (2)"}
MultiLanguageItemData['de'][122711] = {name = "Formel: Temporale Bindung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die uneingeschränkte Herstellung von temporalen Kristallen.\nBenötigt Verzauberkunst von Draenor (1)\n\n\n[q4]Zerbrochener temporaler Kristall\n[q2]Benutzen: Fügt 10 zerbrochene temporale Kristalle zu einem temporalen Kristall zusammen.\nHandwerksmaterial\nBenötigt Urgeist , Glitzernder Splitter"}
MultiLanguageItemData['de'][122712] = {name = "Bauplan: Urkonstruktion", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die uneingeschränkte Herstellung von Getriebefederteilen.\nBenötigt Ingenieurskunst von Draenor (1)\n\n\n[q2]Getriebefederteile\nWird beim Aufheben gebunden\nHandwerksmaterial\n[q]\"Diese Teile sind unglaublich anpassbar und von Ingenieuren bei Reparaturen hochgeschätzt.\"\nVerkaufspreis:\nBenötigt Urgeist , Schwarzfelserz (5), Echteisenerz (5)"}
MultiLanguageItemData['de'][122713] = {name = "Technik: Der Geist des Krieges", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die uneingeschränkte Herstellung von Kriegsbemalung.\nBenötigt Inschriftenkunde von Draenor (1)\nVerkaufspreis: \n[q2]Kriegsbemalung\nWird beim Aufheben gebunden\nHandwerksmaterial\nBenötigt Urgeist , Himmelblaue Pigmente (4)"}
MultiLanguageItemData['de'][122714] = {name = "Vorlage: Urjuwelierskunst", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die uneingeschränkte Herstellung von Taladitkristallen.\nBenötigtJuwelierskunst von Draenor\n(1)\n\n\n[q2]Taladitkristall\nWird beim Aufheben gebunden\nHandwerksmaterial\n[q]\"Ein vielseitiger, im Labor erschaffener Edelstein, der in vielen Juwelierskunstvorlagen Draenors Verwendung findet.\"\nBenötigt Urgeist , Schwarzfelserz (5), Echteisenerz (5)"}
MultiLanguageItemData['de'][122715] = {name = "Muster: Lederhandwerk der Ahnen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die uneingeschränkte Herstellung von poliertem Leder.\nBenötigt Lederverarbeitung von Draenor (1)\n\n\n[q2]Poliertes Leder\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Belastbar und geschmeidig. Wird bei der Lederverarbeitung in Draenor verwendet.\"\nVerkaufspreis:\nBenötigt Urgeist , Rohes Tierleder (10)"}
MultiLanguageItemData['de'][122716] = {name = "Muster: Urweberei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die uneingeschränkte Herstellung von Hexenzwirnstoff.\nBenötigt Schneiderei von Draenor (1)\n\n\n[q2]Hexenzwirnstoff\nWird beim Aufheben gebunden\nHandwerksmaterial\n\"Zu feinem Stoff gewebtes Fell, das als Grundlage für die meisten Schneidereiprodukte in Draenor dient.\"\nVerkaufspreis: \nBenötigt Urgeist , Prächtiges Fell (10)"}
