MultiLanguageItemData['de'][124517] = {name = "[q4]Heiliger Draeneiweihrauch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Mönch\n[q2]Anlegen: Wenn Eure Gesundheit unter 1 % fällt, erhaltet Ihr eine Aufladung von 'Eisenhautgebräu'. 'Eisenhautgebräu' erhöht außerdem den verursachten Schaden um 0 %.\n[q2]Anlegen: 'Beruhigender Nebel' heilt auch Verbündete um das Ziel um 0 % der Heilung des Primärziels.\n[q2]Anlegen: Ihr habt eine Chance von 0 %, einen kostenlosen 'Tritt der aufgehenden Sonne' nach jedem Einsatz von 'Furorfäuste', 'Blackout-Tritt' oder eines normalen 'Tritt der aufgehenden Sonne' auszuführen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][124518] = {name = "[q4]Buchband der Verteidigung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Paladin\n[q2]Anlegen: Heilung mit 'Heiliger Schock' gewährt Euch 'Strahlendes Licht', was die Heilung Eurer nächsten Einsätze von 'Heiliges Licht' oder 'Lichtblitz' innerhalb von 6 Sek. um 1 % erhöht.\n[q2]Anlegen: Wenn Eure Gesundheit unter 1 % fällt, wird das Licht Euch um (Angriffskraft * 11 / 100) heilen und Gegnern in der Nähe (Angriffskraft * 11 / 100) Heiligschaden zufügen. Dieser Effekt kann nur einmal alle 12 Sek. auftreten.\n[q2]Anlegen: 'Kreuzfahrerstoß' erhöht Euren Schaden für 10 Sek. um ( 4 / 100)%. Dieser Effekt ist bis zu 3-mal stapelbar und wird zurückgesetzt, wenn Ihr für 'Kreuzfahrerstoß' ein anderes Ziel auswählt.\nVerkaufspreis:"}
MultiLanguageItemData['de'][124519] = {name = "[q4]Kriegserklärung an den Krieg", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nKlassen: Priester\n[q2]Anlegen: 'Schattenheilung', 'Bittgebet', 'Machtwort: Glanz' und 'Sühne' verleihen Verbündeten zusätzlich 'Disziplin der Naaru', was den erlittenen Schaden 10 Sek. lang um 0 % verringert.\n[q2]Anlegen: Erhöht Eure durch 'Heilung' und 'Blitzheilung' hervorgerufene Heilung um 0 %.\n[q2]Anlegen: Schaden durch 'Gedankenschinden' belegt das Ziel mit 'Geistige Ermüdung', was den durch Gedankenzauber erlittenen Schaden 10 Sek. lang um ( 8 / 100)% erhöht. Dieser Effekt ist bis zu 5-mal stapelbar.\nVerkaufspreis:"}
