MultiLanguageItemData['de'][124634] = {name = "[q5]Thorasus, das steinerne Herz Draenors", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Stärke\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n[q2]Benutzen: Erweckt die Mächte aller wilden Heiligtümer, die von Euch und Euren Verbündeten getragen werden, und erhöht den verursachten Schaden 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]%.\n\n Wenn dieser Effekt endet, entfesselt jeder von Macht erfüllte Spielercharakter einen Blitz aus Licht, der alle Gegner innerhalb von 20 Metern vom auslösenden Spielercharakter trifft und ihnen Schaden in Höhe von ( 27 / 100)% des gesamten Schadens, den er unter der Ermächtigung verursacht hat, zufügt. (2 Min. geteilte Abklingzeit)\n[q]\"Eines der drei wilden Heiligtümer, geschaffen von Erzmagier Khadgar.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][124635] = {name = "[q5]Nithramus, der Allsehende", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Intelligenz\n+4 Ausdauer\n[q2]+ 2 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\n[q2]Benutzen: Erweckt die Mächte aller wilden Heiligtümer, die von Euch und Euren Verbündeten getragen werden, und erhöht den verursachten Schaden 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]%.\n\n Wenn dieser Effekt endet, entfesselt jeder von Macht erfüllte Spielercharakter einen Blitz aus Licht, der alle Gegner innerhalb von 20 Metern vom jeweiligen Spielercharakter trifft und ihnen Schaden in Höhe von ( 27 / 100)% des gesamten Schadens, den er unter der Ermächtigung verursacht hat, zufügt. (2 Min. geteilte Abklingzeit)\n[q]\"Eines der drei wilden Heiligtümer, geschaffen von Erzmagier Khadgar.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][124636] = {name = "[q5]Maalus, der Bluttrinker", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Beweglichkeit\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]+ 3 Vielseitigkeit\n[q2]Benutzen: Erweckt die Mächte aller wilden Heiligtümer, die von Euch und Euren Verbündeten getragen werden, um den verursachten Schaden 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% zu erhöhen.\n\n Wenn dieser Effekt endet, entfesselt jeder von Macht erfüllte Spielercharakter einen Blitz aus Licht, der alle Gegner innerhalb von 20 Metern vom jeweiligen Spielercharakter trifft und ihnen Schaden in Höhe von ( 27 / 100)% des gesamten Schadens, den er unter der Ermächtigung verursacht hat, zufügt. (2 Min. geteilte Abklingzeit)\n[q]\"Eines der drei wilden Heiligtümer, geschaffen von Erzmagier Khadgar.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][124637] = {name = "[q5]Sanctus, Siegel des Ungebrochenen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 [Beweglichkeit oder Stärke]\n+4 Ausdauer\n[q2]+ 2 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\n[q2]Benutzen: Erweckt die Mächte der Ringe von Sanctus, die von Euch und Euren Verbündeten getragen werden, um 15 Sek. lang [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 54 / 100]% Vielseitigkeit zu gewähren.\n\n Für die Dauer dieses Effekts werden sämtlicher erlittener Schaden und alle erhaltene Heilung gleichmäßig unter den ermächtigten Verbündeten aufgeteilt. (2 Min. geteilte Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][124638] = {name = "[q5]Etheralus, der ewige Lohn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]+ 3 Vielseitigkeit\n[q2]Benutzen: Erweckt die Mächte der Ringe von Etheralus, die von Euch und Euren Verbündeten getragen werden, um die hervorgerufene Heilung und Absorption 15 Sek. lang um [(( 80 > 109 ? 0.01 : ( 80 < 100 ? 1 : (110 - 80) / 10))) * 27 / 100]% zu erhöhen.\n\n Wenn dieser Effekt endet, entfesselt jeder ermächtigte Spielercharakter einen Energieausbruch, der Verbündete abschirmt und Schaden in Höhe von ( 27 / 100)% der gesamten Heilung absorbiert, die der Spielercharakter während der Ermächtigung hervorgerufen hat. Der Effekt wird gleichmäßig auf alle abgeschirmten Spielercharaktere verteilt. (2 Min. geteilte Abklingzeit)\nVerkaufspreis:"}
