MultiLanguageItemData['de'][127828] = {name = "[q0]Schillernde Rute", additional_info = "Wird beim Aufheben gebunden\nWaffenhand\n1 Arkanschaden Geschwindigkeit 1.60\n(0.6 Schaden pro Sekunde)\n[q2]Benutzen: Feuert eine schnelle Kugel aus arkaner Energie ab.\n\n Kann nur Spielercharaktere treffen, die eine schillernde Rute verwenden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][127829] = {name = "[q6]Zwillingsklingen des Betrügers", additional_info = "Verus\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Teufel Artefakt Relikt Slot\n[q0]Schatten Artefakt Relikt Slot\n\nKlassen: Dämonenjäger\n[q2]Anlegen: Gewährt die Fähigkeit 'Zorn der Illidari', die alle Gegner in der Nähe wiederholt mit Euren Kriegsgleven aufschlitzt.\n[q]\"Statuiert Exempel an jenen, die närrisch genug sind, sich Euch zu widersetzen, dann wird der Rest ihrer Art sich Euch zu Füßen werfen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][127830] = {name = "[q6]Zwillingsklingen des Betrügers", additional_info = "Muramas\nWird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Dämonenjäger\n[q]\"Das Ende ist gekommen! Lasst die Zerstörung dieser Welt beginnen!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][127831] = {name = "[q3]Geldkassette des Herausforderers", additional_info = "Wird beim Aufheben gebunden\n[q2]<Zum Öffnen rechtsklicken>\nVerkaufspreis:"}
MultiLanguageItemData['de'][127833] = {name = "[q2]Schiff: Zerstörer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Ein mächtiges Schiff mit großen Kanonen. Kann auf Marinemissionen eingesetzt werden.\""}
MultiLanguageItemData['de'][127834] = {name = "Uralter Heiltrank", additional_info = "[q2]Benutzen: Regeneriert 6000 Gesundheit. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127835] = {name = "Uralter Manatrank", additional_info = "[q2]Benutzen: Regeneriert 2000 Mana. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127836] = {name = "Uralter Verjüngungstrank", additional_info = "[q2]Benutzen: Regeneriert 6000 Gesundheit und 1500 Mana. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127837] = {name = "Destillat aus roher Magie", additional_info = "[q2]Benutzen: Auf ex.\nVerkaufspreis:"}
MultiLanguageItemData['de'][127838] = {name = "Sylvanelixier", additional_info = "[q2]Benutzen: Verwandelt Euch in einen Baum. Ihr und alle Spielercharaktere, die sich in Eurem Schatten ausruhen, werden gut erholt und alle Eure Werte um 10% erhöht.\nVerkaufspreis:"}
MultiLanguageItemData['de'][127839] = {name = "Lawinenelixier", additional_info = "[q2]Benutzen: Wenn Ihr eine lange Strecke fallt, verwandelt Ihr Euch in eine Lawine. Beim Auftreffen fügt Ihr allen Gegnern innerhalb von 5 Metern 1500 Schaden zu. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127840] = {name = "Skaggldrynk", additional_info = "[q2]Benutzen: Begebt Euch in das Geisterreich und werdet so für 18 Sek. unsichtbar. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127841] = {name = "Himmelslauftrank", additional_info = "[q2]Benutzen: Erhöht die Bewegungsgeschwindigkeit um 150% und lässt den Trinkenden in der Luft schweben. Hält 8 Sek. lang an. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127842] = {name = "[q4]Infernaler Alchemistenstein", additional_info = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie der Verheerten Inseln\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][127843] = {name = "Trank der tödlichen Anmut", additional_info = "[q2]Benutzen: Gewährt Euren Angriffen eine Chance, einen Energieblitz auf Euer Ziel zu entfesseln.\n\n Wenn Ihr Euch während der gesamten Effektdauer von Gegnern fernhaltet, wird sie um zusätzliche 5 Sek. verlängert. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127844] = {name = "Trank des Alten Krieges", additional_info = "[q2]Benutzen: Beschwört zwei geisterhafte gefallene Krieger, die an Eurer Seite kämpfen. Sie können Eure Nahkampfangriffe und -fähigkeiten imitieren und verursachen damit 1161 Schaden. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127845] = {name = "Unbeugsamer Trank", additional_info = "[q2]Benutzen: Erhöht Eure Rüstung 25 Sek. lang um 124 . (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127846] = {name = "Leywirbeltrank", additional_info = "[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 300 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127847] = {name = "Fläschchen des geflüsterten Pakts", additional_info = "[q2]Benutzen: Erhöht die Intelligenz 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127848] = {name = "Fläschchen des Siebten Dämons", additional_info = "[q2]Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127849] = {name = "Fläschchen der zahllosen Armeen", additional_info = "[q2]Benutzen: Erhöht die Stärke 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127850] = {name = "Fläschchen der zehntausend Narben", additional_info = "[q2]Benutzen: Erhöht die Ausdauer 1 Stunde lang um 69 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:"}
MultiLanguageItemData['de'][127851] = {name = "Geisterkessel", additional_info = "[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:"}
MultiLanguageItemData['de'][127853] = {name = "[q4]Schatzkiste der Eisernen Flotte", additional_info = "Normal\nWird beim Aufheben gebunden\n[q]\"Enthält einen Gegenstand des Schwierigkeitsgrads 'Normal' aus der Schlachtzugzone Höllenfeuerzitadelle.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][127854] = {name = "[q4]Schatzkiste der Eisernen Flotte", additional_info = "Heroisch\nWird beim Aufheben gebunden\n[q]\"Enthält einen Gegenstand des Schwierigkeitsgrads 'Heroisch' aus der Schlachtzugzone Höllenfeuerzitadelle.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][127855] = {name = "[q4]Schatzkiste der Eisernen Flotte", additional_info = "Mythisch\nWird beim Aufheben gebunden\n[q]\"Enthält einen Gegenstand des Schwierigkeitsgrads 'Mythisch' aus der Schlachtzugzone Höllenfeuerzitadelle.\"\n[q2]<Zum Öffnen rechtsklicken>"}
MultiLanguageItemData['de'][127856] = {name = "[q3]Zurückgelassener Hai", additional_info = "[q2]Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n[q2]Mit Rechtsklick Euren zurückgelassenen Hai beschwören oder wieder freigeben.\n80 ( 80)"}
MultiLanguageItemData['de'][127857] = {name = "[q6]Aluneth", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Arkan Artefakt Relikt Slot\n[q0]Frost Artefakt Relikt Slot\n\nKlassen: Magier\n[q2]Anlegen: Gewährt die Fähigkeit 'Mal von Aluneth', die eine Rune auf dem Boden platziert, die nach kurzer Zeit explodiert und massiven Schaden verursacht.\n[q]\"Nach vielen Rückschlägen schaffte Aegwynn es endlich, das Wesen an einen verzauberten Großstab zu binden. Die Aufgabe, Aluneth einzugrenzen, war somit vollbracht, doch die Wächterin brauchte noch Jahre, bis sie die Macht wirklich nutzen konnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][127858] = {name = "Geisterfläschchen", additional_info = "Herbeigezauberter Gegenstand\nEinzigartig: Gildenfläschchen (1)\n[q2]Benutzen: Gewährt den Effekt eines Fläschchens basierend auf Eurer Klasse und Euren Talenten. Hält 1 Stunde lang und über den Tod hinaus an. (3 Sek. Abklingzeit)"}
MultiLanguageItemData['de'][127859] = {name = "[q3]Schillernde Rute", additional_info = "Wird beim Aufheben gebunden\nSpielzeug\n[q2]Benutzen: Rüstet Euch mit einer schillernden Rute aus, die es Euch gestattet, arkane Energie auf andere abzufeuern, die diese Rute ebenfalls tragen. (5 Sek. Abklingzeit)\n[q]\"Ein beliebtes Spielzeug unter Draeneikindern.\""}
MultiLanguageItemData['de'][127860] = {name = "Signet des Wächters", additional_info = "Val'sharah\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n[q]\"Die Zeit hat ihre Spuren hinterlassen.\""}
MultiLanguageItemData['de'][127861] = {name = "[q3]Höhlenpilzstuhl", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Stellt einen leuchtenden Pilzstuhl auf. (5 Min Abklingzeit)"}
MultiLanguageItemData['de'][127863] = {name = "Gefängnisschlüssel", additional_info = "Questgegenstand\n[q]\"Ein Satz länglicher, skelettartiger Schlüssel baumelt an einer Silberkette.\""}
