MultiLanguageItemData['de'][127871] = {name = "Ausgebrannter Leyflammenbrenner", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Dieser Brenner war einst in der Lage, eine starke Flamme aus Leyenergie hervorzubringen, die in der Alchemie sehr nützlich ist.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][127872] = {name = "Gesprungenes zweikammeriges Mischfläschchen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Der Sprung in diesem einstmals wertvollen Mischbehälter macht ihn für die Alchemie nutzlos.\""}
MultiLanguageItemData['de'][127873] = {name = "Verbesserte Korken", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Diese dichten Korken sehen so aus, als ob sie in der Lage wären, instabile Mixturen gut verschließen zu können.\""}
MultiLanguageItemData['de'][127874] = {name = "Präzipitationspulver", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Dieses Pulver wurde aus den Ascherückständen hergestellt, die der Atem eines Drachen hinterließ, und dürfte in der Alchemie äußerst nützlich sein.\""}
MultiLanguageItemData['de'][127875] = {name = "Seidenfilter der Shal'dorei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n[q]\"Wenn dieser Stoff nicht zerrissen wäre, könnte man ihn hervorragend zum Filtern von alchemistischen Flüssigkeiten benutzen.\""}
MultiLanguageItemData['de'][127876] = {name = "Brüchiger Dämonenodemtiegel", additional_info = "Questgegenstand\nEinzigartig\n[q]\"Dieser Topf wurde hergestellt, um darin mächtige Teufelsreagenzien zusammenzumischen, aber er muss wohl ein wenig verstärkt werden.\""}
