MultiLanguageItemData['de'][127884] = {name = "[q3]Teufelsrauchwerfer", additional_info = "Marineausstattung\nWird beim Aufheben gebunden\n[q2]Benutzen: Rüstet ein Kriegsschiff mit Teufelsrauchwerfern aus.\n\nKontert:\n Erstschlag\nBenötigt Ausstattungsbaupläne, die zuletzt in der Nähe der Dämonenschmiede gesehen wurden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][127885] = {name = "[q3]Raubeinige Besatzung", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Heuert eine raubeinige Besatzung für Euer Kriegsschiff an.\n[q]\"Diese Besatzung hat schon alles erlebt – wie man an ihren Hüten erkennen kann. Erhöht die Erfolgschance für Missionen um 10%.\""}
MultiLanguageItemData['de'][127886] = {name = "[q3]Unsinkbar", additional_info = "Marineausstattung\nWird beim Aufheben gebunden\n[q2]Benutzen: Stattet ein Schiff mit 'Unsinkbar' aus.\n\nBei einem vernichtenden Treffer wird das Schiff vor dem Sinken gerettet, indem es in einen undurchdringlichen Schild gehüllt wird. 'Unsinkbar' wird beim Auslösen zerstört.\nBenötigt Ausstattungsbaupläne, die zuletzt im Besitz eines Händlers im Tanaandschungel gesehen wurden.\nVerkaufspreis:"}
