MultiLanguageItemData['de'][127888] = {name = "[q3]Automatischer Himmelsscanner", additional_info = "Marineausstattung\nWird beim Aufheben gebunden\n[q2]Benutzen: Rüstet ein Kriegsschiff mit einem automatischen Himmelsscanner aus.\n\n Unterstützung: Trägerschiff\nVerkaufspreis:"}
