MultiLanguageItemData['de'][127892] = {name = "[q3]Q43-Radaumacherminen", additional_info = "Marineausstattung\nWird beim Aufheben gebunden\n[q2]Benutzen: Rüstet ein Kriegsschiff mit Q43-Radaumacherminen aus.\n\n Unterstützung: U-Boot\nVerkaufspreis:"}
MultiLanguageItemData['de'][127893] = {name = "[q3]Wrackbergungsmodul", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Rüstet ein Kriegsschiff mit einem Wrackbergungsmodul aus.\n[q]\"Beim Einsatz während einer erfolgreichen Mission filtert dieses Gerät das Umgebungsgewässer und birgt eine Kiste voll nützlichem Kram.\""}
MultiLanguageItemData['de'][127894] = {name = "[q3]Tuskarrfischernetz", additional_info = "Marineausstattung\nWird beim Aufheben gebunden\n[q2]Benutzen: Rüstet ein Kriegsschiff mit einem Tuskarrfischernetz aus.\n\nEin Fischernetz der Tuskarr, das am Heck angebracht ist. Fängt Fische und liefert sie bei erfolgreichem Abschluss der Mission ab.\nBenötigt Ausstattungsbaupläne, die zuletzt im Besitz eines Händlers im Tanaandschungel gesehen wurden.\nVerkaufspreis:"}
MultiLanguageItemData['de'][127895] = {name = "[q3]Geisterhaftes Fernglas", additional_info = "Marineausstattung\nWird beim Aufheben gebunden\n[q2]Benutzen: Rüstet ein Kriegsschiff mit einem geisterhaften Fernglas aus.\n\nEin langes Fernglas, das Euch nichts zeigt, wenn Ihr hindurchblickt. Vielleicht erweist es sich doch noch als nützlich.\nBenötigt Ausstattungsbaupläne: Geisterhaftes Fernglas.\nVerkaufspreis:"}
MultiLanguageItemData['de'][127896] = {name = "[q3]Nitrotanks", additional_info = "Wird beim Aufheben gebunden\n[q2]Benutzen: Rüstet ein Kriegsschiff mit Nitrotanks aus.\n[q]\"Ermöglicht es einem Schiff, Nitrotreibstoff zu verbrennen, wodurch es sein Ziel schneller erreichen kann.\""}
MultiLanguageItemData['de'][127897] = {name = "Das Schwert der Wahrheit", additional_info = "Questgegenstand\n[q2]Benutzen: Stoßt Rabenkrones Schwert am ausgewählten Ort in den Boden. (3 Sek. Abklingzeit)\n[q]\"Aus einer dicken Schicht Schmutz und Schmodder glänzt die Klinge hervor.\""}
MultiLanguageItemData['de'][127898] = {name = "Rezept: Uralter Heiltrank", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die Herstellung eines uralten Heiltranks.\n[q2]Stellt einen uralten Heiltrank an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nUralter Heiltrank\n[q2]Benutzen: Regeneriert 6000 Gesundheit. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (4), Kristallphiole"}
MultiLanguageItemData['de'][127899] = {name = "Rezept: Uralter Manatrank", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die Herstellung eines uralten Manatranks.\n[q2]Stellt einen uralten Manatrank an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nUralter Manatrank\n[q2]Benutzen: Regeneriert 2000 Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (5), Kristallphiole"}
MultiLanguageItemData['de'][127900] = {name = "Rezept: Uralter Verjüngungstrank", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die Herstellung eines uralten Verjüngungstranks.\n[q2]Stellt einen uralten Verjüngungstrank an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nUralter Verjüngungstrank\n[q2]Benutzen: Regeneriert 6000 Gesundheit und 1500 Mana. (5 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Uralter Heiltrank , Uralter Manatrank"}
MultiLanguageItemData['de'][127901] = {name = "Rezept: Destillat aus roher Magie", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Destillat aus roher Magie herstellt.\n[q2]Stellt ein Destillat aus roher Magie an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Leyflammenbrenner\nVerkaufspreis: \nDestillat aus roher Magie\n[q2]Benutzen: Auf ex.\nVerkaufspreis:\nBenötigt Aethril (20), Uralter Heiltrank"}
MultiLanguageItemData['de'][127902] = {name = "Rezept: Sylvanelixier", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Sylvanelixier herstellt.\n[q2]Stellt ein Sylvanelixier an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken\nVerkaufspreis: \nSylvanelixier\n[q2]Benutzen: Verwandelt Euch in einen Baum. Ihr und alle Spielercharaktere, die sich in Eurem Schatten ausruhen, werden gut erholt und alle Eure Werte um 10% erhöht.\nVerkaufspreis:\nBenötigt Traumlaub (5), Uralter Heiltrank"}
MultiLanguageItemData['de'][127903] = {name = "Rezept: Lawinenelixier", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Lawinenelixier herstellt.\n[q2]Stellt ein Lawinenelixier an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt zweikammeriges Mischfläschchen\nVerkaufspreis: \nLawinenelixier\n[q2]Benutzen: Wenn Ihr eine lange Strecke fallt, verwandelt Ihr Euch in eine Lawine. Beim Auftreffen fügt Ihr allen Gegnern innerhalb von 5 Metern 1500 Schaden zu. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fuchsblume (5), Uralter Manatrank"}
MultiLanguageItemData['de'][127904] = {name = "Rezept: Skaggldrynk", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man Skaggldrynk herstellt.\n[q2]Stellt einen Skaggldrynk an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Präzipitationspulver\nVerkaufspreis: \nSkaggldrynk\n[q2]Benutzen: Begebt Euch in das Geisterreich und werdet so für 18 Sek. unsichtbar. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fjarnskaggl (5), Uralter Manatrank"}
MultiLanguageItemData['de'][127905] = {name = "Rezept: Himmelslauftrank", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Himmelslauftrank herstellt.\n[q2]Stellt einen Himmelslauftrank an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Seidenfilter der Shal'dorei\nVerkaufspreis: \nHimmelslauftrank\n[q2]Benutzen: Erhöht die Bewegungsgeschwindigkeit um 150% und lässt den Trinkenden in der Luft schweben. Hält 8 Sek. lang an. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (4), Uralter Verjüngungstrank"}
MultiLanguageItemData['de'][127906] = {name = "Rezept: Infernaler Alchemistenstein", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen infernalen Alchemistenstein herstellt.\n[q2]Stellt einen infernalen Alchemistenstein an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel\nVerkaufspreis: \n[q4]Infernaler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie der Verheerten Inseln\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis: \nBenötigt Infernoschwefel , Teufelswurz (5), Blut von Sargeras (3)"}
MultiLanguageItemData['de'][127907] = {name = "Rezept: Trank der tödlichen Anmut", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der tödlichen Anmut herstellt.\n[q2]Stellt einen Trank der tödlichen Anmut an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und Seidenfilter der Shal'dorei.\nVerkaufspreis: \nTrank der tödlichen Anmut\n[q2]Benutzen: Gewährt Euren Angriffen eine Chance, einen Energieblitz auf Euer Ziel zu entfesseln.\n\n Wenn Ihr Euch während der gesamten Effektdauer von Gegnern fernhaltet, wird sie um zusätzliche 5 Sek. verlängert. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fjarnskaggl (2), Traumlaub (2), Kristallphiole"}
MultiLanguageItemData['de'][127908] = {name = "Rezept: Trank des Alten Krieges", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank des Alten Krieges herstellt.\n[q2]Stellt einen Trank des Alten Krieges an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und Präzipitationspulver.\nVerkaufspreis: \nTrank des Alten Krieges\n[q2]Benutzen: Beschwört zwei geisterhafte gefallene Krieger, die an Eurer Seite kämpfen. Sie können Eure Nahkampfangriffe und -fähigkeiten imitieren und verursachen damit 1161 Schaden. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fuchsblume (2), Fjarnskaggl (2), Kristallphiole"}
MultiLanguageItemData['de'][127909] = {name = "Rezept: Unbeugsamer Trank", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen unbeugsamen Trank herstellt.\n[q2]Stellt einen unbeugsamen Trank an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und zweikammeriges Mischfläschchen.\nVerkaufspreis: \nUnbeugsamer Trank\n[q2]Benutzen: Erhöht Eure Rüstung 25 Sek. lang um 124 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Fuchsblume (2), Kristallphiole"}
MultiLanguageItemData['de'][127910] = {name = "Rezept: Leywirbeltrank", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Leywirbeltrank herstellt.\n[q2]Stellt einen Leywirbeltrank an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und Leyflammenbrenner.\nVerkaufspreis: \nLeywirbeltrank\n[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 300 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Traumlaub (2), Kristallphiole"}
MultiLanguageItemData['de'][127911] = {name = "Rezept: Fläschchen des geflüsterten Pakts", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen des geflüsterten Pakts herstellt.\n[q2]Stellt ein Fläschchen des geflüsterten Pakts an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und Seidenfilter der Shal'dorei.\nVerkaufspreis: \nFläschchen des geflüsterten Pakts\n[q2]Benutzen: Erhöht die Intelligenz 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Fjarnskaggl (10), Traumlaub (10), Kristallphiole"}
MultiLanguageItemData['de'][127912] = {name = "Rezept: Fläschchen des Siebten Dämons", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen des Siebten Dämons herstellt.\n[q2]Stellt ein Fläschchen des Siebten Dämons an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und Präzipitationspulver.\nVerkaufspreis: \nFläschchen des Siebten Dämons\n[q2]Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Fuchsblume (10), Fjarnskaggl (10), Kristallphiole"}
MultiLanguageItemData['de'][127913] = {name = "Rezept: Fläschchen der zahllosen Armeen", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen der zahllosen Armeen herstellt.\n[q2]Stellt ein Fläschchen der zahllosen Armeen an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und zweikammeriges Mischfläschchen.\nVerkaufspreis: \nFläschchen der zahllosen Armeen\n[q2]Benutzen: Erhöht die Stärke 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Aethril (10), Fuchsblume (10), Kristallphiole"}
MultiLanguageItemData['de'][127914] = {name = "Rezept: Fläschchen der zehntausend Narben", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Fläschchen der zehntausend Narben herstellt.\n[q2]Stellt ein Fläschchen der zehntausend Narben an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und Leyflammenbrenner.\nVerkaufspreis: \nFläschchen der zehntausend Narben\n[q2]Benutzen: Erhöht die Ausdauer 1 Stunde lang um 69 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Aethril (10), Traumlaub (10), Kristallphiole"}
MultiLanguageItemData['de'][127915] = {name = "Rezept: Geisterkessel", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Geisterkessel herstellt.\n[q2]Stellt einen Geisterkessel an der Dalaraner Alchemiestation her.\nBenötigtAlchemie der Verheerten Inseln\n(100)\nBenötigt leistungsstarken Sudkatalysator\nVerkaufspreis: \nGeisterkessel\n[q7]Wird an Kriegsmeute gebunden\n[q2]Benutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis: \nBenötigt Fläschchen des geflüsterten Pakts (5), Fläschchen des Siebten Dämons (5), Fläschchen der zahllosen Armeen (5), Fläschchen der zehntausend Narben (5), Blut von Sargeras"}
MultiLanguageItemData['de'][127916] = {name = "Altruis' Erkenntnisse", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"In Azsuna muss es jemanden geben, der um die Säulen der Schöpfung weiß.\""}
MultiLanguageItemData['de'][127917] = {name = "Rezept: Uralter Heiltrank", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die effizientere Herstellung eines uralten Heiltranks.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nUralter Heiltrank\n[q2]Benutzen: Regeneriert 6000 Gesundheit. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (4), Kristallphiole"}
MultiLanguageItemData['de'][127918] = {name = "Rezept: Uralter Manatrank", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die effizientere Herstellung eines uralten Manatranks.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUralter Manatrank\n[q2]Benutzen: Regeneriert 2000 Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (5), Kristallphiole"}
MultiLanguageItemData['de'][127919] = {name = "Rezept: Uralter Verjüngungstrank", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch die effizientere Herstellung eines uralten Verjüngungstranks.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nUralter Verjüngungstrank\n[q2]Benutzen: Regeneriert 6000 Gesundheit und 1500 Mana. (5 Min Abklingzeit)\nVerkaufspreis: \nBenötigt Uralter Heiltrank , Uralter Manatrank"}
MultiLanguageItemData['de'][127920] = {name = "Rezept: Destillat aus roher Magie", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Destillat aus roher Magie noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nDestillat aus roher Magie\n[q2]Benutzen: Auf ex.\nVerkaufspreis:\nBenötigt Aethril (20), Uralter Heiltrank"}
MultiLanguageItemData['de'][127921] = {name = "Rezept: Sylvanelixier", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Sylvanelixier effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nSylvanelixier\n[q2]Benutzen: Verwandelt Euch in einen Baum. Ihr und alle Spielercharaktere, die sich in Eurem Schatten ausruhen, werden gut erholt und alle Eure Werte um 10% erhöht.\nVerkaufspreis:\nBenötigt Traumlaub (5), Uralter Heiltrank"}
MultiLanguageItemData['de'][127922] = {name = "Rezept: Lawinenelixier", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man ein Lawinenelixier effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nLawinenelixier\n[q2]Benutzen: Wenn Ihr eine lange Strecke fallt, verwandelt Ihr Euch in eine Lawine. Beim Auftreffen fügt Ihr allen Gegnern innerhalb von 5 Metern 1500 Schaden zu. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fuchsblume (5), Uralter Manatrank"}
MultiLanguageItemData['de'][127923] = {name = "Rezept: Skaggldrynk", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man Skaggldrynk noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nSkaggldrynk\n[q2]Benutzen: Begebt Euch in das Geisterreich und werdet so für 18 Sek. unsichtbar. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fjarnskaggl (5), Uralter Manatrank"}
MultiLanguageItemData['de'][127924] = {name = "Rezept: Himmelslauftrank", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Himmelslauftrank noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nHimmelslauftrank\n[q2]Benutzen: Erhöht die Bewegungsgeschwindigkeit um 150% und lässt den Trinkenden in der Luft schweben. Hält 8 Sek. lang an. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (4), Uralter Verjüngungstrank"}
MultiLanguageItemData['de'][127925] = {name = "Rezept: Infernaler Alchemistenstein", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen infernalen Alchemistenstein noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \n[q4]Infernaler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigtAlchemie der Verheerten Inseln\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis: \nBenötigt Infernoschwefel , Teufelswurz (5), Blut von Sargeras (3)"}
MultiLanguageItemData['de'][127926] = {name = "Rezept: Trank der tödlichen Anmut", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank der tödlichen Anmut noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nTrank der tödlichen Anmut\n[q2]Benutzen: Gewährt Euren Angriffen eine Chance, einen Energieblitz auf Euer Ziel zu entfesseln.\n\n Wenn Ihr Euch während der gesamten Effektdauer von Gegnern fernhaltet, wird sie um zusätzliche 5 Sek. verlängert. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fjarnskaggl (2), Traumlaub (2), Kristallphiole"}
MultiLanguageItemData['de'][127927] = {name = "Rezept: Trank des Alten Krieges", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Trank des Alten Krieges noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nTrank des Alten Krieges\n[q2]Benutzen: Beschwört zwei geisterhafte gefallene Krieger, die an Eurer Seite kämpfen. Sie können Eure Nahkampfangriffe und -fähigkeiten imitieren und verursachen damit 1161 Schaden. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fuchsblume (2), Fjarnskaggl (2), Kristallphiole"}
MultiLanguageItemData['de'][127928] = {name = "Rezept: Unbeugsamer Trank", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen unbeugsamen Trank noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nUnbeugsamer Trank\n[q2]Benutzen: Erhöht Eure Rüstung 25 Sek. lang um 124 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Fuchsblume (2), Kristallphiole"}
MultiLanguageItemData['de'][127929] = {name = "Rezept: Leywirbeltrank", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen Leywirbeltrank noch effizienter herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nLeywirbeltrank\n[q2]Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 300 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Traumlaub (2), Kristallphiole"}
