MultiLanguageItemData['de'][127991] = {name = "Dämonenschlundfrenzy", additional_info = "[q2]Benutzen: Stellt im Verlauf von 20 Sek. 5288 Gesundheit und ( 1375 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet eine Chance, regelmäßig Salven von Teufelsblitzen abzufeuern, während Ihr angreift.\n[q]\"Die Fische des Tanaandschungels waren schon immer böse. Die dämonische Verderbnis hat sie nur zu richtigen Satansbraten gemacht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][127992] = {name = "Neuer Rekrut", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n[q]\"Altruis der Leidende hat die Tapfersten unter den Illidari herausgefordert, sich Euch anzuschließen. Wer wird dem Ruf folgen?\""}
MultiLanguageItemData['de'][127994] = {name = "[q3]Oschi der Dämonenschlundfrenzys", additional_info = "Wird beim Aufheben gebunden\n[q]\"Die Fische des Tanaandschungels waren schon immer böse. Die dämonische Verderbnis hat sie nur zu richtigen Satansbraten gemacht. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\""}
