MultiLanguageItemData['de'][128209] = {name = "Rezept: Wilde Transmutation", additional_info = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man einen wilde Transmutation herstellt.\n[q2]Führt 'Wilde Transmutation' an der Dalaraner Alchemiestation aus.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nBenötigt Leyflammenbrenner, verbesserte Korken, zweikammeriges Mischfläschchen und Präzipitationspulver.\nVerkaufspreis: \nWilde Transmutation\n[q]\"Was werdet Ihr bekommen?\"\nBenötigt Aethril (10), Traumlaub (10), Fuchsblume (10), Fjarnskaggl (10), Sternlichtrose"}
MultiLanguageItemData['de'][128210] = {name = "Rezept: Wilde Transmutation", additional_info = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine wilde Transmutation ohne Alchemietisch herstellt.\n[q2]Benötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nWilde Transmutation\n[q]\"Was werdet Ihr bekommen?\"\nBenötigt Aethril (7), Traumlaub (7), Fuchsblume (7), Fjarnskaggl (7), Sternlichtrose"}
MultiLanguageItemData['de'][128211] = {name = "Rezept: Wilde Transmutation", additional_info = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Benutzen: Lehrt Euch, wie man eine wilde Transmutation mit mehreren Effekten herstellt.\n[q2]Chance auf die Herstellung mehrerer Gegenstände.\nBenötigtAlchemie der Verheerten Inseln\n(1)\nVerkaufspreis: \nWilde Transmutation\n[q]\"Was werdet Ihr bekommen?\"\nBenötigt Aethril (5), Traumlaub (5), Fuchsblume (5), Fjarnskaggl (5), Sternlichtrose"}
