MultiLanguageItemData['de'][128819] = {name = "[q6]Schicksalshammer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Streitkolben}\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Feuer Artefakt Relikt Slot\n[q0]Eisen Artefakt Relikt Slot\n\nKlassen: Schamane\n[q2]Anlegen: Gewährt Euch den Zauber 'Schicksalswinde', durch den Ihr 'Windzorn' auf Eure Gegner niedergehen lasst.\n[q]\"Ein Fremder wird den Hammer erheben und durch ihn wird die Gerechtigkeit walten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128820] = {name = "[q6]Felo'melorn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Feuer Artefakt Relikt Slot\n[q0]Arkan Artefakt Relikt Slot\n\nKlassen: Magier\n[q2]Anlegen: Gewährt die Fähigkeit 'Phönixflammen', die zerstörerisches Feuer auf alle Gegner in der Nähe Eures Ziels schleudert.\n[q]\"...keine elfischen Waffen. Nicht, wenn sie mit Magie und Hass und einer brennenden Begierde nach Rache neu geschmiedet wurden. Nein, Arthas. Felo'melorn ist stärker als je zuvor. So wie auch ich. - Kael'thas Sonnenwanderer\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128821] = {name = "[q6]Ursocs Klauen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Faustwaffe}\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Feuer Artefakt Relikt Slot\n[q0]Blut Artefakt Relikt Slot\n\nKlassen: Druide\n[q2]Anlegen: Gewährt die Fähigkeit 'Zorn des Schläfers', die Euch durch den Avatar von Ursoc große Macht verleiht.\n[q]\"Ursoc, Bruder des Ursol und Beschützer der Furbolgstämme... Träger der Kraft des Waldes selbst.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128822] = {name = "[q6]Ursocs Klauen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Faustwaffe}\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Druide\n[q]\"Azeroth wird Euch brauchen. Wenn Ihr nicht bereit seid, könnte die Welt fallen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128823] = {name = "[q6]Die Silberne Hand", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Streitkolben}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Heilig Artefakt Relikt Slot\n[q0]Leben Artefakt Relikt Slot\n\nKlassen: Paladin\n[q2]Anlegen: Erhöht die Rüstung um 30%.\n[q2]Anlegen: Gewährt die Fähigkeit 'Tyrs Errettung', die Verbündete in der Nähe mit einer Heilungswelle überflutet. (Procchance: 6%)\n[q]\"Tyr antwortete, dass er seine silberne Hand nicht als Zeichen seiner Niederlage ansah. Für ihn war es das Symbol seiner Aufopferung für die Verteidigung von Azeroth und er wollte, dass auch der Rest der Welt dies so sah.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128824] = {name = "[q0]Foliant der Silbernen Hand", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n47 Rüstung\n+7 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nKlassen: Paladin\n[q]\"Esarus thar no'Darador.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128825] = {name = "[q6]T'uure, Fanal der Naaru", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Heilig Artefakt Relikt Slot\n[q0]Leben Artefakt Relikt Slot\n\nKlassen: Priester\n[q2]Anlegen: Eure Segenswörter haben eine Chance, ein Abbild von T'uure an Eurer Seite zu beschwören, das Euch im Kampf unterstützt.\n[q]\"Gesegnet seien die Fackelträger, die Licht ins Dunkel bringen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128826] = {name = "[q6]Thas'dorah, Erbstück von Haus Windläufer", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Distanz} {Bogen}\n3 - 5 Schaden Geschwindigkeit 3.00\n(1.3 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Sturm Artefakt Relikt Slot\n[q0]Blut Artefakt Relikt Slot\n\nKlassen: Jäger\n[q2]Anlegen: Gewährt Zugriff auf die Fähigkeit 'Windstoß', die dem Ziel massiven Schaden zufügt und die Bewegungsgeschwindigkeit aller Verbündeten auf der Flugbahn des Pfeils erhöht.\n[q]\"Als er aus dem Sonnenbrunnen zurückgeholt wurde, strahlte der Bogen Macht aus. Talanas empfand große Ehre beim Anblick dieser Gabe. Er nannte die Waffe Thas'dorah: 'Ehre des Waldes'.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128827] = {name = "[q6]Xal'atath, Klinge des Schwarzen Imperiums", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 Schaden Geschwindigkeit 1.80\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Schatten Artefakt Relikt Slot\n[q0]Blut Artefakt Relikt Slot\n\nKlassen: Priester\n[q2]Anlegen: Gewährt die Fähigkeit 'Leerenstrom', die massiven Schattenschaden verursacht und Euren Abstieg aus dem Wahnsinn verlangsamt.\n[q]\"Xal'atath hat ihren eigenen Kopf. Ignoriert ihr unerträgliches Flüstern. Glaubt niemals ihren Lügen. Nehmt, was Ihr von ihr braucht, aber denkt immer daran, dass die dunkle Präsenz in der Klinge nicht Eure Verbündete ist.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128831] = {name = "[q6]Kriegsklingen der Aldrachi", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Dämonenjäger\n[q]\"Seine Kriegsklingen heulten lauter als das Schlachtgetöse und zerrissen jeden, der ihnen nahekam. Jeder Dämon, den Toranaar bezwang, schien ihn mit neuer Lebenskraft und Stärke zu erfüllen. Er war eine Armee in sich selbst.\""}
MultiLanguageItemData['de'][128832] = {name = "[q6]Kriegsklingen der Aldrachi", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Eisen Artefakt Relikt Slot\n[q0]Arkan Artefakt Relikt Slot\n\nKlassen: Dämonenjäger\n[q2]Anlegen: Verleiht die Fähigkeit 'Seelenschnitzer', die Euer Ziel aufschlitzt, ihm Feuerschaden zufügt und ihm geringe Seelenfragmente entreißt.\n[q]\"Die Aldrachi waren ein stolzes Volk. Zu stolz, um zu dienen. Millionen von Dämonen starben, bevor die Aldrachi ausgelöscht wurden, und nur Sargeras selbst vollbrachte es, ihren König zu töten.\""}
