MultiLanguageItemData['de'][128858] = {name = "[q6]Sichel von Elune", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Arkan Artefakt Relikt Slot\n[q0]Leben Artefakt Relikt Slot\n\nKlassen: Druide\n[q2]Anlegen: Gewährt den Zauber 'Neumond', der Schaden verursacht und dann in einen machtvolleren Zauber umgewandelt wird.\n[q]\"Hierin steckt eine Kraft, die frei sein will. Durch Gleichgewicht und Beherrschung kann der Wolf gebändigt werden, doch nur für gewisse Zeit.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128859] = {name = "[q6]Fänge von Ashamane", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Druide\n[q]\"Sie tobte durch die Reihen der Dämonen und verschwand dann zwischen den Bäumen. Sie verbarg sich in den Wipfeln und stürzte sich auf die Kommandanten der Legion. Sie war eine furchterregende Bestie. Sie kannte kein Halten, keine Gnade.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128860] = {name = "[q6]Fänge von Ashamane", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Frost Artefakt Relikt Slot\n[q0]Blut Artefakt Relikt Slot\n\nKlassen: Druide\n[q2]Anlegen: Gewährt die Fähigkeit 'Ashamanes Raserei', die eine Reihe blutiger Angriffe auf ein gegnerisches Ziel entfesselt.\n[q]\"Ashamanes Opfer wird bis heute gedacht. Wir leben durch ihre Gnade und ihre Kinder durchstreifen als treue Begleiter noch immer mit uns die Wälder.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128861] = {name = "[q6]Titanenblitz", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Distanz} {Schusswaffe}\n3 - 6 Schaden Geschwindigkeit 3.00\n(1.5 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Sturm Artefakt Relikt Slot\n[q0]Arkan Artefakt Relikt Slot\n\nKlassen: Jäger\n[q2]Anlegen: Hati kämpft jetzt als Begleiter für Euch.\n\"Ein unnachahmliches Beispiel technomagischer Ingenieurskunst, erfüllt mit der Macht der Stürme.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128862] = {name = "[q6]Schwarzfrost", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Frost Artefakt Relikt Slot\n[q0]Arkan Artefakt Relikt Slot\n\nKlassen: Magier\n[q2]Anlegen: Gewährt die Fähigkeit 'Schwarzblitz', die einem Einzelziel massiven Schattenfrostschaden zufügt.\n[q]\"Schwarzfrost enthielt nur einen kleinen Teil von Alodis Macht, doch selbst das war mehr, als die meisten Magi je zu beherrschen hoffen durften.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128864] = {name = "Die steinigen Hügel des Hochbergs", additional_info = "Questgegenstand\n[q]\"Die Tinte ist durch Ziegenspeichel verlaufen und unscharf.\""}
MultiLanguageItemData['de'][128866] = {name = "[q6]Der Wahrheitshüter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n25 Rüstung\n+1 Stärke\n+3 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Heilig Artefakt Relikt Slot\n[q0]Eisen Artefakt Relikt Slot\n\nKlassen: Paladin\n[q2]Anlegen: Gewährt die Fähigkeit 'Auge von Tyr', die einen Lichtblitz aus Eurem Schild hervorruft, der Gegner in der Nähe schwächt.\n[q]\"Als der Hammer das erste Mal fiel, entsprangen Flüsse aus Magma aus dem Eis. Beim zweiten Mal heulte der Himmel auf und Blitze entflammten ihn. Beim dritten Mal drang ein Sonnenstrahl durch den Sturm und flüsterte über die Oberfläche des Wahrheitshüters.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128867] = {name = "[q6]Eidsucher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Paladin\n[q]\"Töten um des Tötens willen... Erobern um der Eroberung willen... Es liegt keine Ehre in solchen Dingen. Nur Schande und Bedauern.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128868] = {name = "[q6]Zorn des Lichts", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Heilig Artefakt Relikt Slot\n[q0]Schatten Artefakt Relikt Slot\n\nKlassen: Priester\n[q2]Anlegen: Gewährt die Fähigkeit 'Zorn des Lichts', die einen Strom heiligen Feuers auf einen Gegner niedergehen lässt. (Procchance: 15%)\n[q]\"Wir wohnten an diesem Tag voller Hoffnung und Hingabe der Zeremonie bei... und verließen sie voller Kummer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128869] = {name = "[q6]Die Königsmörder", additional_info = "Kummer\nWird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schurke\n[q]\"Es war kein angenehmer Tod. Doch er war schnell, lautlos und effizient. Als der Orc seinen letzten Atemzug tat, verzerrte dies die tödliche Wunde. Niemand konnte sagen, ob er einem Messer, einer Axt oder einem Speer erlegen war.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128870] = {name = "[q6]Die Königsmörder", additional_info = "Qual\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Dolch}\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Schatten Artefakt Relikt Slot\n[q0]Eisen Artefakt Relikt Slot\n\nKlassen: Schurke\n[q2]Anlegen: Gewährt Euch die Fähigkeit 'Königsmord', die Eurem Ziel ein Gift von unerreichter Potenz injiziert.\n[q]\"Unzählige Stimmen wurden zum Schweigen gebracht, unzählige Anführer gestürzt... alles auf sein launisches, finsteres Geheiß. Für diese Taten würde es keine Wiedergutmachung geben, nur Einsamkeit und Kummer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128872] = {name = "[q6]Die Schreckensklingen", additional_info = "Schicksal\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Schwert}\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Blut Artefakt Relikt Slot\n[q0]Eisen Artefakt Relikt Slot\n\nKlassen: Schurke\n[q2]Anlegen: Gewährt die Fähigkeit 'Fluch der Schreckensklingen', durch die Ihr Finishing-Moves schneller einsetzen könnt... dafür jedoch einen Preis zahlt.\n[q]\"Sie sah sich selbst, wie sie eine riesige Piratenflotte kommandierte, eine, die die See beherrschen und ganz Azeroth unterwerfen konnte. Jeder, der es wagte, sie herauszufordern, wurde verbrannt und jede Stadt, die an ihren Schätzen festhielt, vernichtet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128873] = {name = "[q6]Zorn der Steinmutter", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schildhand} {Streitkolben}\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schamane\n[q]\"Erschaffen durch die Macht des Schicksalshammers und des Schamanen, der diesen trägt.\"\nVerkaufspreis:"}
