MultiLanguageItemData['de'][128908] = {name = "[q6]Kriegsschwerter der Valarjar", additional_info = "Odyns Zorn\nWird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Feuer Artefakt Relikt Slot\n[q0]Sturm Artefakt Relikt Slot\n\nKlassen: Krieger\n[q2]Anlegen: Gewährt die Fähigkeit 'Odyns Zorn', die Gegnern in der Nähe massiven Feuerschaden zufügt.\n[q]\"Helyas Verrat wird nie vergeben werden. Lasst sie unter den Wellen verrotten, fern der Hallen der Tapferkeit.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128910] = {name = "[q6]Strom'kar der Kriegsbrecher", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Schwert}\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Eisen Artefakt Relikt Slot\n[q0]Blut Artefakt Relikt Slot\n\nKlassen: Krieger\n[q2]Anlegen: Gewährt die Fähigkeit 'Kriegsbrecher', die in einem Bereich massiven Schaden verursacht und Gegner verwundbar macht.\n[q]\"Der letzte Schlag wird durch den Stahl des barbarischen Königs erfolgen. Mit ihm wird das Getöse der Schlacht verstummen und für das erste Königreich wird ein neues Zeitalter des Friedens beginnen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128911] = {name = "[q6]Sharas'dal, Szepter der Gezeiten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Streitkolben}\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Leben Artefakt Relikt Slot\n[q0]Frost Artefakt Relikt Slot\n\nKlassen: Schamane\n[q2]Anlegen: Gewährt die Fähigkeit 'Gabe der Königin', die Eure Verbündeten um einen großen Betrag heilt und ihre maximale Gesundheit erhöht.\n[q]\"Sie trieben den Abgrund hinab, doch Azshara und ihre Hochgeborenen blieben ungebrochen. Sie waren von absoluter Dunkelheit umgeben, und die Königin zwang Sharas'dal, ihnen das Licht zu bringen...\"\nVerkaufspreis:"}
