MultiLanguageItemData['de'][128921] = {name = "Zauberschlacke", additional_info = "Questgegenstand\n[q]\"Die angesammelte Schlacke einer Stadt voller Magier.\""}
MultiLanguageItemData['de'][128922] = {name = "Alchemistische Flamme", additional_info = "Questgegenstand\n[q]\"Unter Alchemisten umgangssprachlich 'flüssiges Feuer' genannt.\""}
MultiLanguageItemData['de'][128923] = {name = "Bezauberte Isolierung", additional_info = "Questgegenstand\n[q]\"Speziell verarbeitet, um sowohl gegen Hitze als auch Leyenergie zu schützen.\""}
MultiLanguageItemData['de'][128924] = {name = "Stillgelegte Heizung", additional_info = "Questgegenstand\n[q]\"Eher mechanisch denn magisch. Möglicherweise stammt sie aus dem Ingenieursladen?\""}
MultiLanguageItemData['de'][128933] = {name = "Rashars rechtes Auge", additional_info = "Questgegenstand\n[q]\"Das bernsteinfarbene Auge hat einen weichen, warmen Schimmer, der zu einem genaueren Blick einlädt.\""}
MultiLanguageItemData['de'][128934] = {name = "[q6]Schild der Meereskönigin", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n25 Rüstung\n+1 Stärke\n+3 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schamane\n[q]\"Als der Ozean das Leben aus ihren Körpern schmetterte, regten sich uralte Kreaturen in der Dunkelheit. Ihr Flüstern floss durch die Strömung. Ihre Macht legte sich eng um die Königin und ihre Diener.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128935] = {name = "[q6]Die Faust des Ra-den", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Faustwaffe}\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+6 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Sturm Artefakt Relikt Slot\n[q0]Frost Artefakt Relikt Slot\n\nKlassen: Schamane\n[q2]Anlegen: Gewährt die Fähigkeit 'Sturmhüter', die Euren 'Blitzschlag' oder 'Kettenblitzschlag' mit großer Macht erfüllt.\n[q]\"Um Al'Akirs Untergang zu besiegeln, donnerte Meister Ra seine Faust in den Gipfel des Berges. Der Himmel brach auf und all das Feuer und der Zorn darin stürzte hinab auf den Windlord.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128936] = {name = "[q6]Schutz des hohen Hüters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Schild}hand} {Schild}\n25 Rüstung\n+1 Stärke\n+3 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\nKlassen: Schamane\n[q]\"Ra und Helya erschufen einen Schild, den Schutz des hohen Hüters, als Schlüssel für die Elementarebene. Er pulsierte mit der Energie der vier Elemente, die Ra nach Belieben rufen konnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128937] = {name = "[q6]Sheilun, Stab der Nebel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Frost Artefakt Relikt Slot\n[q0]Leben Artefakt Relikt Slot\n\nKlassen: Mönch\n[q2]Anlegen: Gewährt Euch den Zauber 'Sheiluns Gabe', der einen Verbündeten um einen beträchtlichen Wert heilt.\n[q]\"Ihr sucht die ruhige, unausweichliche Macht eines tiefen Flusses, der Schluchten in den stärksten Stein schneidet und Krieger mit seinen Strömungen ohne das leiseste Kräuseln hinfortträgt. Sheilun ist die Verkörperung dieses Konzepts.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128938] = {name = "[q6]Fu Zan, Gefährte des Wanderers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n4 - 6 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Beweglichkeit\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Leben Artefakt Relikt Slot\n[q0]Sturm Artefakt Relikt Slot\n\nKlassen: Mönch\n[q2]Anlegen: Gewährt die Fähigkeit 'Explodierendes Fässchen', die genau das tut, was Ihr glaubt, dass sie es tut.\n[q]\"Von Anfang an hat dieser Stab legendäre Wesen und unsterbliche Geister begleitet, während sie wichtige Arbeiten in ganz Azeroth ausführten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128940] = {name = "[q6]Fäuste der Himmel", additional_info = "Al'burq\nWird beim Aufheben gebunden\nEinzigartig\n{Waffenhand} {Faustwaffe}\n2 - 3 Schaden Geschwindigkeit 2.60\n(1.0 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Sturm Artefakt Relikt Slot\n[q0]Eisen Artefakt Relikt Slot\n\nKlassen: Mönch\n[q2]Anlegen: Gewährt die Fähigkeit 'Schlag des Windlords', die einen heftigen Doppelangriff hervorruft, der Euren Gegner zusätzlich verkrüppelt.\n[q]\"Als Irmaat seine zwei Waffen erhob und die Macht in ihnen auf die Probe stellte, entsprang daraus unkontrollierbare Wut.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128941] = {name = "[q6]Szepter des Sargeras", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Teufel Artefakt Relikt Slot\n[q0]Feuer Artefakt Relikt Slot\n\nKlassen: Hexenmeister\n[q2]Anlegen: Gewährt die Fähigkeit 'Dimensionsriss', die Portale in Raum und Zeit aufreißt und vernichtenden Schaden gegen Eure Gegner freisetzt.\n[q]\"Als schließlich der Moment kam, in dem Ner'zhul zum Handeln gezwungen war, tat er es ganz hemmungslos und dachte dabei nicht an Konsequenzen. Die Vernichtung von Draenor war ihm egal, er hieß sie sogar als Teil seines Vermächtnisses willkommen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128942] = {name = "[q6]Ulthalesh, Sense der Totenwinde", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\n{Zweihändig} {Stab}\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\n\n[q0]Schatten Artefakt Relikt Slot\n[q0]Blut Artefakt Relikt Slot\n\nKlassen: Hexenmeister\n[q2]Anlegen: Gewährt die Fähigkeit 'Seelen ernten', die die Seelen gefallener Gegner erntet, um Ulthalesh mit Macht zu erfüllen.\n[q]\"Der Meister der Sichel wird entweder Sataiel besiegen oder verschlungen werden, was die Klinge nur noch stärker machen wird. Danach wird ein anderer kommen, um seinen Platz einzunehmen. Und danach wieder ein anderer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][128943] = {name = "[q6]Schädel der Man'ari", additional_info = "Wird beim Aufheben gebunden\nEinzigartig\nIn Schildhand geführt\n+3 Intelligenz\n+2 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 1.\n[q2]Erhöht Eure Meisterschaftswertung um + 1.\n\n[q0]Schatten Artefakt Relikt Slot\n[q0]Feuer Artefakt Relikt Slot\n\nKlassen: Hexenmeister\n[q2]Anlegen: Gewährt die Fähigkeit 'Thal'kiels Verzehr', durch die Thal'kiel gerufen wird, um einen Gegner zu quälen.\n[q]\"Als Thal'kiel endlich erschien, war er verändert. Um Jahrhunderte gealtert, allein in der Dunkelheit mit seinen Gedanken und Sklaven. Er war buckelig und hatte ein merkwürdiges Glänzen in den Augen. Er beschwor seine Erwecker und wir antworteten ihm...\"\nVerkaufspreis:"}
