MultiLanguageItemData['de'][132365] = {name = "[q5]Bryndaors Fesseln", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\n[q2]Anlegen: Wenn Ihr durch 'Todesstoß' um mehr als 10% Eurer maximalen Gesundheit geheilt werdet, erhaltet Ihr 15% der verbrauchten Runenmacht zurück.\n[q]\"Für seine schändlichen Taten wurde Bryndaor verdammt, in alle Ewigkeit an den Toren Helheims Wache zu halten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132366] = {name = "[q5]Koltiras neugefundener Wille", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\n[q2]Anlegen: 'Auslöschen' verursacht 10% mehr Schaden und hat eine Chance von 15%, 1 Runen zurückzuerstatten. (Procchance: 15%)\n[q]\"Nach der Schlacht an der Kapelle des Hoffnungsvollen Lichts trennten sich die Wege der zwei Kameraden. Thassarian trat in den Dienst seines Königs, während Koltira, vormaliger Verteidiger von Quel'Thalas, zu seinem Volk, den Blutelfen, zurückkehrte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132367] = {name = "[q5]Dienst von Blutschatten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]+ 3 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n[q2]+ 6 Lebensdiebstahl\nHaltbarkeit 70 / 70\nKlassen: Todesritter\n[q2]Anlegen: 'Herzstoß' verringert die verbleibende Abklingzeit von 'Vampirblut' um 2 Sek.\n[q]\"Nach seinem Tod kehrte Blutschatten als erster Todesritter zurück und schwor Orgrim Schicksalshammer die Treue.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132368] = {name = "Erstes Fragment von Farondis' Band", additional_info = "Questgegenstand\n[q]\"Ein Bruchstück von Farondis' Band.\""}
MultiLanguageItemData['de'][132369] = {name = "[q5]Wilfreds Siegel der überlegenen Beschwörung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 8.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Hexenmeister\n[q2]Anlegen: Jede Beschwörung eines Schreckenspirschers oder Wildwichtels verringert die verbleibende Abklingzeit von 'Dämonischen Tyrannen beschwören' und 'Höllenbestie beschwören' um 2 Sek.\n[q]\"An einem entscheidenden Tag des Argentumturniers zu Hause vergessen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132370] = {name = "Salzaugenarmreif", additional_info = "Questgegenstand\n[q]\"Ein primitiver Ring, passend für Murlocnasenlöcher, -lippen und -flossen.\""}
MultiLanguageItemData['de'][132371] = {name = "Treibholz", additional_info = "Questgegenstand\n[q]\"Ein Stück sonnengebleichtes Treibholz.\""}
MultiLanguageItemData['de'][132374] = {name = "[q5]Kazzaks letzter Fluch", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\n[q2]Anlegen: 'Verdammnis' verursacht für jeden Eurer aktiven Dämonenbegleiter 5% höheren Schaden.\n[q]\"Als der Verdammnislord durch das Dunkle Portal in die Scherbenwelt schritt, hinterließ er seinen Feinden ein Abschiedsgeschenk...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132375] = {name = "[q5]Odr, Schal der Ymirjar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 2.\nKlassen: Hexenmeister\n[q2]Anlegen: Gegner, die von Eurer 'Verwüstung' markiert wurden, erleiden durch Eure Einzelzielzauber 15% mehr Schaden.\n[q]\"In einwandfreiem Zustand unter dem verbranntem Schutt des Dorfes Ymirheim aufgefunden.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132376] = {name = "[q5]Tuch von Acherus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nRücken\n3 Rüstung\n+3 Stärke\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 2.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nKlassen: Todesritter\n[q2]Anlegen: Erhöht die Dauer von 'Antimagische Hülle' um 100%, und jeglicher absorbierter Schaden heilt Euch.\n[q]\"Denn Ihr steht nicht nur mir allein gegenüber, sondern der gesamten Schwarzen Klinge. Wir sind unsterblich, unerbittlich und wir hungern nach Leben!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132377] = {name = "Aridens Kompass", additional_info = "Questgegenstand\n[q]\"Ein abgenutzter alter Kompass, der mit den Dunklen Reitern des Gebirgspasses der Totenwinde in Verbindung steht.\""}
MultiLanguageItemData['de'][132378] = {name = "[q5]Sacrolashs Dunkelstoß", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 7.\n[q2]Erhöht Eure Meisterschaftswertung um + 7.\n\n[q0]Prismatischer Sockel\n\nKlassen: Hexenmeister\n[q2]Anlegen: 'Verderbnis' verursacht 15% mehr Schaden und verringert die Bewegungsgeschwindigkeit von Gegnern um 60%.\n[q]\"Elend... Verwirrung... Misstrauen. Dies sind die Kennzeichen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132379] = {name = "[q5]Tücke der Sin'dorei", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\n[q2]Anlegen: Nach dem Wirken von 'Verdammniswache beschwören', 'Höllenbestie beschwören' oder 'Dämonischen Tyrannen beschwören' verursachen Ihr und Eure Diener 25 Sek. lang 15% mehr Schaden. [ Grimoire der Überlegenheit : Dieser Effekt kann nur einmal alle 3 Min. auftreten ]\n[q]\"So viele unseres Volkes wurden durch die Brennende Legion unterjocht und zu verderbten Schatten ihrer selbst gemacht. Es ist ausgleichende Gerechtigkeit, wenn wir ihre eigenen Armeen gegen sie einsetzen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132381] = {name = "[q5]Stretens schlaflose Schlingen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\n[q2]Anlegen: Für jeden Gegner, der mit Eurem Zauber 'Instabiles Gebrechen' belegt ist, wird Euer gesamter verursachter Schaden um 4% erhöht.\n[q]\"Das einzige Risiko ist, dass Ihr wahnsinnig werdet.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132393] = {name = "[q5]Regelmäßiges Ritual", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Hexenmeister\n[q2]Anlegen: 'Schreckenspirscher rufen' erstattet 1 Seelensplitter zurück.\n[q]\"Es hat Außenstehende schon immer erstaunt, wie einige Vrykulhexenmeister riesige Rudel von Teufelspirschern beschwören und ihrem Willen unterwerfen konnten.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132394] = {name = "[q5]Kapuze der ewigen Verachtung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 120 / 120\nKlassen: Hexenmeister\n[q2]Anlegen: 'Agonie' verursacht den vollen Schaden um 10% schneller.\n[q]\"Wer diese Kapuze anlegt, wird von unheiliger Stärke und Entschlossenheit erfüllt. Doch wird er auf ewig alle Freundlichkeit und Güte verlieren. Hütet Euch...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132406] = {name = "[q5]Unvergleichliche Bindungen des Sonnenkönigs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Magier\n[q2]Anlegen: Nachdem Ihr 'Kampfeshitze' verbraucht habt, habt Ihr eine Chance von 15%, dass Euer nächster nicht spontaner, innerhalb von 15 Sek. gewirkter 'Pyroschlag' 300% mehr Schaden verursacht.\n[q]\"Entgegen der vorherrschenden Meinung war das bevorzugte (und zumeist auch finale) Wort von Kael'thas an seine Feinde: PYROSCHLAG!\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132407] = {name = "[q5]Fesseln des Magiestoßes", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\n[q2]Anlegen: 'Chaosblitz' hat eine Chance von 20%, einen weiteren Gegner innerhalb von 30 Metern zu treffen. (Procchance: 20%)\n[q]\"Varo'then war unsterblich in die Königin verliebt. Leider bekam er nie die Gelegenheit, ihr diese Fesseln anzulegen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132409] = {name = "[q5]Anunds versengte Fesseln", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Priester\n[q2]Anlegen: Jedes Mal, wenn 'Schattenwort: Schmerz' und 'Vampirberührung' Schaden verursachen, wird der Schaden Eures nächsten Einsatzes von 'Leerenblitz' um 3% erhöht. Bis zu 50-mal stapelbar.\n[q]\"Niemand weiß, warum Anund vor Kaldrigos stand. Laut einer Legende war es aber Anunds letztes 'Schattenwort: Schmerz', das Korl zum Sieg über den schrecklichen Wyrm verhalf.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132410] = {name = "[q5]Splitter der Exodar", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 9.\n[q2]Erhöht Eure Tempowertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Magier\n[q2]Anlegen: Eure Fähigkeit 'Zeitkrümmung' belegt Euch nicht mehr mit dem Effekt 'Temporale Verzerrung' und ignoriert eine bestehende 'Temporale Verzerrung', sowie ähnliche auf Euch aktive Effekte.\n[q]\"Die Hauptstadt der Draenei vermag zwischen den Dimensionen zu reisen und sogar die Zeit selbst zu verzerren. Was könnte ein winziges Fragment dieser Macht wohl alles in den Händen eines Sterblichen bewirken?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132411] = {name = "[q5]Lady Vashjs Griff", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\n[q2]Anlegen: Während 'Eisige Adern' aktiv ist, erhaltet Ihr alle 10 Sek. 1 Aufladungen von 'Eisige Finger'.\n[q]\"Erfüllt von der Macht der Nagameereshexe fühlen sich Eure Finger darin etwas kalt an, sind aber überraschend beweglich und voller Energie.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132413] = {name = "[q5]Rhonins Angriffsarmwickel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\n[q2]Anlegen: 'Arkane Geschosse' haben eine Chance von 18%, dass Euer nächster Einsatz von 'Arkanschlag' innerhalb von 6 Sek. kostenlos wird. (Procchance: 18%)\n[q]\"Magier, die so mächtig sind wie der ehemalige Anführer der Kirin Tor Rhonin, verwenden oft arkane Bindungen, um die Magie zu stabilisieren, die sich aus ihren Fingerspitzen entlädt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132436] = {name = "[q5]Skjoldr, Ivagonts Refugium", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Priester\n[q2]Anlegen: Euer 'Machtwort: Schild' absorbiert 15% mehr Schaden und verringert die verbleibende Abklingzeit von 'Schmerzunterdrückung' um 4 Sek.\n[q]\"Ivagont kämpfte während des Massakers der Sturmschuppennaga an der Dunkelküste so wie immer an der Seite von Kakushan. Durch seinen Schutz überlebten beide ohne einen Kratzer.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132437] = {name = "[q5]Mutter Shahraz' Verführung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Schulter} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 120 / 120\nKlassen: Priester\n[q2]Anlegen: Wenn Ihr die Leerengestalt annehmt, erhaltet Ihr 3 Stapel von Leerengestalt.\n[q]\"Ihr scheint mir ein wenig verspannt zu sein...\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132438] = {name = "Talisman des Aufstiegs", additional_info = "Questgegenstand\n[q]\"(NYI - Requires Revered with Valkyra) Given to Valkyra who have proven themselves ready to ascend to the highest ranks of their order.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132440] = {name = "Der Svalngard", additional_info = "Questgegenstand\n[q]\"Großschild von Odyn, dem Herrn der Hallen der Tapferkeit.\""}
MultiLanguageItemData['de'][132441] = {name = "[q5]Draugr, Gurt des ewigen Königs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Platte}\n10 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\n[q2]Anlegen: 'Schwärender Stoß' hat eine Chance von 30%, 1 Runen zurückzuerstatten. (Procchance: 30%)\n[q]\"Laut einer Legende sind die Körper der Titanenbrut so von der Energie der Schöpfer erfüllt, dass beim Tod des sterblichen Wirts Fragmente zurückbleiben. Angeblich wurde dieser Gurt sorgfältig aus diesen Fragmenten zusammengenäht.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132442] = {name = "[q5]Kordel der Unendlichkeit", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\n[q2]Anlegen: Erhöht den von 'Arkane Geschosse' verursachten Schaden um 10%.\n[q2]Anlegen: Jedes Mal, wenn 'Arkane Geschosse' einen Gegner trifft, wird der Schaden Eures nächsten Einsatzes von 'Mal von Aluneth' um 1.0% erhöht. Dieser Effekt ist stapelbar.\n[q]\"Die darin enthaltene Magie scheint ebenso wenig ein Ende zu nehmen wie die Brennende Legion.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132443] = {name = "[q5]Aggramars Schritte", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Platte}\n11 Rüstung\n+4 [Stärke oder Intelligenz]\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 95 / 95\nKlassen: Krieger , Paladin , Todesritter\n[q2]Anlegen: Erhöht Eure Bewegungsgeschwindigkeit um 75% Eures Tempos, Eures kritischen Trefferwerts, Eurer Meisterschaft oder Eurer Vielseitigkeit, je nachdem, welcher Wert am höchsten ist.\n[q]\"Zeit und Raum sind eins. Für einen Beobachter des Universums ist Entfernung so gut wie bedeutungslos.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132444] = {name = "[q5]Prydaz, Xavarics Magnum Opus", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHals\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\n\n[q0]Prismatischer Sockel\n[q2]Anlegen: Verleiht Euch für 30 Sek. alle 30 Sek. einen Absorptionsschild in Höhe von 25% Eurer maximalen Gesundheit.\n[q]\"Träger dieses Amuletts pfeifen eine beunruhigende Melodie, und alle in der Nähe hören zwischen den Noten immer wieder gequälte Schreie, die aus weiter Ferne zu kommen scheinen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132445] = {name = "[q5]Al'maiesh, der Faden der Hoffnung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Priester\n[q2]Anlegen: Wenn 'Glücksfall' ausgelöst wird und das Segenswort nicht von Abklingzeit betroffen ist, erhöht 'Glücksfall' den Schaden und die Heilung Eures nächsten Einsatzes dieses Segenswortes um 10%. Dieser Effekt ist bis zu 5-mal stapelbar.\n[q]\"Angeblich gehörte sie der ursprünglichen Val'kyr.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132446] = {name = "Jabruls Juwelen", additional_info = "Questgegenstand\n[q]\"Ein großer Beutel, der verschiedene Edelsteine enthält.\""}
MultiLanguageItemData['de'][132447] = {name = "[q5]Bezaubernde Beinkleider von An'juna", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Priester\n[q2]Anlegen: Erhöht die Dauer von 'Erneuerung' um 6 Sek.\n[q]\"Die Träger dieser Beinkleider gehen oft bis zum Äußersten und vollbringen mehr, als die Pflicht von ihnen verlangt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132448] = {name = "[q5]Die vierte Lektion des Instrukteurs", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\n[q2]Anlegen: Geißelstoß hat eine Chance, 1-2 zusätzliche schwärende Wunden aufzubrechen.\n[q]\"Dieses Geschenk übergab Razuvious angeblich seinen begabtesten Akolythen. Aber niemand weiß, wie es aus den Mauern von Naxxramas entkam. Hat der Lichkönig vielleicht seine eigenen Agenten auf die Verheerten Inseln entsandt?\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132449] = {name = "[q5]Phyrix' Umarmung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 9.\n[q2]Erhöht Eure Meisterschaftswertung um + 5.\n\n[q0]Prismatischer Sockel\n\nKlassen: Priester\n[q2]Anlegen: Erhöht die Dauer und den Heilbonus von 'Schutzgeist' um 50% und der Heilbonuseffekt von 'Schutzgeist' wird nicht mehr abgebrochen, wenn er sich opfert.\n[q]\"Phyrix war eine legendäre Priesterin, die Abenteurer durch den Geschmolzenen Kern und den Pechschwingenhort führte. Leider setzte Nefarian ihrem Leben ein Ende, aber ihr Geist beschützt Azeroths Champions bis zum heutigen Tag.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132450] = {name = "[q5]Muzes standhafter Wille", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 2.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Priester\n[q2]Anlegen: Wenn Ihr über mehr als 75% Gesundheit verfügt, wird die Zauberzeit Eurer Fähigkeiten 'Blitzheilung', 'Heilung', 'Gebet der Heilung' und 'Heilige Pein' um 15% verringert.\n[q]\"Von ihren bescheidenen Anfängen in Silbermond bis zu den Tiefen des Schwarzfels blieb Muze stets standhaft und brachte dank ihrer Heilkünste ihre Gefährten jedes Mal von der Schwelle des Todes zurück.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132451] = {name = "[q5]Mystischer Kilt des Runenmeisters", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 145 / 145\nKlassen: Magier\n[q2]Anlegen: 'Arkanbeschuss' erstattet Euch pro verbrauchter Arkaner Aufladung 3% Eures maximalen Manas zurück.\n[q]\"Obwohl die Halbriesen von Nordend von Natur aus keine oder so gut wie keine Magie verwenden, sind die mystischen Vrykul von Sturmheim wahre Meister der Runenmagie.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132452] = {name = "[q5]Sephuz' Geheimnis", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 10.\n[q2]Erhöht Eure Tempowertung um + 4.\n\n[q0]Prismatischer Sockel\n[q2]Anlegen: Erhöht Eure Bewegungsgeschwindigkeit um 10% und Euer Tempo um 2%. Wenn Ihr einen Gegner erfolgreich mit einem Kontrollverlusteffekt belegt, ihn unterbrecht oder einen Effekt von einem Ziel bannt, erhöht dieser Effekt stattdessen für 10 Sek. Eure Bewegungsgeschwindigkeit um 70% und Euer Tempo um 25%. Kann nur einmal alle 30 Sek. auftreten.\n[q]\"Die Nichtgreifbarkeit ist ein seltsames Konzept. Das Wort selbst lässt auf eine magische Fähigkeit schließen, aber in der physischen Welt steht es lediglich für die Macht, hier oder dort zu sein, jetzt oder später.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132453] = {name = "[q5]Blutrippenknochenbeinplatten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Beine} {Platte}\n16 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 6.\nHaltbarkeit 145 / 145\nKlassen: Todesritter\n[q2]Anlegen: 'Knochenschild' erhöht Eure Rüstung zusätzlich um 10% und Eure maximale Runenmacht um 60.\n[q]\"Teile des wandelnden Schreckens Blutrippe sind immer noch von nekromantischer Energie erfüllt, die dem Willen all jener gehorcht, die stark genug sind, sie zu kontrollieren.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132454] = {name = "[q5]Koralons brennende Berührung", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 4.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Magier\n[q2]Anlegen: 'Versengen' verursacht 350% mehr Schaden und trifft Gegner mit weniger als 30% Gesundheit garantiert kritisch.\n[q]\"Tief unten in der von Tausendwinter geschützten Kammer entfachten Eindringlinge stets aufs Neue den Zorn von Koralon dem Flammenwächter.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132455] = {name = "[q5]Norgannons Weitsicht", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Füße} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 95 / 95\nKlassen: Priester , Magier , Hexenmeister\n[q2]Anlegen: Wenn Ihr Euch 6 Sek. lang nicht bewegt, erhaltet Ihr 'Norgannons Weitsicht'. Diese erlaubt Euch 4 Sek. lang, Zauber aus der Bewegung heraus zu wirken. Die Dauer beginnt, sobald Ihr Euch bewegt.\n[q]\"Magie muss geregelt, verwaltet und kontrolliert werden. Aber sie muss auch geschätzt und in Ehren gehalten werden – nicht gierig gehamstert. Dieses Paradoxon müsst Ihr begreifen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132456] = {name = "[q5]Bahre der Seelen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\n[q2]Anlegen: Beim Wirken eines Schaden verursachenden Feuerzaubers besteht eine Chance von 6%, einen Seelensplitter zu erzeugen. (Procchance: 6%)\n[q]\"Aus verschiedenen Blickwinkeln betrachtet scheint die schwache Reflektion dreier unterschiedlicher Gesichter zu erkennen zu sein.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132457] = {name = "[q5]Lethtendris' Machtkordel", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 5.\nHaltbarkeit 70 / 70\nKlassen: Hexenmeister\n[q2]Anlegen: Wenn 'Instabiles Gebrechen' auf ein Ziel gewirkt wird, das noch nicht von 'Instabiles Gebrechen' betroffen ist, besteht eine Chance von 25%, dass Seelensplitterkosten zurückerstattet werden.\n[q]\"Lethtendris erschuf ein Gerät, um die verderbende Macht Düsterbruchs für sich selbst zu nutzen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132458] = {name = "[q5]Toravons Schneesturmbindungen", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\nHandgelenk Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 70 / 70\nKlassen: Todesritter\n[q2]Anlegen: Während 'Säule des Frosts' aktiv ist, wird der verursachte Frostschaden um 15% erhöht.\n[q]\"Tief unten in der von Tausendwinter geschützten Kammer zerschmetterte Toravon der Eiswächter unermüdlich alle Eindringlinge.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132459] = {name = "[q5]Beharrlichkeit des Schwarzen Märtyrers", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Platte}\n13 Rüstung\n+5 [Stärke oder Intelligenz]\n+7 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Todesritter\n[q2]Anlegen: 'Heulende Böe' fügt Gegnern, die kürzlich Schaden durch Eure Fähigkeit 'Unbarmherziger Winter' erlitten haben, 20% mehr Schaden zu.\n[q]\"Kalter Stahl wiegt schwer auf dem Haupt, das diese Krone trägt.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132460] = {name = "[q5]Alythess' Pyrogenik", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+4 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 8.\n[q2]Erhöht Eure Tempowertung um + 6.\n\n[q0]Prismatischer Sockel\n\nKlassen: Hexenmeister\n[q2]Anlegen: Durch Euren Zauber 'Feuerregen' betroffene Gegner erleiden um 10% erhöhten Schaden durch Eure Feuerzauber.\n[q]\"Leid... Hass... Chaos. Dies sind die Säulen.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132461] = {name = "[q5]Griff von Xalan dem Gefürchteten", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Hände} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Priester\n[q2]Anlegen: Wenn Eure 'Sühne' Schaden verursacht, wird die Effektdauer von 'Abbitte' auf Euch um 3 Sek. erhöht. Wenn sie heilt, wird die Effektdauer von 'Abbitte' stattdessen auf Eurem Ziel um 3 Sek. erhöht.\n[q]\"Während des Kriegs der Satyrn rissen die Nachtelfen Xalan dies glatt aus den Händen.\"\nVerkaufspreis:"}
