MultiLanguageItemData['de'][132861] = {name = "[q5]Estel, Dejahnas Inspiration", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Brust} {Stoff}\n5 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 200 / 200\nKlassen: Priester\n[q2]Anlegen: Erhöht die hervorgerufene Heilung um 3%.\n[q2]Anlegen: 'Bittgebet' erhöht Euer Tempo für jedes Ziel, das mit Eurer Fähigkeit 'Abbitte' belegt ist, 8 Sek. lang um 1%.\n[q]\"Der Glaube ist der Anfang aller Dinge. Ist das Talent für das Arkane zwar vorhanden, aber nicht gefestigt, kann man immer noch Zauberin werden. Aber ist der eigene Glaube lediglich vorhanden und nicht gefestigt, dann wird man niemals Priesterin.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132862] = {name = "Ring der Gefallenen", additional_info = "Questgegenstand\n[q]\"In den Ring ist ein schwarzer Opal eingesetzt, dessen neblige Wirbelstruktur etwas Seelenhaftes erkennen lässt.\""}
MultiLanguageItemData['de'][132863] = {name = "[q5]Darcklis Drachenfeuerdiadem", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Kopf} {Stoff}\n4 Rüstung\n+5 Intelligenz\n+7 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 6.\n[q2]Erhöht Eure Tempowertung um + 4.\nHaltbarkeit 120 / 120\nKlassen: Magier\n[q2]Anlegen: Erhöht den Schaden von 'Drachenodem' um 100% und die Reichweite um 25 Meter.\n[q]\"Zu den zahllosen Erfolgen von Erzmagier Darckli gehörte auch, dass er mit dem eigenen Mund Drachenfeuer speien konnte.\"\nVerkaufspreis:"}
MultiLanguageItemData['de'][132864] = {name = "[q5]Mangazas Wahnsinn", additional_info = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Legion - legendär (1)\n{Taille} {Stoff}\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 5.\n[q2]Erhöht Eure Tempowertung um + 3.\nHaltbarkeit 70 / 70\nKlassen: Priester\n[q2]Anlegen: Erhöht die maximale Anzahl von Aufladungen von 'Gedankenschlag' um 1.\n[q]\"Mangaza der Kaldorei war unter seinen Brüdern für seine Innovationen bekannt, so griff er mit Magie den Verstand seiner Feinde anstelle ihres Körpers an. Leider trieb dies schließlich nicht nur seine Opfer, sondern auch ihn selbst in den Wahnsinn.\"\nVerkaufspreis:"}
